/* Sinh tự động bởi docs/export-static.js — nguồn: screens/ */
TPL.bundle = {
  "admin/agents": "<!-- agents · Thành viên: bộ lọc + vùng bảng (bảng render động bằng d-02-table) -->\n<div class=\"card\"><div class=\"card-body\">\n  <div class=\"table-toolbar\">\n    <div class=\"field field-search\"><label class=\"field-label\" for=\"u-q\">Tìm kiếm</label><input class=\"input\" id=\"u-q\" placeholder=\"Tên, SĐT, ref_code, alias\" value=\"{{ f.q }}\" oninput=\"Admin.st.users.q=this.value; Admin.st.users.page=1; Admin.renderUsers()\"></div>\n    <div class=\"field\"><label class=\"field-label\" for=\"u-type\">Loại</label><select class=\"select\" id=\"u-type\" onchange=\"Admin.st.users.type=this.value; Admin.st.users.page=1; Admin.renderUsers()\"><option value=\"\">Tất cả</option><option value=\"agent\" {{ f.type === 'agent' ? 'selected' : '' }}>Thành viên</option><option value=\"buyer\" {{ f.type === 'buyer' ? 'selected' : '' }}>Người mua chưa đăng ký</option></select></div>\n    <div class=\"field\"><label class=\"field-label\" for=\"u-rank\">Hạng</label><select class=\"select\" id=\"u-rank\" onchange=\"Admin.st.users.rank=this.value; Admin.st.users.page=1; Admin.renderUsers()\"><option value=\"\">Tất cả</option>{% each r in CONFIG.ranks %}<option value=\"{{ r.id }}\" {{ f.rank === r.id ? 'selected' : '' }}>{{{ r.label }}}</option>{% endeach %}</select></div>\n    <div class=\"field\"><label class=\"field-label\" for=\"u-status\">Trạng thái</label><select class=\"select\" id=\"u-status\" onchange=\"Admin.st.users.status=this.value; Admin.st.users.page=1; Admin.renderUsers()\"><option value=\"\">Tất cả</option><option value=\"active\" {{ f.status === 'active' ? 'selected' : '' }}>Đang hoạt động</option><option value=\"locked\" {{ f.status === 'locked' ? 'selected' : '' }}>Đã khoá</option></select></div>\n    <div class=\"toolbar-actions\"><button class=\"btn btn-secondary\" onclick=\"Admin.exportUsers()\">{{{ icon('download', 16) }}} Xuất Excel</button></div>\n  </div>\n  <div id=\"u-table\">{{{ UI.skeletonTable(9, 6) }}}</div>\n</div></div>\n\n{% block admin/agents-drawer %}\n<!-- agents · Drawer chi tiết thành viên · part = 'title' | 'body' | 'foot' -->\n{% if part === 'title' %}\n<h2>{{ u.fullName }}</h2>\n<div class=\"row-wrap mt-1\">{{{ badge('userType', u.type) }}}{{{ u.rank ? badge('rank', u.rank) : '' }}}{{{ badge('user', u.status) }}}<span class=\"text-sm text-muted mono\">{{ u.id }}</span></div>\n\n{% elif part === 'body' %}\n<div class=\"section\">\n  <div class=\"section-title\">Hồ sơ</div>\n  <dl class=\"dl\">\n    <dt>SĐT</dt><dd class=\"mono\">{{ u.phone }}</dd>\n    <dt>Email</dt><dd>{{ u.email || '—' }}</dd>\n    <dt>Địa chỉ</dt><dd>{{ u.address || '—' }}</dd>\n    <dt>ref_code</dt><dd class=\"mono\">{{ u.refCode || '—' }}</dd>\n    <dt>Link cá nhân</dt><dd class=\"mono\">{% if u.purchaseAlias %}{{ RULES.publicPurchaseUrl(u.purchaseAlias) }}{% else %}—{% endif %}</dd>\n    <dt>TK nhận hoa hồng</dt><dd>{% if u.bank %}{{ u.bank.bankName }} · <span class=\"mono\">{{ u.bank.accountNo }}</span> · {{ u.bank.owner }}{% else %}—{% endif %}</dd>\n    <dt>T&C</dt><dd>{% if u.tcConsent %}v{{ u.tcConsent.version }} · {{ dt(u.tcConsent.at) }}{% else %}—{% endif %}</dd>\n    <dt>Tham gia</dt><dd>{{ dt(u.activatedAt || u.createdAt) }}</dd>\n    {% if u.status === 'locked' %}<dt>Lý do khoá</dt><dd class=\"text-error\">{{ u.lockedReason }} ({{ dt(u.lockedAt) }})</dd>{% endif %}\n  </dl>\n</div>\n\n{% if u.type === 'agent' %}\n<div class=\"section\">\n  <div class=\"row-between\">\n    <div class=\"section-title\">Hạng & điểm</div>\n    {% if head %}<button class=\"btn btn-secondary btn-sm\" onclick=\"Admin.assignRankModal('{{ u.id }}')\">{{{ icon('edit', 14) }}} Chỉ định hạng</button>{% endif %}\n  </div>\n  <dl class=\"dl\">\n    <dt>Hạng</dt><dd>{{{ badge('rank', u.rank) }}} từ {{ date(u.rankSince) }}</dd>\n    <dt>Luỹ kế / tháng này</dt><dd>{{{ u.cumulativeSales }}} gói · {{{ salesThisMonth }}} gói tháng này</dd>\n    <dt>Hoa hồng ghi nhận</dt><dd>{{ money(w.recorded) }} ({{ num(w.points) }} điểm)</dd>\n    <dt>Khả dụng / đang giữ / đã rút</dt><dd>{{ money(w.available) }} · {{ money(w.held) }} · {{ money(w.withdrawn) }}</dd>\n  </dl>\n  <div class=\"section-title mt-3\">Lịch sử thăng/giáng hạng</div>\n  <ul class=\"timeline\">\n    {% each h in rankHistory %}\n    <li><span class=\"timeline-time\">{{ dt(h.at) }}</span><span class=\"timeline-text\">{{{ badge('rankEvent', h.event) }}} {% if h.from %}{{{ RULES.rank(h.from).label }}} → {% endif %}{{{ RULES.rank(h.to).label }}} · {{ h.reason || '' }} · {{ h.by || '' }}</span></li>\n    {% endeach %}\n  </ul>\n</div>\n{% endif %}\n\n<div class=\"section\">\n  <div class=\"section-title\">Tuyến trên (đến gốc)</div>\n  {% if chain.length %}\n  <ol class=\"stack-sm\" style=\"padding-left:20px\">\n    {% each c, i in chain %}\n    <li>F{{{ i + 1 }}}: <strong>{{ c.fullName }}</strong> {{{ badge('rank', c.rank) }}} <span class=\"mono text-muted\">{{ c.refCode }}</span></li>\n    {% endeach %}\n  </ol>\n  {% else %}\n  <p class=\"text-muted\">Không có (thành viên gốc)</p>\n  {% endif %}\n</div>\n\n<div class=\"section\">\n  <div class=\"section-title\">Cây tuyến dưới (3 cấp)</div>\n  {% if tree.length %}{{{ include('partials/admin-tree', { nodes: tree }) }}}{% else %}<p class=\"text-muted\">Chưa có</p>{% endif %}\n</div>\n\n<div class=\"section\">\n  <div class=\"section-title\">Lịch sử đơn</div>\n  <dl class=\"dl\">\n    <dt>Đã mua</dt><dd>{{{ bought.length }}} đơn ({{{ boughtPaid }}} thanh toán)</dd>\n    <dt>Đã bán (qua link)</dt><dd>{{{ soldPaid }}} / {{{ sold.length }}}</dd>\n  </dl>\n  {% each o in soldRecent %}\n  <div class=\"row-between text-sm mt-2\"><span class=\"mono\">{{ o.id }}</span><span>{{ o.fullName }}</span>{{{ badge('orderStatus', o.status) }}}<button class=\"btn-link\" onclick=\"Admin.orderDrawer('{{ o.id }}')\">Xem</button></div>\n  {% endeach %}\n</div>\n\n{% if u.type === 'agent' %}\n<div class=\"section\">\n  <div class=\"section-title\">Lịch sử hoa hồng ({{{ cms.length }}})</div>\n  {% if cms.length %}\n  <div class=\"table-wrap\"><table class=\"table\" style=\"min-width:0\">\n    <thead><tr><th>Ngày</th><th>Đơn</th><th>Nguồn</th><th class=\"num\">Số tiền</th></tr></thead>\n    <tbody>\n    {% each c in cmsRecent %}\n      <tr><td>{{ date(c.createdAt) }}</td><td class=\"mono\">{{ c.orderId }}</td><td>{{{ c.source }}} · {{{ RULES.rank(c.rankAtCalc).label }}}</td><td class=\"num mono\">{{ money(c.amount) }}</td></tr>\n    {% endeach %}\n    </tbody>\n  </table></div>\n  {% else %}\n  <p class=\"text-muted\">Chưa có</p>\n  {% endif %}\n</div>\n{% endif %}\n\n<div class=\"section\">\n  <div class=\"section-title\">Nhật ký & audit</div>\n  {{{ include('partials/admin-audit-list', { list: audit }) }}}\n  <ul class=\"timeline mt-2\">\n    {% each l in logs %}\n    <li><span class=\"timeline-time\">{{ dt(l.at) }}</span><span class=\"timeline-text\">{{ l.text }}</span></li>\n    {% endeach %}\n  </ul>\n</div>\n\n{% elif part === 'foot' %}\n{% if head && u.type === 'agent' %}<button class=\"btn btn-secondary\" onclick=\"Admin.changeReferrerModal('{{ u.id }}')\">{{{ icon('users', 16) }}} Đổi người giới thiệu</button>{% endif %}\n{% if u.status === 'active' %}\n<button class=\"btn btn-danger-outline\" onclick=\"Admin.lockUser('{{ u.id }}')\">{{{ icon('lock', 16) }}} Khoá</button>\n{% else %}\n<button class=\"btn btn-success\" onclick=\"Admin.unlockUser('{{ u.id }}')\">{{{ icon('unlock', 16) }}} Mở khoá</button>\n{% endif %}\n{% endif %}\n{% endblock %}\n\n{% block admin/agents-modal-rank %}\n<!-- agents · Modal chỉ định hạng (Head Admin) · part = 'body' | 'foot' -->\n{% if part === 'body' %}\n<p class=\"text-muted\">{{ u.fullName }} · hiện tại {{{ RULES.rank(u.rank).label }}} · luỹ kế {{{ u.cumulativeSales }}} gói</p>\n<div class=\"mt-4\">{{{ UI.field({ id: 'ar-rank', label: 'Hạng mới', type: 'select', value: u.rank, options: CONFIG.ranks.map(r => ({ value: r.id, label: r.label + ' (ngưỡng ' + r.threshold + ')' })) }) }}}</div>\n<div class=\"mt-4\">{{{ UI.field({ id: 'ar-reason', label: 'Lý do', required: true, type: 'textarea', rows: 2 }) }}}</div>\n{% elif part === 'foot' %}\n<button class=\"btn btn-secondary\" onclick=\"UI.closeModal()\">Huỷ</button>\n<button class=\"btn btn-primary\" onclick=\"Admin.assignRank('{{ u.id }}')\">Chỉ định</button>\n{% endif %}\n{% endblock %}\n\n{% block admin/agents-modal-referrer %}\n<!-- agents · Modal đổi người giới thiệu (Head Admin) · part = 'body' | 'foot' -->\n{% if part === 'body' %}\n<p class=\"text-muted\">{{ u.fullName }} · hiện tại: {% if cur %}{{ cur.fullName }} (<span class=\"mono\">{{ cur.refCode }}</span>){% else %}không có{% endif %}</p>\n<div class=\"alert alert-warning mt-3\">{{{ icon('warning', 18) }}}<div class=\"text-sm\">Nguyên tắc chương trình: tuyến được gán 100% chính xác và khoá tại thời điểm mua. Thao tác này là ngoại lệ, chỉ ảnh hưởng đơn phát sinh sau thời điểm đổi, bắt buộc lý do và được ghi audit.</div></div>\n<div class=\"mt-4\">{{{ UI.field({ id: 'cr-code', label: 'ref_code người giới thiệu mới', required: true, mono: true, placeholder: 'VD: BINH88' }) }}}</div>\n<div class=\"mt-4\">{{{ UI.field({ id: 'cr-reason', label: 'Lý do', required: true, type: 'textarea', rows: 2 }) }}}</div>\n{% elif part === 'foot' %}\n<button class=\"btn btn-secondary\" onclick=\"UI.closeModal()\">Huỷ</button>\n<button class=\"btn btn-primary\" onclick=\"Admin.changeReferrer('{{ u.id }}')\">Xác nhận đổi</button>\n{% endif %}\n{% endblock %}\n\n{% block admin/agents-modal-root %}\n<!-- agents · Modal tạo thành viên gốc (Head Admin) · part = 'body' | 'foot' -->\n{% if part === 'body' %}\n<p class=\"text-sm text-muted\">Thành viên gốc được kích hoạt ngay, không qua mua hàng và duyệt hồ sơ. Dùng cho đại lý đầu mối.</p>\n<form class=\"form-grid form-grid-2 mt-3\" novalidate>\n  {{{ UI.field({ id: 'ra-name', label: 'Họ và tên', required: true }) }}}\n  {{{ UI.field({ id: 'ra-phone', label: 'Số điện thoại', required: true, mono: true }) }}}\n  {{{ UI.field({ id: 'ra-email', label: 'Email', required: true, type: 'email' }) }}}\n  {{{ UI.field({ id: 'ra-rank', label: 'Hạng khởi điểm', type: 'select', value: 'COPPER', options: CONFIG.ranks.map(r => ({ value: r.id, label: r.label })) }) }}}\n  {{{ UI.field({ id: 'ra-bank', label: 'Ngân hàng', type: 'select', value: CONFIG.banks[0], options: CONFIG.banks.map(b => ({ value: b, label: b })) }) }}}\n  {{{ UI.field({ id: 'ra-acc', label: 'Số tài khoản', mono: true }) }}}\n  {{{ UI.field({ id: 'ra-owner', label: 'Chủ tài khoản' }) }}}\n  {{{ UI.field({ id: 'ra-ref', label: 'ref_code tuyến trên (nếu có)', mono: true, placeholder: 'để trống = gốc' }) }}}\n  {{{ UI.field({ id: 'ra-pw', label: 'Mật khẩu tạm', required: true, value: CONFIG.demo.agentPassword }) }}}\n  <div style=\"grid-column:1/-1\">{{{ UI.field({ id: 'ra-reason', label: 'Lý do', required: true, type: 'textarea', rows: 2 }) }}}</div>\n</form>\n{% elif part === 'foot' %}\n<button class=\"btn btn-secondary\" onclick=\"UI.closeModal()\">Huỷ</button>\n<button class=\"btn btn-primary\" onclick=\"Admin.createRootAgent()\">Tạo thành viên</button>\n{% endif %}\n{% endblock %}\n\n{% block admin/agents-table %}\n<!-- agents · Bảng thành viên: rows = [{ u, ref, sold, downline }], pg = UI.paginate(...) -->\n{% if !rows.length %}\n{{{ UI.empty('users', 'Không có người dùng phù hợp', 'Thử bỏ bớt bộ lọc.', '<button class=\"btn btn-secondary\" onclick=\"Admin.st.users={q:\\'\\',type:\\'\\',rank:\\'\\',status:\\'\\',page:1}; App.reload()\">Xoá bộ lọc</button>') }}}\n{% else %}\n<div class=\"table-wrap\"><table class=\"table\">\n  <thead><tr><th>Thành viên</th><th>Loại</th><th>ref_code</th><th>Link cá nhân</th><th>Tuyến trên</th><th>Hạng</th><th class=\"num\">Đơn đã bán</th><th class=\"num\">Tuyến dưới</th><th>Tham gia</th><th>Trạng thái</th><th></th></tr></thead>\n  <tbody>\n  {% each row in rows %}\n  {% set u = row.u %}\n    <tr>\n      <td><span class=\"cell-main\">{{ u.fullName }}</span><span class=\"cell-sub mono\">{{ u.phone }}</span></td>\n      <td>{{{ badge('userType', u.type) }}}</td>\n      <td class=\"mono\">{{ u.refCode || '—' }}</td>\n      <td class=\"mono\">{{ u.purchaseAlias || '—' }}</td>\n      <td>{% if row.ref %}{{ row.ref.fullName }}<span class=\"cell-sub mono\">{{ row.ref.refCode }}</span>{% else %}—{% endif %}</td>\n      <td>{{{ u.rank ? badge('rank', u.rank) : '—' }}}</td>\n      <td class=\"num\">{{{ row.sold }}}{% if u.type === 'agent' %}<span class=\"cell-sub\">luỹ kế {{{ u.cumulativeSales }}}</span>{% endif %}</td>\n      <td class=\"num\">{{{ row.downline }}}</td>\n      <td>{{ date(u.activatedAt || u.createdAt) }}</td>\n      <td>{{{ badge('user', u.status) }}}</td>\n      <td><div class=\"row-actions\"><button class=\"btn btn-secondary btn-sm\" onclick=\"Admin.userDrawer('{{ u.id }}')\">Chi tiết</button></div></td>\n    </tr>\n  {% endeach %}\n  </tbody>\n</table></div>\n{{{ UI.pagination(pg, 'Admin.gotoUsers') }}}\n{% endif %}\n{% endblock %}\n",
  "admin/dashboard": "<!-- admin-dashboard · Tổng quan: thống kê kỳ, biểu đồ doanh thu, job xét hạng, việc cần làm -->\n<div class=\"stack-lg\">\n  <div class=\"row-between\">\n    <p class=\"text-muted\">Số liệu {{{ days }}} ngày gần nhất</p>\n    {{{ include('partials/admin-period-seg', { period: period, periods: periods }) }}}\n  </div>\n\n  <div class=\"stat-grid stat-grid-6\">\n    <div class=\"stat stat-navy\"><div class=\"stat-label\">{{{ icon('bars', 16) }}} Doanh thu</div><div class=\"stat-value\">{{{ money(s.revenue) }}}</div><div class=\"stat-sub\">{{{ s.paid }}} đơn thanh toán · về công ty {{{ money(s.companyCommission) }}}</div></div>\n    <div class=\"stat\"><div class=\"stat-label\">{{{ icon('inbox', 16) }}} Số đơn</div><div class=\"stat-value\">{{{ num(s.orders) }}}</div></div>\n    <div class=\"stat\"><div class=\"stat-label\">{{{ icon('users', 16) }}} Thành viên mới</div><div class=\"stat-value\">{{{ num(s.newAgents) }}}</div><div class=\"stat-sub\">{{{ totalAgents }}} thành viên tổng</div></div>\n    <div class=\"stat stat-clickable {{ s.regPending ? 'stat-accent' : '' }}\" onclick=\"App.navigate('registrations')\"><div class=\"stat-label\">{{{ icon('user', 16) }}} Đăng ký chờ duyệt</div><div class=\"stat-value {{ s.regPending ? 'text-warning' : '' }}\">{{{ num(s.regPending) }}}</div></div>\n    <div class=\"stat stat-clickable\" onclick=\"App.navigate('withdrawals?tab=withdraw')\"><div class=\"stat-label\">{{{ icon('cash', 16) }}} Rút tiền chờ duyệt</div><div class=\"stat-value {{ s.withdrawPending ? 'text-warning' : '' }}\">{{{ num(s.withdrawPending) }}}</div><div class=\"stat-sub\">{{{ s.withdrawApproved }}} chờ chi trả</div></div>\n    <div class=\"stat stat-clickable\" onclick=\"App.navigate('inventory')\"><div class=\"stat-label\">{{{ icon('key', 16) }}} Mã còn trong kho</div><div class=\"stat-value {{ s.stock <= CONFIG.stock.lowThreshold ? 'text-warning' : '' }}\">{{{ num(s.stock) }}}</div></div>\n  </div>\n\n  <div class=\"split-2\">\n    <div class=\"stack\">\n      <div class=\"card\">\n        <div class=\"card-head\"><h2>Doanh thu theo ngày (triệu đồng)</h2></div>\n        <div class=\"card-body\">{{{ UI.chart.combo(series, { height: 240, barName: 'triệu đ', yFormat: (v) => Math.round(v), accent: true, aria: 'Doanh thu theo ngày' }) }}}</div>\n      </div>\n      <div class=\"card\">\n        <div class=\"card-head\"><h2>Job xét hạng cuối tháng</h2><span class=\"text-sm text-muted\">{{ rules.rankRules.jobTime || CONFIG.rankRules.jobTime }} · tự động</span></div>\n        <div class=\"card-body\">\n          <p><strong>{{{ s.noSaleAgents }}}</strong> thành viên chưa bán đủ {{{ rules.rankRules.minSalesPerMonth }}} gói trong tháng này (sẽ giáng 1 bậc nếu không phát sinh đơn). Thành viên đủ luỹ kế sẽ được thăng thẳng lên hạng tương ứng.</p>\n          {% if head %}\n          <div class=\"actions actions-row\"><button class=\"btn btn-primary\" onclick=\"Admin.runJob()\">{{{ icon('zap', 18) }}} Chạy xét hạng ngay (mô phỏng)</button></div>\n          {% else %}\n          <p class=\"text-caption mt-2\">Chỉ Head Admin mới chạy thủ công.</p>\n          {% endif %}\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-head\"><h2>Việc cần làm</h2><span class=\"badge badge-warning\">{{{ todo.length }}}</span></div>\n      <div class=\"card-body\">\n        {% if todo.length %}\n        <ul class=\"todo-list\">\n          {% each t in todo %}\n          <li><span class=\"todo-count\">{{{ t.count }}}</span><div class=\"todo-text\">{{{ t.title }}}<small>{{{ t.sub }}}</small></div><a class=\"btn btn-secondary btn-sm\" href=\"#{{{ t.href }}}\">Xử lý {{{ icon('arrow-right', 14) }}}</a></li>\n          {% endeach %}\n        </ul>\n        {% else %}\n        {{{ UI.empty('check-circle', 'Không có việc tồn đọng') }}}\n        {% endif %}\n      </div>\n    </div>\n  </div>\n</div>\n\n{% block admin/dashboard-job-result %}\n<!-- admin-dashboard · Modal kết quả job xét hạng (r = Store.runMonthEndJob) · part = 'body' | 'foot' -->\n{% if part === 'body' %}\n<div class=\"stack\">\n  <div class=\"alert alert-success\">{{{ icon('check-circle', 18) }}}<div><strong>{{{ r.promoted.length }}}</strong> thăng hạng · <strong>{{{ r.demoted.length }}}</strong> giáng hạng</div></div>\n  {% if r.promoted.length %}\n  <h3>Thăng hạng</h3>\n  <ul class=\"stack-sm\" style=\"padding-left:18px\">\n    {% each p in r.promoted %}\n    <li>{{ p.user.fullName }}: {{{ RULES.rank(p.from).label }}} → <strong>{{{ RULES.rank(p.to).label }}}</strong> (luỹ kế {{{ p.user.cumulativeSales }}})</li>\n    {% endeach %}\n  </ul>\n  {% endif %}\n  {% if r.demoted.length %}\n  <h3>Giáng hạng</h3>\n  <ul class=\"stack-sm\" style=\"padding-left:18px\">\n    {% each p in r.demoted %}\n    <li>{{ p.user.fullName }}: {{{ RULES.rank(p.from).label }}} → <strong>{{{ RULES.rank(p.to).label }}}</strong></li>\n    {% endeach %}\n  </ul>\n  {% endif %}\n</div>\n{% elif part === 'foot' %}\n<button class=\"btn btn-primary\" onclick=\"UI.closeModal(); App.reload()\">Đóng</button>\n{% endif %}\n{% endblock %}\n",
  "admin/exceptions": "<!-- exceptions · Cấp phát ngoại lệ (ẩn khi CONFIG.rules.onePackagePerPhone = false) -->\n<div class=\"card\"><div class=\"card-body\">\n  {{{ UI.empty('gift', 'Quy tắc 1 gói / 1 SĐT đang tắt', 'Bật CONFIG.rules.onePackagePerPhone để dùng màn này.') }}}\n</div></div>\n",
  "admin/inventory": "<!-- inventory · Kho mã & thiết bị: cảnh báo, thống kê, bộ lọc + vùng bảng (bảng render động bằng d-05-table) -->\n<!-- cnt = { IN_STOCK, ASSIGNED, ACTIVATED } · low · pendingOrders · total · pct · f = Admin.st.codes -->\n<div class=\"stack-lg\">\n  {% if low %}\n  <div class=\"alert alert-warning\" role=\"alert\">{{{ icon('warning', 20) }}}<div><span class=\"alert-title\">Kho sắp cạn</span>Còn {{{ cnt.IN_STOCK }}} mã sẵn hàng (ngưỡng {{{ CONFIG.stock.lowThreshold }}}).</div></div>\n  {% endif %}\n  {% if pendingOrders %}\n  <div class=\"alert alert-error\" role=\"alert\">{{{ icon('alert-octagon', 20) }}}<div class=\"row-between grow\"><span><span class=\"alert-title\">{{{ pendingOrders }}} đơn đã thanh toán chờ gắn mã</span></span><button class=\"btn btn-primary btn-sm\" {{{ cnt.IN_STOCK ? '' : 'disabled' }}} onclick=\"UI.toast('Đã gắn mã cho ' + Store.fulfilPendingLicenses() + ' đơn.'); App.reload()\">Gắn mã cho đơn chờ</button></div></div>\n  {% endif %}\n\n  <div class=\"stat-grid\" style=\"grid-template-columns:repeat(4,1fr)\">\n    <div class=\"stat {{ low ? 'stat-accent' : '' }}\"><div class=\"stat-label\">{{{ icon('key', 16) }}} Sẵn hàng</div><div class=\"stat-value {{ low ? 'text-warning' : '' }}\">{{{ num(cnt.IN_STOCK) }}}</div><div class=\"progress mt-2 {{ low ? 'is-low' : '' }}\"><span style=\"width:{{{ pct }}}%\"></span></div></div>\n    <div class=\"stat\"><div class=\"stat-label\">{{{ icon('inbox', 16) }}} Đã gắn đơn hàng</div><div class=\"stat-value\">{{{ num(cnt.ASSIGNED) }}}</div></div>\n    <div class=\"stat\"><div class=\"stat-label\">{{{ icon('device', 16) }}} Đã kích hoạt</div><div class=\"stat-value\">{{{ num(cnt.ACTIVATED) }}}</div></div>\n    <div class=\"stat stat-navy\"><div class=\"stat-label\">Σ tổng</div><div class=\"stat-value\">{{{ num(total) }}}</div><div class=\"stat-sub\">{{{ cnt.IN_STOCK }}} + {{{ cnt.ASSIGNED }}} + {{{ cnt.ACTIVATED }}} = {{{ total }}} ✓</div></div>\n  </div>\n\n  <div class=\"card\"><div class=\"card-body\">\n    <div class=\"table-toolbar\">\n      <div class=\"field field-search\"><label class=\"field-label\" for=\"k-q\">Tìm mã / serial / đơn / lô</label><input class=\"input input-mono\" id=\"k-q\" value=\"{{ f.q }}\" oninput=\"Admin.st.codes.q=this.value; Admin.st.codes.page=1; Admin.renderCodes()\"></div>\n      <div class=\"field\"><label class=\"field-label\" for=\"k-status\">Trạng thái</label><select class=\"select\" id=\"k-status\" onchange=\"Admin.st.codes.status=this.value; Admin.st.codes.page=1; Admin.renderCodes()\"><option value=\"\">Tất cả</option>{% each k in ['IN_STOCK', 'ASSIGNED', 'ACTIVATED'] %}<option value=\"{{ k }}\" {{ f.status === k ? 'selected' : '' }}>{{{ LABELS.license[k].text }}}</option>{% endeach %}</select></div>\n      <div class=\"toolbar-actions\"><button class=\"btn btn-secondary\" onclick=\"Admin.exportCodes()\">{{{ icon('download', 16) }}} Xuất Excel</button></div>\n    </div>\n    <div id=\"k-table\">{{{ UI.skeletonTable(7, 8) }}}</div>\n  </div></div>\n</div>\n\n{% block admin/inventory-drawer %}\n<!-- inventory · Drawer chi tiết mã kích hoạt: c = Store.codeInfo, o (đơn), a (thành viên bán), stepIdx · part = 'title' | 'body' | 'foot' -->\n{% if part === 'title' %}\n<h2 class=\"mono\">{{ c.code }}</h2>\n<div class=\"row-wrap mt-1\">{{{ badge('license', c.status, true) }}}<span class=\"mono text-sm text-muted\">{{ c.deviceSku }} · {{ c.deviceSerial || '' }}</span></div>\n\n{% elif part === 'body' %}\n<div class=\"section\">\n  <div class=\"section-title\">Vòng đời (một chiều)</div>\n  <div class=\"steps\">\n    {% each s, i in ['IN_STOCK', 'ASSIGNED', 'ACTIVATED'] %}\n    <div class=\"step {{ c.status === s ? 'is-active' : '' }} {{ stepIdx > i ? 'is-done' : '' }}\"><span class=\"step-dot\">{{{ i + 1 }}}</span><span>{{{ LABELS.license[s].text }}}</span></div>\n    {% if i < 2 %}<span class=\"step-line\"></span>{% endif %}\n    {% endeach %}\n  </div>\n  <dl class=\"dl mt-4\">\n    <dt>Nhập kho</dt><dd>{{ dt(c.stockedAt) }} · lô {{ c.batch }}</dd>\n    <dt>Gắn đơn</dt><dd>{% if c.assignedAt %}{{ dt(c.assignedAt) }} · <span class=\"mono\">{{ c.orderId }}</span>{% else %}—{% endif %}</dd>\n    <dt>Thành viên bán</dt><dd>{% if a %}{{ a.fullName }} · {{{ badge('rank', a.rank) }}}{% else %}—{% endif %}</dd>\n    <dt>Người mua</dt><dd>{% if o %}{{ o.fullName }} · <span class=\"mono\">{{ o.phone }}</span>{% else %}—{% endif %}</dd>\n    <dt>Kích hoạt</dt><dd>{% if c.activatedAt %}{{ dt(c.activatedAt) }} · {{ c.device.name }} · <span class=\"mono\">{{ c.device.deviceId }}</span>{% else %}—{% endif %}</dd>\n  </dl>\n</div>\n\n{% elif part === 'foot' %}\n{% if c.status === 'ASSIGNED' %}\n<button class=\"btn btn-primary\" onclick=\"Store.activateCode('{{ c.code }}', { name: 'Samsung Galaxy A54 (mô phỏng)' }); UI.toast('Đã mô phỏng kích hoạt từ app.'); Admin.renderCodes(); Admin.codeDrawer('{{ c.code }}')\">{{{ icon('device', 16) }}} Mô phỏng kích hoạt từ app</button>\n{% endif %}\n{% if o %}<button class=\"btn btn-secondary\" onclick=\"Admin.orderDrawer('{{ o.id }}')\">Xem đơn</button>{% endif %}\n{% endif %}\n{% endblock %}\n\n{% block admin/inventory-modal-generate %}\n<!-- inventory · Modal sinh mã hàng loạt · part = 'body' | 'foot' -->\n{% if part === 'body' %}\n{{{ UI.field({ id: 'gen-n', label: 'Số lượng', required: true, mono: true, value: 100, attrs: 'inputmode=\"numeric\"' }) }}}\n<div class=\"mt-4\">{{{ UI.field({ id: 'gen-sku', label: 'Mã sản phẩm thiết bị', required: true, mono: true, value: CONFIG.stock.deviceSku }) }}}</div>\n<p class=\"text-caption mt-2\">Serial sinh tự động dạng {{{ CONFIG.stock.deviceSku }}}-000001; mã kích hoạt {{{ CONFIG.stock.codePrefix }}}-XXXX-XXXX-XXXX không trùng.</p>\n{% elif part === 'foot' %}\n<button class=\"btn btn-secondary\" onclick=\"UI.closeModal()\">Huỷ</button>\n<button class=\"btn btn-primary\" onclick=\"Admin.generate()\">Sinh mã</button>\n{% endif %}\n{% endblock %}\n\n{% block admin/inventory-modal-import %}\n<!-- inventory · Modal nhập mã từ file / dán danh sách · part = 'body' | 'foot' -->\n{% if part === 'body' %}\n<div class=\"dropzone\" onclick=\"document.getElementById('imp-file').click()\">{{{ icon('upload', 28) }}}<div class=\"mt-2\">Chọn file .csv (mỗi dòng: mã kích hoạt;serial thiết bị)</div><input type=\"file\" id=\"imp-file\" accept=\".csv,.txt\" hidden onchange=\"Admin.readImportFile(this)\"></div>\n<div class=\"mt-4\">{{{ UI.field({ id: 'imp-sku', label: 'Mã sản phẩm thiết bị', mono: true, value: CONFIG.stock.deviceSku }) }}}</div>\n<div class=\"mt-4\">{{{ UI.field({ id: 'imp-text', label: 'Hoặc dán danh sách', type: 'textarea', rows: 5, placeholder: 'HOMI-AB12-CD34-EF56;HW01-001301\\nHOMI-…' }) }}}</div>\n{% elif part === 'foot' %}\n<button class=\"btn btn-secondary\" onclick=\"UI.closeModal()\">Huỷ</button>\n<button class=\"btn btn-primary\" onclick=\"Admin.importCodes()\">Nhập vào kho</button>\n{% endif %}\n{% endblock %}\n\n{% block admin/inventory-table %}\n<!-- inventory · Bảng kho mã: rows = [{ c, a (thành viên bán), hasOrder }], pg = UI.paginate(...) -->\n{% if !rows.length %}\n{{{ UI.empty('key', 'Không có mã phù hợp', 'Thử đổi bộ lọc hoặc từ khoá.') }}}\n{% else %}\n<div class=\"table-wrap\"><table class=\"table\">\n  <thead><tr><th>Mã sản phẩm</th><th>Mã kích hoạt</th><th>Đơn</th><th>Thành viên bán</th><th>Ngày nhập kho</th><th>Trạng thái</th><th></th></tr></thead>\n  <tbody>\n  {% each row in rows %}\n  {% set c = row.c %}\n    <tr>\n      <td><span class=\"cell-main mono\">{{ c.deviceSku }}</span><span class=\"cell-sub mono\">{{ c.deviceSerial || '' }}</span></td>\n      <td class=\"mono\">{{ c.code }}</td>\n      <td>{% if c.orderId %}{% if row.hasOrder %}<button class=\"btn-link mono\" onclick=\"Admin.orderDrawer('{{ c.orderId }}')\">{{ c.orderId }}</button>{% else %}<span class=\"mono\">{{ c.orderId }}</span>{% endif %}{% else %}—{% endif %}</td>\n      <td>{% if row.a %}{{ row.a.fullName }}{% else %}—{% endif %}</td>\n      <td>{{ date(c.stockedAt) }}<span class=\"cell-sub mono\">{{ c.batch }}</span></td>\n      <td>{{{ badge('license', c.status) }}}</td>\n      <td><div class=\"row-actions\"><button class=\"btn btn-secondary btn-sm\" onclick=\"Admin.codeDrawer('{{ c.code }}')\">Chi tiết</button></div></td>\n    </tr>\n  {% endeach %}\n  </tbody>\n</table></div>\n{{{ UI.pagination(pg, 'Admin.gotoCodes') }}}\n{% endif %}\n{% endblock %}\n",
  "admin/login": "<!-- admin-login · Đăng nhập quản trị -->\n<div class=\"admin-login\">\n  <div class=\"admin-login-side\">\n    <div>{{{ UI.logo({ size: 40, invert: true }) }}}</div>\n    <div>\n      <h2>Khu vực quản trị HOMI365</h2>\n      <p>Duyệt đăng ký thành viên, đối soát đơn hàng, quản lý kho mã & thiết bị, bảng hoa hồng theo hạng, duyệt rút tiền 2 lớp.</p>\n    </div>\n    <p class=\"text-sm\" style=\"color:var(--sky-200)\">{{ CONFIG.brand.company }}</p>\n  </div>\n  <div class=\"admin-login-form\">\n    <div class=\"card\"><div class=\"card-body\">\n      <h1>Đăng nhập quản trị</h1>\n      <p class=\"text-muted mt-1 mb-4\">Tài khoản do Head Admin cấp. Thành viên vui lòng đăng nhập tại <a href=\"#login\">cổng thành viên</a>.</p>\n      <form novalidate onsubmit=\"Admin.login(event)\">\n        {{{ UI.field({ id: 'ad-user', label: 'Tên đăng nhập', required: true, attrs: 'autocomplete=\"username\"' }) }}}\n        <div class=\"field mt-4\" id=\"ad-pass-field\">\n          <label class=\"field-label\" for=\"ad-pass\">Mật khẩu<span class=\"req\">*</span></label>\n          <div class=\"input-affix\"><input class=\"input\" type=\"password\" id=\"ad-pass\" autocomplete=\"current-password\" required><button type=\"button\" class=\"btn btn-ghost affix-btn\" aria-label=\"Hiện mật khẩu\" onclick=\"UI.togglePassword('ad-pass', this)\">{{{ icon('eye', 20) }}}</button></div>\n          <div class=\"field-error\" id=\"ad-pass-err\"></div>\n        </div>\n        <div id=\"ad-alert\" class=\"mt-4\" hidden></div>\n        <div class=\"actions\"><button class=\"btn btn-primary btn-lg btn-block\" id=\"ad-submit\">{{{ icon('lock', 18) }}} Đăng nhập</button></div>\n      </form>\n      <div class=\"demo-hint\">Demo: <strong>head</strong> (Head Admin) · <strong>admin</strong> · <strong>admin2</strong> (Specialist) / mật khẩu <strong>{{{ CONFIG.admin.accounts[0].password }}}</strong></div>\n    </div></div>\n  </div>\n</div>\n\n{% block admin/login-alert %}\n<!-- admin-login · Thông báo đăng nhập thất bại (r = kết quả Store.adminLogin) -->\n{% if r.locked %}\n<div class=\"alert alert-error\" role=\"alert\">{{{ icon('lock', 20) }}}<div><span class=\"alert-title\">Tài khoản tạm khoá</span>Nhập sai quá {{{ CONFIG.admin.maxLoginFail }}} lần. Thử lại sau {{{ r.minutes }}} phút.</div></div>\n{% else %}\n<div class=\"alert alert-error\" role=\"alert\">{{{ icon('x-circle', 20) }}}<div>Tên đăng nhập hoặc mật khẩu không đúng (hoặc tài khoản bị vô hiệu). Còn {{{ r.remaining }}} lần thử.</div></div>\n{% endif %}\n{% endblock %}\n",
  "admin/orders": "<!-- orders · Đơn hàng & đối soát: tab + bộ lọc + vùng bảng (bảng render động bằng d-03-table) -->\n<div class=\"card\">\n  <div class=\"tabs\" role=\"tablist\" style=\"padding:0 20px\">\n    <button class=\"tab {{ f.tab === 'all' ? 'is-active' : '' }}\" onclick=\"Admin.st.orders.tab='all'; Admin.st.orders.page=1; App.reload()\">Tất cả đơn</button>\n    <button class=\"tab {{ f.tab === 'awaiting' ? 'is-active' : '' }}\" onclick=\"Admin.st.orders.tab='awaiting'; Admin.st.orders.page=1; App.reload()\">Chờ đối soát <span class=\"count\">{{{ awaiting }}}</span></button>\n    <button class=\"tab {{ f.tab === 'late' ? 'is-active' : '' }}\" onclick=\"Admin.st.orders.tab='late'; Admin.st.orders.page=1; App.reload()\">Callback sau hết hạn <span class=\"count\">{{{ late }}}</span></button>\n  </div>\n  <div class=\"card-body\">\n    {% if f.tab === 'awaiting' %}\n    <div class=\"alert alert-info mb-4\">{{{ icon('info', 18) }}}<div class=\"text-sm\">Đối chiếu sao kê theo <strong>nội dung CK = mã đơn</strong> và số tiền. Xác nhận → cấp mã (Đã gắn đơn hàng) + ghi nhận hoa hồng theo chuỗi tuyến ngay.</div></div>\n    {% endif %}\n    <div class=\"table-toolbar\">\n      <div class=\"field field-search\"><label class=\"field-label\" for=\"o-q\">Tìm kiếm</label><input class=\"input\" id=\"o-q\" placeholder=\"Mã đơn, tên, SĐT, ref_code\" value=\"{{ f.q }}\" oninput=\"Admin.st.orders.q=this.value; Admin.st.orders.page=1; Admin.renderOrders()\"></div>\n      {% if f.tab === 'all' %}\n      <div class=\"field\"><label class=\"field-label\" for=\"o-status\">Trạng thái</label><select class=\"select\" id=\"o-status\" onchange=\"Admin.st.orders.status=this.value; Admin.st.orders.page=1; Admin.renderOrders()\"><option value=\"\">Tất cả</option>{% each k in Object.keys(LABELS.orderStatus) %}<option value=\"{{ k }}\" {{ f.status === k ? 'selected' : '' }}>{{{ LABELS.orderStatus[k].text }}}</option>{% endeach %}</select></div>\n      {% endif %}\n      <div class=\"toolbar-actions\"><button class=\"btn btn-secondary\" onclick=\"Admin.exportOrders()\">{{{ icon('download', 16) }}} Xuất Excel</button></div>\n    </div>\n    <div id=\"o-table\">{{{ UI.skeletonTable(8, 6) }}}</div>\n  </div>\n</div>\n\n{% block admin/orders-allocation %}\n<!-- orders · Phân bổ hoa hồng theo chuỗi tuyến của một đơn: rows = [{ c, level, who, rate }], total, expected, ok -->\n{% if !rows.length %}\n<p class=\"text-muted\">Chưa có (đơn chưa thanh toán hoặc không có người bán).</p>\n{% else %}\n<div class=\"table-wrap\"><table class=\"table\" style=\"min-width:0\">\n  <thead><tr><th>Cấp</th><th>Người thụ hưởng</th><th>Hạng lúc tính</th><th class=\"num\">Mức hạng</th><th class=\"num\">Nhận</th><th>TT</th></tr></thead>\n  <tbody>\n  {% each row in rows %}\n    <tr>\n      <td>{{{ row.level }}}</td>\n      <td>{% if row.c.beneficiaryId === 'COMPANY' %}<strong>HOMI365</strong>{% else %}{{ row.who }}{% endif %}</td>\n      <td>{{{ badge('rank', row.c.rankAtCalc) }}}</td>\n      <td class=\"num mono\">{{ money(row.rate) }}</td>\n      <td class=\"num mono text-strong\">{{ money(row.c.amount) }}</td>\n      <td>{{{ badge('commission', row.c.status) }}}</td>\n    </tr>\n  {% endeach %}\n  </tbody>\n  <tfoot><tr><th colspan=\"4\">Tổng (kiểm: {{ money(expected) }})</th><th class=\"num {{ ok ? 'text-success' : 'text-error' }}\">{{ money(total) }}</th><th></th></tr></tfoot>\n</table></div>\n{% endif %}\n{% endblock %}\n\n{% block admin/orders-drawer %}\n<!-- orders · Drawer chi tiết đơn hàng · part = 'title' | 'body' | 'foot' -->\n{% if part === 'title' %}\n<h2 class=\"mono\">{{ o.id }}</h2>\n<div class=\"row-wrap mt-1\">{{{ badge('orderStatus', o.status) }}}{{{ o.status === 'PAID' ? badge('shipping', o.shipping) : '' }}}{% if o.flags && o.flags.lateCallback %}<span class=\"badge badge-warning\">Callback muộn</span>{% endif %}{% if o.refunded %}<span class=\"badge badge-error\">Đã hoàn tiền</span>{% endif %}</div>\n\n{% elif part === 'body' %}\n<div class=\"section\">\n  <div class=\"section-title\">Đơn hàng</div>\n  <dl class=\"dl\">\n    <dt>Gói</dt><dd>{{ pkg.fullName }}</dd>\n    <dt>Số tiền</dt><dd>{{ money(o.price) }}</dd>\n    <dt>Phương thức</dt><dd>{{ LABELS.method[o.method] || '—' }}</dd>\n    <dt>Tạo lúc</dt><dd>{{ dt(o.createdAt) }}</dd>\n    {% if o.paidAt %}<dt>Thanh toán lúc</dt><dd>{{ dt(o.paidAt) }}</dd>{% endif %}\n  </dl>\n</div>\n\n<div class=\"section\">\n  <div class=\"section-title\">Người mua & giao hàng</div>\n  <dl class=\"dl\">\n    <dt>Họ tên</dt><dd>{{ o.fullName }}</dd>\n    <dt>SĐT</dt><dd class=\"mono\">{{ o.phone }}</dd>\n    <dt>Email</dt><dd>{{ o.email || '—' }}</dd>\n    <dt>Địa chỉ</dt><dd>{{ o.address }}</dd>\n    <dt>Ghi chú</dt><dd>{{ o.note || '—' }}</dd>\n    <dt>Người bán</dt><dd>{% if s %}{{ s.fullName }} · <span class=\"mono\">{{ o.refCode }}</span> · {% if o.referrerRankAtOrder %}{{{ RULES.rank(o.referrerRankAtOrder).label }}} lúc đơn{% endif %}{% else %}—{% endif %}</dd>\n  </dl>\n  {% if o.status === 'PAID' && pkg.hasShipping %}\n  <div class=\"row-between mt-3\">\n    <span>Giao hàng: {{{ badge('shipping', o.shipping) }}}</span>\n    {% if next %}\n    <button class=\"btn btn-primary btn-sm\" onclick=\"Admin.updateShipping('{{ o.id }}', '{{ next }}')\">{{{ icon('truck', 16) }}} Chuyển sang \"{{{ RULES.shippingLabel(next) }}}\"</button>\n    {% else %}\n    <span class=\"text-sm text-success\">Đã giao xong</span>\n    {% endif %}\n  </div>\n  {% endif %}\n</div>\n\n<div class=\"section\">\n  <div class=\"section-title\">Mã kích hoạt & thiết bị</div>\n  {% if code %}\n  <div class=\"code-box\">\n    <div class=\"grow\"><span class=\"code-label\">{{{ label('license', code.status) }}} · {{ code.deviceSku }} {{ code.deviceSerial || '' }}</span><span class=\"code-value\">{{ code.code }}</span></div>\n    <button class=\"btn btn-secondary btn-icon\" aria-label=\"Sao chép\" onclick=\"UI.copy('{{{ code.code }}}')\">{{{ icon('copy', 18) }}}</button>\n  </div>\n  {% if code.device %}<p class=\"text-sm text-muted mt-2\">Thiết bị: {{ code.device.name }} · <span class=\"mono\">{{ code.device.deviceId }}</span> · {{ dt(code.activatedAt) }}</p>{% endif %}\n  {% elif o.status === 'PAID' %}\n  <div class=\"alert alert-warning\">{{{ icon('warning', 18) }}}<div class=\"text-sm\">Đã thanh toán nhưng chưa có mã (kho hết). <a href=\"#inventory\">Bổ sung kho</a>.</div></div>\n  {% else %}\n  <p class=\"text-muted\">Chưa gắn (đơn chưa thanh toán).</p>\n  {% endif %}\n</div>\n\n<div class=\"section\">\n  <div class=\"section-title\">Phân bổ hoa hồng theo chuỗi tuyến</div>\n  {{{ allocation }}}\n</div>\n\n<div class=\"section\">\n  <div class=\"section-title\">Dòng thời gian</div>\n  {{{ include('partials/admin-timeline', { rows: timeline }) }}}\n</div>\n\n{% elif part === 'foot' %}\n{% if o.status === 'AWAITING_RECONCILE' %}\n<button class=\"btn btn-danger-outline\" onclick=\"Admin.rejectReconcile('{{ o.id }}')\">Từ chối</button>\n<button class=\"btn btn-success\" onclick=\"Admin.confirmReconcile('{{ o.id }}')\">{{{ icon('check', 16) }}} Xác nhận đã nhận tiền</button>\n{% endif %}\n{% if o.flags && o.flags.lateCallback && !o.flags.lateChecked %}\n<button class=\"btn btn-secondary\" onclick=\"Store.clearLateFlag('{{ o.id }}'); UI.toast('Đã đánh dấu kiểm tra.'); App.reload()\">{{{ icon('check', 16) }}} Đã kiểm tra</button>\n{% endif %}\n{% if o.status === 'PAID' && !o.refunded %}\n<button class=\"btn btn-danger-outline\" onclick=\"Admin.refundOrder('{{ o.id }}')\">Hoàn tiền & huỷ hoa hồng</button>\n{% endif %}\n{% endif %}\n{% endblock %}\n\n{% block admin/orders-table %}\n<!-- orders · Bảng đơn hàng: rows = [{ o, s (người bán), c (mã KH) }], pg = UI.paginate(...) -->\n{% if !rows.length %}\n{{{ UI.empty('inbox', 'Không có đơn phù hợp') }}}\n{% else %}\n<div class=\"table-wrap\"><table class=\"table\">\n  <thead><tr><th>Mã đơn</th><th>Người mua</th><th>Người bán</th><th>Hạng lúc đơn</th><th>Phương thức</th><th class=\"num\">Số tiền</th><th>Thanh toán</th><th>Giao hàng</th><th>Mã KH</th><th></th></tr></thead>\n  <tbody>\n  {% each row in rows %}\n  {% set o = row.o %}\n    <tr>\n      <td><span class=\"cell-main mono\">{{ o.id }}</span><span class=\"cell-sub\">{{ dt(o.createdAt) }}</span></td>\n      <td><span class=\"cell-main\">{{ o.fullName }}</span><span class=\"cell-sub mono\">{{ o.phone }}</span></td>\n      <td>{% if row.s %}{{ row.s.fullName }}<span class=\"cell-sub mono\">{{ o.refCode }}</span>{% else %}—{% endif %}</td>\n      <td>{{{ o.referrerRankAtOrder ? badge('rank', o.referrerRankAtOrder) : '—' }}}</td>\n      <td>{{ LABELS.method[o.method] || '—' }}</td>\n      <td class=\"num mono\">{{ money(o.price) }}</td>\n      <td>{{{ badge('orderStatus', o.status) }}}{% if o.flags && o.flags.lateCallback && !o.flags.lateChecked %}<span class=\"cell-sub text-warning\">Callback muộn</span>{% endif %}{% if o.refunded %}<span class=\"cell-sub text-error\">Đã hoàn tiền</span>{% endif %}</td>\n      <td>{{{ o.status === 'PAID' ? badge('shipping', o.shipping) : '—' }}}</td>\n      <td>{{{ o.status === 'PAID' ? badge('license', row.c ? row.c.status : 'PENDING') : '—' }}}</td>\n      <td><div class=\"row-actions\">\n        {% if o.status === 'AWAITING_RECONCILE' %}\n        <button class=\"btn btn-success btn-sm\" onclick=\"Admin.confirmReconcile('{{ o.id }}')\">Xác nhận</button>\n        <button class=\"btn btn-danger-outline btn-sm\" onclick=\"Admin.rejectReconcile('{{ o.id }}')\">Từ chối</button>\n        {% endif %}\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"Admin.orderDrawer('{{ o.id }}')\">Chi tiết</button>\n      </div></td>\n    </tr>\n  {% endeach %}\n  </tbody>\n</table></div>\n{{{ UI.pagination(pg, 'Admin.gotoOrders') }}}\n{% endif %}\n{% endblock %}\n",
  "admin/products": "<!-- products · Sản phẩm & bảng hoa hồng 6 hạng: list = [{ p, total, versions }], top = RULES.topRank() -->\n<div class=\"stack-lg\">\n  <div class=\"alert alert-info\">{{{ icon('info', 18) }}}<div class=\"text-sm\">Mỗi gói có <strong>bảng hoa hồng theo 6 hạng</strong> (VNĐ/gói, tăng đơn điệu). Hoa hồng của một đơn = mức {{{ top.label }}}, chia theo chênh lệch hạng trên chuỗi tuyến; phần còn dư về công ty. Mỗi lần sửa lưu thành phiên bản có ngày hiệu lực.</div></div>\n\n  <div class=\"table-wrap\"><table class=\"table\">\n    <thead><tr><th>Mã</th><th>Tên gói</th><th class=\"num\">Giá</th><th>Ảnh</th><th class=\"num\">HH {{{ top.label }}}</th><th>Bảng HH</th><th>Cập nhật</th><th>Bán</th><th></th></tr></thead>\n    <tbody>\n    {% each row in list %}\n    {% set p = row.p %}\n      <tr>\n        <td class=\"mono text-strong\">{{ p.id }}</td>\n        <td><span class=\"cell-main\">{{ p.name }}</span><span class=\"cell-sub\">{{{ esc(p.desc).slice(0, 70) }}}…</span></td>\n        <td class=\"num mono\">{{ money(p.price) }}</td>\n        <td>{% if p.image %}<img src=\"{{ p.image }}\" alt=\"\" style=\"width:56px;height:36px;object-fit:cover;border-radius:4px\">{% else %}—{% endif %}</td>\n        <td class=\"num mono\">{{ money(row.total) }}</td>\n        <td><span class=\"text-sm\">{{{ row.versions }}} phiên bản</span></td>\n        <td>{{ date(p.updatedAt) }}</td>\n        <td>{% if p.active %}<span class=\"badge badge-success\">Đang bán</span>{% else %}<span class=\"badge badge-neutral\">Tắt</span>{% endif %}</td>\n        <td><div class=\"row-actions\">\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"Admin.packageForm('{{ p.id }}')\">{{{ icon('edit', 14) }}} Sửa</button>\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"Admin.commissionTableModal('{{ p.id }}')\">{{{ icon('layers', 14) }}} Bảng HH</button>\n          {% if p.active %}\n          <button class=\"btn btn-danger-outline btn-sm\" onclick=\"Admin.togglePackage('{{ p.id }}', false)\">Tắt bán</button>\n          {% else %}\n          <button class=\"btn btn-success btn-sm\" onclick=\"Admin.togglePackage('{{ p.id }}', true)\">Bật bán</button>\n          {% endif %}\n        </div></td>\n      </tr>\n    {% endeach %}\n    </tbody>\n  </table></div>\n\n  {% each row in list %}\n  <div class=\"card\">\n    <div class=\"card-head\"><h2>Bảng hoa hồng · {{ row.p.id }} {{ row.p.name }}</h2><button class=\"btn btn-primary btn-sm\" onclick=\"Admin.commissionTableModal('{{ row.p.id }}')\">{{{ icon('plus', 14) }}} Phiên bản mới</button></div>\n    <div class=\"card-body\">{{{ include('admin/products-commission-table', row.table) }}}</div>\n  </div>\n  {% endeach %}\n</div>\n\n{% block admin/products-commission-table %}\n<!-- products · Bảng hoa hồng hiện hành + lịch sử phiên bản của một gói (view-model từ Admin.commissionTableVm) -->\n<!-- rows = [{ r, amount, diff }] · versions = [{ v, isCurrent, state: 'upcoming' | 'current' | 'replaced', cells: [{ short, changed, prevK, curK }] }] -->\n<div class=\"table-wrap\"><table class=\"table\" style=\"min-width:0\">\n  <thead><tr><th>Hạng</th><th class=\"num\">Mức hoa hồng</th><th class=\"num\">Chênh lệch so với hạng dưới</th></tr></thead>\n  <tbody>\n  {% each row in rows %}\n    <tr><td>{{{ badge('rank', row.r.id) }}}</td><td class=\"num mono text-strong\">{{ money(row.amount) }}</td><td class=\"num mono\">{% if row.diff !== null %}+{{ money(row.diff) }}{% else %}—{% endif %}</td></tr>\n  {% endeach %}\n  </tbody>\n</table></div>\n\n<h3 class=\"mt-4 mb-2\">Lịch sử phiên bản</h3>\n{% if !versions.length %}\n<p class=\"text-muted\">Chưa có</p>\n{% endif %}\n{% each ver in versions %}\n{% set v = ver.v %}\n<div class=\"policy-version {{ ver.isCurrent ? 'is-current' : '' }}\">\n  <div class=\"row-between\">\n    <strong>v{{{ v.version }}}</strong>\n    {% if ver.state === 'upcoming' %}<span class=\"badge badge-info\">Sắp hiệu lực</span>{% elif ver.state === 'current' %}<span class=\"badge badge-success\">Đang áp dụng</span>{% else %}<span class=\"badge badge-neutral\">Đã thay thế</span>{% endif %}\n  </div>\n  <div class=\"text-sm text-muted\">Hiệu lực {{ date(v.effectiveFrom) }} · {{ v.by }} · {{ dt(v.at) }}</div>\n  <div class=\"text-sm mt-1\">{% each cell, i in ver.cells %}{% if i %} · {% endif %}<span class=\"mono\">{{{ cell.short }}} {% if cell.changed %}<span class=\"diff-del\">{{{ cell.prevK }}}k</span> <span class=\"diff-add\">{{{ cell.curK }}}k</span>{% else %}{{{ cell.curK }}}k{% endif %}</span>{% endeach %}</div>\n  {% if v.note %}<div class=\"text-sm text-muted mt-1\">\"{{ v.note }}\"</div>{% endif %}\n</div>\n{% endeach %}\n{% endblock %}\n\n{% block admin/products-modal-package %}\n<!-- products · Modal thêm / sửa gói sản phẩm: p (gói hoặc mặc định), editing (true khi sửa) · part = 'body' | 'foot' -->\n{% if part === 'body' %}\n<form class=\"form-grid form-grid-2\" novalidate>\n  {{{ UI.field({ id: 'pk-id', label: 'Mã gói', required: true, mono: true, value: p.id, attrs: editing ? 'readonly' : '' }) }}}\n  {{{ UI.field({ id: 'pk-name', label: 'Tên gói', required: true, value: p.name }) }}}\n  {{{ UI.field({ id: 'pk-price', label: 'Giá (đ)', required: true, mono: true, value: p.price, attrs: 'inputmode=\"numeric\"' }) }}}\n  {{{ UI.field({ id: 'pk-image', label: 'Ảnh (đường dẫn)', value: p.image || '', placeholder: './public/product/og-cover.png' }) }}}\n  <div style=\"grid-column:1/-1\">{{{ UI.field({ id: 'pk-full', label: 'Tên đầy đủ hiển thị', required: true, value: p.fullName }) }}}</div>\n  <div style=\"grid-column:1/-1\">{{{ UI.field({ id: 'pk-desc', label: 'Mô tả', type: 'textarea', rows: 2, value: p.desc }) }}}</div>\n  <div style=\"grid-column:1/-1\">{{{ UI.field({ id: 'pk-benefits', label: 'Quyền lợi (mỗi dòng một mục)', type: 'textarea', rows: 4, value: (p.benefits || []).join('\\n') }) }}}</div>\n  {{{ UI.field({ id: 'pk-months', label: 'Thời hạn license (tháng, tuỳ chọn)', mono: true, value: p.licenseMonths || '' }) }}}\n  <label class=\"check\"><input type=\"checkbox\" id=\"pk-ship\" {{{ p.hasShipping ? 'checked' : '' }}}> Có giao hàng vật lý</label>\n</form>\n{% if !editing %}<p class=\"text-caption mt-2\">Sau khi tạo, thêm bảng hoa hồng 6 hạng bằng nút \"Bảng HH\".</p>{% endif %}\n{% elif part === 'foot' %}\n<button class=\"btn btn-secondary\" onclick=\"UI.closeModal()\">Huỷ</button>\n<button class=\"btn btn-primary\" onclick=\"Admin.savePackage({{{ editing ? 'true' : 'false' }}})\">Lưu</button>\n{% endif %}\n{% endblock %}\n\n{% block admin/products-modal-table %}\n<!-- products · Modal tạo phiên bản bảng hoa hồng mới: rows = [{ r, value, diff }], today · part = 'body' | 'foot' -->\n{% if part === 'body' %}\n<div class=\"table-wrap\"><table class=\"table\" style=\"min-width:0\">\n  <thead><tr><th>Hạng</th><th>Mức hoa hồng (đ)</th><th class=\"num\">Chênh lệch</th></tr></thead>\n  <tbody>\n  {% each row in rows %}\n    <tr>\n      <td>{{{ badge('rank', row.r.id) }}}</td>\n      <td><input class=\"input input-mono\" id=\"ct-{{{ row.r.id }}}\" value=\"{{{ row.value }}}\" inputmode=\"numeric\" oninput=\"Admin.ctRecalc()\" aria-label=\"Mức {{{ row.r.label }}}\"></td>\n      <td class=\"num mono\" id=\"ct-diff-{{{ row.r.id }}}\">{% if row.diff !== null %}+{{ money(row.diff) }}{% else %}—{% endif %}</td>\n    </tr>\n  {% endeach %}\n  </tbody>\n</table></div>\n<div class=\"field-error mt-2\" id=\"ct-err\"></div>\n<div class=\"form-grid form-grid-2 mt-4\">\n  {{{ UI.field({ id: 'ct-eff', label: 'Ngày hiệu lực', required: true, type: 'date', value: today }) }}}\n  {{{ UI.field({ id: 'ct-note', label: 'Ghi chú phiên bản', placeholder: 'Lý do thay đổi…' }) }}}\n</div>\n<p class=\"text-caption mt-2\">Đơn thanh toán từ ngày hiệu lực áp dụng bảng mới; hoa hồng đã ghi nhận giữ nguyên.</p>\n{% elif part === 'foot' %}\n<button class=\"btn btn-secondary\" onclick=\"UI.closeModal()\">Huỷ</button>\n<button class=\"btn btn-primary\" onclick=\"Admin.saveCommissionTable('{{ p.id }}')\">Lưu phiên bản</button>\n{% endif %}\n{% endblock %}\n",
  "admin/ranks": "<!-- ranks · Hạng & quy tắc chương trình: r = Store.rules(), head = Head Admin?, tcNext = phiên bản T&C kế tiếp -->\n<div class=\"split-2 split-2-eq\">\n  <div class=\"stack\">\n    <div class=\"card\">\n      <div class=\"card-head\"><h2>Bảng hạng thành viên</h2><span class=\"text-sm text-muted\">Ngưỡng = tổng gói bán luỹ kế [cần xác nhận]</span></div>\n      <div class=\"card-body\">\n        <div class=\"table-wrap\"><table class=\"table\" style=\"min-width:0\">\n          <thead><tr><th>Hạng</th><th class=\"num\">Ngưỡng luỹ kế</th><th class=\"num\">Bước</th><th>Quyền tuyển thành viên</th></tr></thead>\n          <tbody>\n          {% each k, i in CONFIG.ranks %}\n            <tr><td>{{{ badge('rank', k.id) }}}</td><td class=\"num mono\">{{{ k.threshold }}} gói</td><td class=\"num mono\">{% if i %}+{{{ k.threshold - CONFIG.ranks[i - 1].threshold }}}{% else %}—{% endif %}</td><td>{% if k.canRecruit %}<span class=\"badge badge-success\">Được tuyển</span>{% else %}<span class=\"badge badge-neutral\">Chỉ bán</span>{% endif %}</td></tr>\n          {% endeach %}\n          </tbody>\n        </table></div>\n        <p class=\"text-caption mt-2\">Ngưỡng hạng cấu hình tại <span class=\"mono\">CONFIG.ranks</span> (chờ khách chốt 10/18/24/28/30).</p>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-head\"><h2>Quy tắc chương trình</h2></div>\n      <div class=\"card-body\">\n        <form novalidate onsubmit=\"Admin.saveRules(event)\">\n          <div class=\"form-grid form-grid-2\">\n            {{{ UI.field({ id: 'rl-min', label: 'Bán tối thiểu / tháng để giữ hạng', mono: true, value: r.rankRules.minSalesPerMonth, attrs: head ? '' : 'readonly' }) }}}\n            {{{ UI.field({ id: 'rl-steps', label: 'Số bậc giáng khi không đạt', mono: true, value: r.rankRules.demoteSteps, attrs: head ? '' : 'readonly' }) }}}\n            {{{ UI.field({ id: 'rl-maxwd', label: 'Số lần rút tối đa / tháng', mono: true, value: r.withdraw.maxPerMonth, attrs: head ? '' : 'readonly' }) }}}\n            {{{ UI.field({ id: 'rl-points', label: 'Tỷ lệ điểm (điểm / 1đ hoa hồng)', mono: true, value: CONFIG.points.perVnd, attrs: 'readonly' }) }}}\n            <div style=\"grid-column:1/-1\">{{{ UI.field({ id: 'rl-payout', label: 'Ghi chú thời điểm chi trả', value: r.withdraw.payoutNote, attrs: head ? '' : 'readonly' }) }}}</div>\n          </div>\n          <div class=\"check mt-3\"><input type=\"checkbox\" id=\"rl-reset\" {{{ r.rankRules.demoteResetsCumulative ? 'checked' : '' }}} {{{ head ? '' : 'disabled' }}}> Giáng hạng reset luỹ kế [cần xác nhận]</div>\n          {% if head %}\n          <div class=\"mt-4\">{{{ UI.field({ id: 'rl-note', label: 'Ghi chú thay đổi', placeholder: 'Lý do…' }) }}}</div>\n          <div class=\"actions\"><button class=\"btn btn-primary\">Lưu quy tắc</button></div>\n          {% else %}\n          <p class=\"text-caption mt-3\">Chỉ Head Admin được sửa.</p>\n          {% endif %}\n        </form>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"stack\">\n    <div class=\"card\">\n      <div class=\"card-head\"><h2>Điều khoản & điều kiện (T&C)</h2><span class=\"badge badge-navy badge-plain\">v{{ r.tc.version }} · {{ r.tc.updatedAt }}</span></div>\n      <div class=\"card-body\">\n        <form novalidate onsubmit=\"Admin.saveTc(event)\">\n          {{{ UI.field({ id: 'tc-ver', label: 'Phiên bản mới', mono: true, value: tcNext, attrs: head ? '' : 'readonly' }) }}}\n          <div class=\"mt-3\">{{{ UI.field({ id: 'tc-text', label: 'Nội dung', type: 'textarea', rows: 12, value: r.tc.text, attrs: head ? '' : 'readonly' }) }}}</div>\n          {% if head %}<div class=\"actions\"><button class=\"btn btn-primary\">Lưu T&C phiên bản mới</button></div>{% endif %}\n        </form>\n        <p class=\"text-caption mt-2\">Thành viên đăng ký sau ngày hiệu lực chấp nhận phiên bản mới; phiên bản đã chấp nhận lưu trong hồ sơ.</p>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-head\"><h2>Lịch sử thay đổi</h2></div>\n      <div class=\"card-body\">\n        <ul class=\"timeline\">\n          {% each h in history %}\n          <li><span class=\"timeline-time\">{{ dt(h.at) }}</span><span class=\"timeline-text\"><strong>{{ h.by }}</strong> · {{ h.note }}</span></li>\n          {% endeach %}\n        </ul>\n      </div>\n    </div>\n  </div>\n</div>\n",
  "admin/registrations": "<!-- registrations · Duyệt đăng ký thành viên: bộ lọc + vùng bảng (bảng render động bằng d-09-table) -->\n<div class=\"card\"><div class=\"card-body\">\n  <div class=\"alert alert-info mb-4\">{{{ icon('info', 18) }}}<div class=\"text-sm\">Duyệt <strong>2 lớp</strong> (người thứ 2 phải khác người thứ 1; Head Admin tự chốt). Khi <strong>Đã duyệt</strong>: tạo tài khoản thành viên hạng Copper, sinh ref_code + link cá nhân, gửi email kích hoạt. Duyệt không ảnh hưởng đơn, tuyến và hoa hồng đã ghi.</div></div>\n  <div class=\"table-toolbar\">\n    <div class=\"field field-search\"><label class=\"field-label\" for=\"rg-q\">Tìm kiếm</label><input class=\"input\" id=\"rg-q\" placeholder=\"Họ tên, SĐT, email\" value=\"{{ f.q }}\" oninput=\"Admin.st.regs.q=this.value; Admin.st.regs.page=1; Admin.renderRegs()\"></div>\n    <div class=\"field\"><label class=\"field-label\" for=\"rg-status\">Trạng thái</label><select class=\"select\" id=\"rg-status\" onchange=\"Admin.st.regs.status=this.value; Admin.st.regs.page=1; Admin.renderRegs()\"><option value=\"\">Tất cả</option>{% each k in Object.keys(LABELS.approval) %}<option value=\"{{ k }}\" {{ f.status === k ? 'selected' : '' }}>{{{ LABELS.approval[k].text }}}</option>{% endeach %}</select></div>\n  </div>\n  <div id=\"rg-table\">{{{ UI.skeletonTable(7, 5) }}}</div>\n</div></div>\n\n{% block admin/registrations-drawer %}\n<!-- registrations · Drawer chi tiết hồ sơ đăng ký: r, ref, refRankLabel, o (đơn gốc), agent, mail, timeline (html), audit (html), canApprove · part = 'title' | 'body' | 'foot' -->\n{% if part === 'title' %}\n<h2>{{ r.fullName }}</h2>\n<div class=\"row-wrap mt-1\">{{{ badge('approval', r.status, true) }}}<span class=\"mono text-sm text-muted\">{{ r.id }}</span></div>\n\n{% elif part === 'body' %}\n<div class=\"section\">\n  <div class=\"section-title\">Hồ sơ đã nộp</div>\n  <dl class=\"dl\">\n    <dt>SĐT</dt><dd class=\"mono\">{{ r.phone }}</dd>\n    <dt>Email</dt><dd>{{ r.email }}</dd>\n    <dt>Ngân hàng</dt><dd>{{ r.bank.bankName }} · <span class=\"mono\">{{ r.bank.accountNo }}</span> · {{ r.bank.owner }}</dd>\n    <dt>T&C</dt><dd>v{{ r.tcVersion }} · {{ dt(r.tcAt) }}</dd>\n    <dt>Nộp lúc</dt><dd>{{ dt(r.createdAt) }}</dd>\n  </dl>\n</div>\n<div class=\"section\">\n  <div class=\"section-title\">Người giới thiệu & đơn gốc</div>\n  <dl class=\"dl\">\n    <dt>Người giới thiệu</dt><dd>{% if ref %}{{ ref.fullName }} · <span class=\"mono\">{{ ref.refCode }}</span> · {{{ badge('rank', ref.rank) }}} (lúc nộp: {{{ refRankLabel }}}){% else %}—{% endif %}</dd>\n    <dt>Đơn</dt><dd>{% if o %}<span class=\"mono\">{{ o.id }}</span> · {{ money(o.price) }} · {{ date(o.paidAt) }}{% else %}—{% endif %}</dd>\n  </dl>\n</div>\n<div class=\"section\">\n  <div class=\"section-title\">Tiến trình</div>\n  {{{ timeline }}}\n</div>\n{% if agent %}\n<div class=\"section\">\n  <div class=\"section-title\">Đã kích hoạt</div>\n  <dl class=\"dl\">\n    <dt>ref_code</dt><dd class=\"mono\">{{ agent.refCode }}</dd>\n    <dt>Link cá nhân</dt><dd class=\"mono\">{{ RULES.publicPurchaseUrl(agent.purchaseAlias) }}</dd>\n    <dt>Hạng</dt><dd>{{{ badge('rank', agent.rank) }}}</dd>\n  </dl>\n  {% if mail %}\n  <div class=\"alert alert-success mt-3\">{{{ icon('sms', 18) }}}<div class=\"text-sm\"><span class=\"alert-title\">Email kích hoạt (mock) → {{ mail.to }}</span><pre style=\"white-space:pre-wrap;font-family:inherit;margin-top:6px\">{{ mail.body }}</pre></div></div>\n  {% endif %}\n</div>\n{% endif %}\n<div class=\"section\">\n  <div class=\"section-title\">Audit</div>\n  {{{ audit }}}\n</div>\n\n{% elif part === 'foot' %}\n{% if r.status.startsWith('PENDING') %}\n<button class=\"btn btn-danger-outline\" onclick=\"Admin.regReject('{{ r.id }}')\">Từ chối</button>\n<button class=\"btn btn-success\" {{{ canApprove ? '' : 'disabled' }}} onclick=\"Admin.regApprove('{{ r.id }}')\">Xác nhận</button>\n{% endif %}\n{% if agent %}<button class=\"btn btn-secondary\" onclick=\"Admin.userDrawer('{{ agent.id }}')\">Xem thành viên</button>{% endif %}\n{% endif %}\n{% endblock %}\n\n{% block admin/registrations-table %}\n<!-- registrations · Bảng hồ sơ đăng ký: rows = [{ r, ref, refRankLabel, cb, cell }], pg = UI.paginate(...) -->\n{% if !rows.length %}\n{{{ UI.empty('user', 'Không có hồ sơ', 'Chưa có đăng ký nào ở trạng thái này.') }}}\n{% else %}\n<div class=\"table-wrap\"><table class=\"table\">\n  <thead><tr><th>Mã</th><th>Người đăng ký</th><th>Người giới thiệu</th><th>Đơn gốc</th><th>Ngày nộp</th><th>Tiến trình</th><th>Hành động</th></tr></thead>\n  <tbody>\n  {% each row in rows %}\n  {% set r = row.r %}\n    <tr>\n      <td class=\"mono\">{{ r.id }}</td>\n      <td><span class=\"cell-main\">{{ r.fullName }}</span><span class=\"cell-sub mono\">{{ r.phone }}</span><span class=\"cell-sub\">{{ r.email }}</span></td>\n      <td>{% if row.ref %}{{ row.ref.fullName }}<span class=\"cell-sub\"><span class=\"mono\">{{ row.ref.refCode }}</span> · {{{ row.refRankLabel }}} lúc nộp</span>{% else %}—{% endif %}</td>\n      <td><button class=\"btn-link mono\" onclick=\"Admin.orderDrawer('{{ r.orderId }}')\">{{ r.orderId }}</button></td>\n      <td>{{ dt(r.createdAt) }}</td>\n      <td>{{{ row.cell }}}</td>\n      <td><div class=\"row-actions\">\n        {% if r.status.startsWith('PENDING') %}\n        <button class=\"btn btn-success btn-sm\" {{{ row.cb.ok ? '' : 'disabled' }}} title=\"{{{ row.cb.why || '' }}}\" onclick=\"Admin.regApprove('{{ r.id }}')\">Xác nhận</button>\n        <button class=\"btn btn-danger-outline btn-sm\" onclick=\"Admin.regReject('{{ r.id }}')\">Từ chối</button>\n        {% endif %}\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"Admin.regDrawer('{{ r.id }}')\">Chi tiết</button>\n      </div></td>\n    </tr>\n  {% endeach %}\n  </tbody>\n</table></div>\n{{{ UI.pagination(pg, 'Admin.gotoRegs') }}}\n{% endif %}\n{% endblock %}\n",
  "admin/users": "<!-- admin-users · Tài khoản admin (Head Admin): me = admin đang đăng nhập, list = Store.adminUsers() -->\n<div class=\"card\"><div class=\"card-body\">\n  <div class=\"table-wrap\"><table class=\"table\">\n    <thead><tr><th>Tên đăng nhập</th><th>Họ tên</th><th>Vai trò</th><th>Trạng thái</th><th>Tạo bởi</th><th></th></tr></thead>\n    <tbody>\n    {% each a in list %}\n      <tr>\n        <td class=\"mono text-strong\">{{ a.username }}{% if a.username === me.username %} <span class=\"badge badge-navy badge-plain\">bạn</span>{% endif %}</td>\n        <td>{{ a.fullName }}</td>\n        <td>{{{ badge('role', a.role) }}}</td>\n        <td>{{{ badge('adminStatus', a.status) }}}</td>\n        <td>{{ a.createdBy }}<span class=\"cell-sub\">{{ date(a.createdAt) }}</span></td>\n        <td><div class=\"row-actions\">\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"Admin.adminForm('{{ a.username }}')\">{{{ icon('edit', 14) }}} Sửa</button>\n          {% if a.username !== me.username %}\n            {% if a.status === 'active' %}\n            <button class=\"btn btn-danger-outline btn-sm\" onclick=\"Admin.setAdminStatus('{{ a.username }}', 'disabled')\">Vô hiệu</button>\n            {% else %}\n            <button class=\"btn btn-success btn-sm\" onclick=\"Admin.setAdminStatus('{{ a.username }}', 'active')\">Kích hoạt</button>\n            {% endif %}\n          {% endif %}\n        </div></td>\n      </tr>\n    {% endeach %}\n    </tbody>\n  </table></div>\n  <p class=\"text-caption mt-3\">Head Admin không thể tự hạ vai trò hoặc vô hiệu chính mình. Specialist truy cập màn này bị từ chối (403).</p>\n</div></div>\n\n{% block admin/users-form %}\n<!-- admin-users · Modal thêm / sửa tài khoản admin: a (tài khoản đang sửa hoặc null), me · part = 'body' | 'foot' -->\n{% if part === 'body' %}\n{{{ UI.field({ id: 'am-user', label: 'Tên đăng nhập', required: true, mono: true, value: a ? a.username : '', attrs: a ? 'readonly' : '' }) }}}\n<div class=\"mt-4\">{{{ UI.field({ id: 'am-name', label: 'Họ tên', required: true, value: a ? a.fullName : '' }) }}}</div>\n<div class=\"mt-4\">{{{ UI.field({ id: 'am-role', label: 'Vai trò', type: 'select', value: a ? a.role : 'SPECIALIST', options: [{ value: 'SPECIALIST', label: LABELS.role.SPECIALIST.text }, { value: 'HEAD', label: LABELS.role.HEAD.text }], attrs: a && a.username === me.username ? 'disabled' : '' }) }}}</div>\n<div class=\"mt-4\">{{{ UI.field({ id: 'am-pw', label: a ? 'Đặt lại mật khẩu (để trống nếu giữ)' : 'Mật khẩu', required: !a, type: 'password' }) }}}</div>\n{% elif part === 'foot' %}\n<button class=\"btn btn-secondary\" onclick=\"UI.closeModal()\">Huỷ</button>\n<button class=\"btn btn-primary\" onclick=\"Admin.saveAdmin({{{ a ? 'true' : 'false' }}})\">Lưu</button>\n{% endif %}\n{% endblock %}\n",
  "admin/withdrawals": "<!-- withdrawals · Rút tiền & sổ hoa hồng: khung tab (nội dung tab render động vào #d07-body bằng d-07-withdraw / d-07-ledger) -->\n<div class=\"card\">\n  <div class=\"tabs\" role=\"tablist\" style=\"padding:0 20px\">\n    <button class=\"tab {{ tab === 'withdraw' ? 'is-active' : '' }}\" onclick=\"Admin.st.d07.tab='withdraw'; App.reload()\">{{{ icon('cash', 18) }}} Rút tiền <span class=\"count\">{{{ pending }}}</span></button>\n    <button class=\"tab {{ tab === 'ledger' ? 'is-active' : '' }}\" onclick=\"Admin.st.d07.tab='ledger'; App.reload()\">{{{ icon('layers', 18) }}} Sổ hoa hồng</button>\n  </div>\n  <div class=\"card-body\" id=\"d07-body\"></div>\n</div>\n\n{% block admin/withdrawals-drawer %}\n<!-- withdrawals · Drawer chi tiết yêu cầu rút tiền: w, u, wal, timeline (html), audit (html), canApprove · part = 'title' | 'body' | 'foot' -->\n{% if part === 'title' %}\n<h2 class=\"mono\">{{ w.id }}</h2>\n<div class=\"row-wrap mt-1\">{{{ badge('withdrawal', w.status, true) }}}<span class=\"text-strong\">{{ money(w.amount) }}</span></div>\n\n{% elif part === 'body' %}\n<div class=\"section\">\n  <div class=\"section-title\">Thành viên</div>\n  <dl class=\"dl\">\n    <dt>Họ tên</dt><dd>{{ u.fullName }} {{{ badge('rank', u.rank) }}}</dd>\n    <dt>SĐT</dt><dd class=\"mono\">{{ u.phone }}</dd>\n    <dt>Số dư</dt><dd>Ghi nhận {{ money(wal.recorded) }} · giữ {{ money(wal.held) }} · đã rút {{ money(wal.withdrawn) }} · khả dụng {{ money(wal.available) }}</dd>\n  </dl>\n</div>\n<div class=\"section\">\n  <div class=\"section-title\">Tài khoản nhận</div>\n  <dl class=\"dl\">\n    <dt>Ngân hàng</dt><dd>{{ w.bank.bankName }}</dd>\n    <dt>Số TK</dt><dd class=\"mono\">{{ w.bank.accountNo }}</dd>\n    <dt>Chủ TK</dt><dd>{{ w.bank.owner }}</dd>\n  </dl>\n</div>\n<div class=\"section\">\n  <div class=\"section-title\">Tiến trình duyệt</div>\n  {{{ timeline }}}\n</div>\n<div class=\"section\">\n  <div class=\"section-title\">Audit</div>\n  {{{ audit }}}\n</div>\n\n{% elif part === 'foot' %}\n{% if w.status.startsWith('PENDING') %}\n<button class=\"btn btn-danger-outline\" onclick=\"Admin.wdReject('{{ w.id }}')\">Từ chối</button>\n<button class=\"btn btn-success\" {{{ canApprove ? '' : 'disabled' }}} onclick=\"Admin.wdApprove('{{ w.id }}')\">Xác nhận</button>\n{% endif %}\n{% if w.status === 'APPROVED' %}<button class=\"btn btn-primary\" onclick=\"Admin.wdPaid('{{ w.id }}')\">Đánh dấu đã chi trả</button>{% endif %}\n{% endif %}\n{% endblock %}\n\n{% block admin/withdrawals-ledger %}\n<!-- withdrawals · Tab sổ hoa hồng (chỉ đọc): s = Admin.st.d07, rows = [{ c, who }], pg, total, company -->\n<div class=\"alert alert-neutral mb-4\">{{{ icon('info', 18) }}}<div class=\"text-sm\">Sổ hoa hồng <strong>chỉ đọc</strong>: mỗi khoản ghi nhận ngay khi đơn thanh toán theo bảng hoa hồng hiệu lực; không có bước duyệt hoa hồng. Kiểm tra Σ theo đơn tại chi tiết đơn (orders).</div></div>\n<div class=\"table-toolbar\">\n  <div class=\"field field-search\"><label class=\"field-label\" for=\"cm-q\">Tìm theo thành viên / đơn</label><input class=\"input\" id=\"cm-q\" value=\"{{ s.cmQ }}\" oninput=\"Admin.st.d07.cmQ=this.value; Admin.st.d07.cmPage=1; Admin.renderLedgerTab()\"></div>\n  <div class=\"toolbar-actions\">\n    <span class=\"text-sm text-muted\">Tổng ghi nhận {{ money(total) }} · về công ty {{ money(company) }}</span>\n    <button class=\"btn btn-secondary\" onclick=\"Admin.exportCm()\">{{{ icon('download', 16) }}} Xuất Excel</button>\n  </div>\n</div>\n{% if !rows.length %}\n{{{ UI.empty('layers', 'Không có khoản hoa hồng') }}}\n{% else %}\n<div class=\"table-wrap\"><table class=\"table\">\n  <thead><tr><th>Mã</th><th>Ngày</th><th>Đơn</th><th>Người thụ hưởng</th><th>Cấp</th><th>Hạng lúc tính</th><th class=\"num\">Số tiền</th><th>TT</th></tr></thead>\n  <tbody>\n  {% each row in rows %}\n  {% set c = row.c %}\n    <tr>\n      <td class=\"mono\">{{ c.id }}</td>\n      <td>{{ date(c.createdAt) }}</td>\n      <td><button class=\"btn-link mono\" onclick=\"Admin.orderDrawer('{{ c.orderId }}')\">{{ c.orderId }}</button></td>\n      <td>{% if c.beneficiaryId === 'COMPANY' %}<strong>HOMI365</strong>{% else %}{{ row.who }}{% endif %}</td>\n      <td>{{{ badge('commissionKind', c.kind) }}}{% if c.kind === 'DIFF' %} <span class=\"text-sm text-muted\">F{{{ c.depth }}}</span>{% endif %}</td>\n      <td>{{{ badge('rank', c.rankAtCalc) }}}</td>\n      <td class=\"num mono text-strong\">{{ money(c.amount) }}</td>\n      <td>{{{ badge('commission', c.status) }}}</td>\n    </tr>\n  {% endeach %}\n  </tbody>\n</table></div>\n{{{ UI.pagination(pg, 'Admin.gotoCm') }}}\n{% endif %}\n{% endblock %}\n\n{% block admin/withdrawals-list %}\n<!-- withdrawals · Tab rút tiền (duyệt 2 lớp): s = Admin.st.d07, rows = [{ w, u, wal, okBal, cb, cell }], pg -->\n<div class=\"alert alert-info mb-4\">{{{ icon('info', 18) }}}<div class=\"text-sm\">Duyệt <strong>2 lớp</strong>: Specialist thứ nhất → Chờ duyệt (1/2) → Specialist thứ hai (khác người) → Đã duyệt; Head Admin xác nhận 1 lần là đủ. Sau khi chuyển khoản, bấm <strong>Đánh dấu đã chi trả</strong>. Từ chối phải nêu lý do — thành viên thấy tại wallet và số tiền hoàn về khả dụng.</div></div>\n<div class=\"table-toolbar\">\n  <div class=\"field\"><label class=\"field-label\" for=\"wd-status\">Trạng thái</label><select class=\"select\" id=\"wd-status\" onchange=\"Admin.st.d07.wdStatus=this.value; Admin.st.d07.wdPage=1; Admin.renderWithdrawTab()\"><option value=\"\">Tất cả (5 trạng thái)</option>{% each k in Object.keys(LABELS.withdrawal) %}<option value=\"{{ k }}\" {{ s.wdStatus === k ? 'selected' : '' }}>{{{ LABELS.withdrawal[k].text }}}</option>{% endeach %}</select></div>\n  <div class=\"toolbar-actions\">\n    <button class=\"btn btn-secondary\" onclick=\"Admin.wdExportBank()\">{{{ icon('download', 16) }}} File ngân hàng (đã duyệt)</button>\n    <button class=\"btn btn-secondary\" onclick=\"Admin.exportWd()\">{{{ icon('download', 16) }}} Xuất Excel</button>\n  </div>\n</div>\n{% if !rows.length %}\n{{{ UI.empty('cash', 'Không có yêu cầu rút tiền') }}}\n{% else %}\n<div class=\"table-wrap\"><table class=\"table\">\n  <thead><tr><th>Mã</th><th>Thành viên</th><th class=\"num\">Số tiền</th><th>Đối chiếu số dư</th><th>Nhận về</th><th>Tiến trình</th><th>Hành động</th></tr></thead>\n  <tbody>\n  {% each row in rows %}\n  {% set w = row.w %}\n  {% set u = row.u %}\n  {% set wal = row.wal %}\n    <tr>\n      <td class=\"mono\">{{ w.id }}<span class=\"cell-sub\">{{ dt(w.createdAt) }}</span></td>\n      <td><span class=\"cell-main\">{{ u.fullName }}</span><span class=\"cell-sub\">{{{ badge('rank', u.rank) }}} <span class=\"mono\">{{ u.phone }}</span></span></td>\n      <td class=\"num mono text-strong\">{{ money(w.amount) }}</td>\n      <td>\n        {% if w.status.startsWith('PENDING') %}\n        <span class=\"{{ row.okBal ? 'text-success' : 'text-error' }}\">{{{ icon(row.okBal ? 'check-circle' : 'x-circle', 14) }}} {{{ row.okBal ? 'Đủ số dư' : 'Thiếu số dư' }}}</span><span class=\"cell-sub\">ghi nhận {{ money(wal.recorded) }} · giữ {{ money(wal.held) }} · đã rút {{ money(wal.withdrawn) }}</span>\n        {% else %}\n        <span class=\"text-muted\">—</span>\n        {% endif %}\n      </td>\n      <td>{{ w.bank.bankName }}<span class=\"cell-sub mono\">{{ w.bank.accountNo }} · {{ w.bank.owner }}</span></td>\n      <td>{{{ row.cell }}}</td>\n      <td><div class=\"row-actions\">\n        {% if w.status.startsWith('PENDING') %}\n        <button class=\"btn btn-success btn-sm\" {{{ row.cb.ok && row.okBal ? '' : 'disabled' }}} title=\"{{{ row.cb.why || (row.okBal ? '' : 'Thiếu số dư') }}}\" onclick=\"Admin.wdApprove('{{ w.id }}')\">Xác nhận</button>\n        <button class=\"btn btn-danger-outline btn-sm\" onclick=\"Admin.wdReject('{{ w.id }}')\">Từ chối</button>\n        {% endif %}\n        {% if w.status === 'APPROVED' %}<button class=\"btn btn-primary btn-sm\" onclick=\"Admin.wdPaid('{{ w.id }}')\">Đánh dấu đã chi trả</button>{% endif %}\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"Admin.wdDrawer('{{ w.id }}')\">Chi tiết</button>\n      </div></td>\n    </tr>\n  {% endeach %}\n  </tbody>\n</table></div>\n{{{ UI.pagination(pg, 'Admin.gotoWd') }}}\n{% endif %}\n{% endblock %}\n",
  "buyer/buy": "<!-- buy · Trang mua hàng: (a) form · (b) OTP tại chỗ · (c) lỗi field · (g) SMS lỗi -->\n<div class=\"a01-grid\">\n  <div class=\"a01-pkg\">{{{ include('partials/pkg-header', { pkg: pkg, tag: 'h1' }) }}}</div>\n\n  <div class=\"a01-ref\">\n    <div class=\"card card-tint\"><div class=\"card-body ref-card\">\n      <span class=\"avatar\" aria-hidden=\"true\">{{ RULES.initials(seller.fullName) }}</span>\n      <div>\n        <div class=\"text-sm text-muted\">Người giới thiệu</div>\n        <div class=\"text-strong\">{{ seller.fullName }}</div>\n        <div class=\"text-caption mono\">Mã {{ seller.refCode }}</div>\n      </div>\n    </div></div>\n  </div>\n\n  <div class=\"card a01-form\" id=\"a01-card\">\n    <div class=\"card-head\"><h2>Thông tin nhận hàng</h2><span class=\"text-sm text-muted\">Bước 1/3</span></div>\n    <div class=\"card-body\" id=\"a01-body\">\n      <form id=\"a01-form\" novalidate onsubmit=\"Buyer.a01Submit(event)\">\n        {{{ UI.field({ id: 'fullName', label: 'Họ và tên', required: true, placeholder: 'Nguyễn Văn A', value: draft.fullName, attrs: 'autocomplete=\"name\"' }) }}}\n        {{{ UI.field({ id: 'phone', label: 'Số điện thoại', required: true, type: 'tel', placeholder: '0912 345 678', value: draft.phone, mono: true, hint: 'Dùng để nhận mã OTP, mã kích hoạt và đăng nhập sau này.', attrs: 'autocomplete=\"tel\" inputmode=\"numeric\"' }) }}}\n        {{{ UI.field({ id: 'email', label: 'Email', required: true, type: 'email', placeholder: 'ban@email.com', value: draft.email, hint: 'Nhận xác nhận đơn hàng và thông tin thành viên.', attrs: 'autocomplete=\"email\"' }) }}}\n        {{{ UI.field({ id: 'address', label: 'Địa chỉ nhận hàng', required: true, type: 'textarea', rows: 2, placeholder: 'Số nhà, đường, phường/xã, tỉnh/thành phố', value: draft.address, attrs: 'autocomplete=\"street-address\"' }) }}}\n        {{{ UI.field({ id: 'note', label: 'Ghi chú', type: 'textarea', rows: 2, placeholder: 'Ví dụ: giao giờ hành chính, gọi trước khi giao…', value: draft.note }) }}}\n        <div class=\"qty-fixed mt-4\"><span>Số lượng</span><strong>1 gói (cố định)</strong></div>\n        <div class=\"total-row\"><span>Tổng thanh toán</span><span class=\"total-amt\">{{{ money(pkg.price) }}}</span></div>\n        <div id=\"a01-alert\" class=\"mt-4\" hidden></div>\n        <div class=\"actions\"><button type=\"submit\" class=\"btn btn-primary btn-lg btn-block\" id=\"a01-submit\">{{{ icon('sms', 20) }}} Gửi OTP &amp; tiếp tục</button></div>\n        <p class=\"text-caption text-center mt-3\">Bằng việc tiếp tục, bạn đồng ý nhận SMS xác thực từ HOMI365.</p>\n      </form>\n    </div>\n  </div>\n\n  <div class=\"a01-intro stack\">{{{ include('partials/product-intro', { pkg: pkg, pc: pc, g0: g0 }) }}}</div>\n</div>\n\n{% block buyer/buy-state %}\n{% if state === 'invalid' || state === 'inactive' %}\n<!-- (e) Link không hợp lệ / không còn hiệu lực (BR-01) -->\n<div class=\"card\"><div class=\"card-body stack text-center\">\n  <div class=\"result-icon is-error\" style=\"margin:0 auto\">{{{ icon('external', 34) }}}</div>\n  {% if state === 'inactive' %}\n  <div class=\"error-code\">LINK KHÔNG CÒN HIỆU LỰC</div>\n  <h1>Link giới thiệu này đã ngừng hoạt động</h1>\n  <p class=\"text-muted\">Tài khoản người giới thiệu đang bị tạm khoá. Vui lòng liên hệ người đã gửi link cho bạn hoặc bộ phận hỗ trợ.</p>\n  {% else %}\n  <div class=\"error-code\">LINK KHÔNG HỢP LỆ</div>\n  <h1>Link giới thiệu không hợp lệ</h1>\n  <p class=\"text-muted\">Gói sản phẩm chỉ mua được qua link giới thiệu của thành viên HOMI365. Vui lòng mở lại đúng link bạn nhận được (dạng <span class=\"mono\">{{ CONFIG.brand.baseUrl }}/r/…</span>).</p>\n  {% endif %}\n  <div class=\"alert alert-neutral\" style=\"text-align:left\">{{{ icon('phone', 20) }}}<div>Hỗ trợ: <strong>{{ CONFIG.brand.supportHotline }}</strong> ({{ CONFIG.brand.supportHours }})</div></div>\n  <div class=\"actions actions-row\">\n    <a class=\"btn btn-secondary btn-lg\" href=\"#order-lookup\">{{{ icon('search', 18) }}} Tra cứu đơn hàng đã mua</a>\n    <a class=\"btn btn-primary btn-lg\" href=\"#home\">Về trang giới thiệu prototype</a>\n  </div>\n</div></div>\n\n{% elif state === 'inactive-pkg' %}\n<!-- (f) Gói ngưng bán -->\n<div class=\"card\"><div class=\"card-body stack text-center\">\n  <div class=\"result-icon is-pending\" style=\"margin:0 auto\">{{{ icon('package', 34) }}}</div>\n  <h1>Sản phẩm tạm ngưng bán</h1>\n  <p class=\"text-muted\">Gói sản phẩm đang được tạm tắt bán để cập nhật. Vui lòng quay lại sau hoặc liên hệ người giới thiệu của bạn{% if seller %} (<strong>{{ seller.fullName }}</strong>){% endif %}.</p>\n  <div class=\"actions\"><a class=\"btn btn-secondary btn-lg\" href=\"#order-lookup\">Tra cứu đơn hàng</a></div>\n</div></div>\n\n{% elif state === 'duplicate' %}\n<!-- (d) SĐT đã mua gói (BR-03) -->\n<div class=\"card\"><div class=\"card-body stack text-center\">\n  <div class=\"result-icon is-pending\" style=\"margin:0 auto\">{{{ icon('alert-octagon', 34) }}}</div>\n  <h1>Số điện thoại này đã mua gói</h1>\n  <p class=\"text-muted\">Mỗi số điện thoại chỉ được sở hữu <strong>1 gói</strong>. Số <span class=\"mono\">{{ RULES.maskPhone(phone) }}</span> đã có đơn hàng thanh toán thành công, nên không thể tạo đơn mới.</p>\n  <div class=\"alert alert-info\" style=\"text-align:left\">{{{ icon('info', 20) }}}<div>Bạn có thể tra cứu đơn đã mua, xem mã kích hoạt hoặc kích hoạt tài khoản seller bằng chính số điện thoại này. Cần mua thêm gói cho người thân? Liên hệ hỗ trợ {{ CONFIG.brand.supportHotline }} để được cấp ngoại lệ.</div></div>\n  <div class=\"actions actions-row\">\n    <a class=\"btn btn-secondary btn-lg\" href=\"#buy\">Nhập số khác</a>\n    <a class=\"btn btn-primary btn-lg\" href=\"#order-lookup?phone={{ phone }}\">Tra cứu đơn hàng</a>\n  </div>\n</div></div>\n{% endif %}\n{% endblock %}\n",
  "buyer/login": "<!-- login · Đăng nhập thành viên (SĐT + mật khẩu) · Quên mật khẩu (OTP) -->\n<div class=\"buyer-split\">\n  <aside class=\"buyer-side\">{{{ include('partials/intro-panel', intro) }}}</aside>\n  <div class=\"stack\">\n    {% if reason === 'expired' %}\n    <div class=\"alert alert-warning\" role=\"alert\">{{{ icon('clock', 20) }}}<div><span class=\"alert-title\">Phiên đăng nhập đã hết hạn</span>Vui lòng đăng nhập lại. Sau khi đăng nhập bạn sẽ quay về trang đang xem.</div></div>\n    {% endif %}\n    <div class=\"card\"><div class=\"card-body\" id=\"a05-body\">\n      {% if forgot %}\n      <form novalidate onsubmit=\"Buyer.a05Forgot(event)\">\n        {{{ UI.field({ id: 'fg-phone', label: 'Số điện thoại thành viên', required: true, type: 'tel', mono: true, placeholder: '0912 345 678', attrs: 'inputmode=\"numeric\" autocomplete=\"tel\"' }) }}}\n        <div id=\"a05-alert\" hidden></div>\n        <div class=\"actions\">\n          <button class=\"btn btn-primary btn-lg btn-block\">{{{ icon('sms', 18) }}} Gửi OTP</button>\n          <a class=\"btn btn-ghost\" href=\"#login\">Quay lại đăng nhập</a>\n        </div>\n      </form>\n      {% else %}\n      <form novalidate onsubmit=\"Buyer.a05Submit(event)\">\n        {{{ UI.field({ id: 'lg-phone', label: 'Số điện thoại', required: true, type: 'tel', mono: true, placeholder: '0912 345 678', attrs: 'inputmode=\"numeric\" autocomplete=\"tel\"' }) }}}\n        <div class=\"field mt-4\" id=\"lg-pass-field\">\n          <label class=\"field-label\" for=\"lg-pass\">Mật khẩu<span class=\"req\">*</span></label>\n          <div class=\"input-affix\">\n            <input class=\"input\" type=\"password\" id=\"lg-pass\" autocomplete=\"current-password\">\n            <button type=\"button\" class=\"btn btn-ghost affix-btn\" aria-label=\"Hiện mật khẩu\" onclick=\"UI.togglePassword('lg-pass', this)\">{{{ icon('eye', 20) }}}</button>\n          </div>\n          <div class=\"field-error\" id=\"lg-pass-err\"></div>\n        </div>\n        <div class=\"row-between mt-3\">\n          <label class=\"check\"><input type=\"checkbox\" id=\"lg-remember\"> Ghi nhớ đăng nhập ({{ CONFIG.session.rememberDays }} ngày)</label>\n          <a href=\"#login?view=forgot\" class=\"btn-link\">Quên mật khẩu?</a>\n        </div>\n        <div id=\"a05-alert\" hidden></div>\n        <div class=\"actions\"><button class=\"btn btn-primary btn-lg btn-block\" id=\"lg-submit\">{{{ icon('key', 18) }}} Đăng nhập</button></div>\n      </form>\n      <p class=\"text-center text-sm text-muted mt-4\">Đã mua gói nhưng chưa có tài khoản? <a href=\"#register\">Đăng ký thành viên</a><br><a href=\"#admin-login\">Quản trị viên đăng nhập tại đây</a></p>\n      {% endif %}\n    </div></div>\n    <div class=\"demo-hint\">Thành viên mẫu: <strong>0908123456</strong> / <strong>{{ CONFIG.demo.agentPassword }}</strong> (Lithium) · <strong>0912345678</strong> Gold · <strong>0987654321</strong> Copper · <strong>0977000111</strong> bị khoá · <strong>{{ demoPhone }}</strong> đã mua chưa đăng ký · <strong>0913000888</strong> hồ sơ chờ duyệt · <strong>0914000999</strong> bị từ chối</div>\n  </div>\n</div>\n\n{% block buyer/login-reset %}\n<h2 class=\"mb-4\">Đặt mật khẩu mới</h2>\n<form novalidate onsubmit=\"Buyer.a05Reset(event, '{{ phone }}')\">\n  {{{ UI.field({ id: 'rs-pw', label: 'Mật khẩu mới', type: 'password', required: true, hint: 'Tối thiểu 8 ký tự, có chữ và số' }) }}}\n  {{{ UI.field({ id: 'rs-pw2', label: 'Nhập lại mật khẩu mới', type: 'password', required: true }) }}}\n  <div class=\"actions\"><button class=\"btn btn-primary btn-lg btn-block\">Đặt lại mật khẩu</button></div>\n</form>\n{% endblock %}\n",
  "buyer/order-lookup": "<!-- order-lookup · Tra cứu đơn hàng (không cần đăng nhập) -->\n<div class=\"buyer-split\">\n  <aside class=\"buyer-side\">{{{ include('partials/intro-panel', intro) }}}</aside>\n  <div class=\"stack\">\n    <div class=\"card\"><div class=\"card-body\" id=\"a04-body\">\n      <div class=\"seg mb-4\" role=\"tablist\">\n        <button role=\"tab\" aria-selected=\"{{ mode === 'phone' }}\" class=\"{% if mode === 'phone' %}is-active{% endif %}\" onclick=\"Buyer._a04Mode='phone'; App.reload()\">Số điện thoại + OTP</button>\n        <button role=\"tab\" aria-selected=\"{{ mode === 'order' }}\" class=\"{% if mode === 'order' %}is-active{% endif %}\" onclick=\"Buyer._a04Mode='order'; App.reload()\">Mã đơn hàng</button>\n      </div>\n      {% if mode === 'phone' %}\n      <form novalidate onsubmit=\"Buyer.a04Phone(event)\">\n        {{{ UI.field({ id: 'lk-phone', label: 'Số điện thoại đã mua', required: true, type: 'tel', mono: true, placeholder: '0912 345 678', value: prefill, attrs: 'inputmode=\"numeric\" autocomplete=\"tel\"' }) }}}\n        <div class=\"field-hint mt-2\">Xác thực OTP để xem đầy đủ, bao gồm mã kích hoạt.</div>\n        <div class=\"actions\"><button class=\"btn btn-primary btn-lg btn-block\" id=\"lk-submit\">{{{ icon('sms', 18) }}} Gửi OTP</button></div>\n      </form>\n      {% else %}\n      <form novalidate onsubmit=\"Buyer.a04Order(event)\">\n        {{{ UI.field({ id: 'lk-order', label: 'Mã đơn hàng', required: true, mono: true, placeholder: 'HM260904001', hint: 'In trên màn kết quả thanh toán và trong SMS.', attrs: 'autocapitalize=\"characters\"' }) }}}\n        <div class=\"alert alert-neutral mt-4\">{{{ icon('info', 18) }}}<div class=\"text-sm\">Tra cứu bằng mã đơn chỉ hiển thị trạng thái. Mã kích hoạt chỉ hiện khi xác thực OTP số điện thoại mua (BR-08).</div></div>\n        <div class=\"actions\"><button class=\"btn btn-primary btn-lg btn-block\">{{{ icon('search', 18) }}} Tra cứu</button></div>\n      </form>\n      {% endif %}\n    </div></div>\n    <div class=\"demo-hint\">SĐT mẫu có đơn: <strong>{{ demoPhone }}</strong> (chưa có TK seller) · <strong>0908123456</strong> (seller) · mã đơn: <strong>{{ demoOrderId }}</strong></div>\n  </div>\n</div>\n\n{% block buyer/order-lookup-card %}\n<div class=\"order-card\">\n  <div class=\"order-card-head\">\n    <div><div class=\"text-sm text-muted\">Mã đơn</div><div class=\"mono text-strong\">{{ o.id }}</div></div>\n    <div class=\"text-right\"><div class=\"text-sm text-muted\">{{{ date(o.createdAt) }}}</div><div class=\"text-strong\">{{{ money(o.price) }}}</div></div>\n  </div>\n  <div class=\"status-row\">\n    <span class=\"text-sm text-muted\">Thanh toán:</span>{{{ badge('orderStatus', o.status) }}}\n    <span class=\"text-sm text-muted\">Giao hàng:</span>{{{ badge('shipping', o.shipping) }}}\n  </div>\n  {% if o.status === 'PAID' %}\n    {% if verified %}\n      {% if o.licenseCode %}\n      <div class=\"code-box mt-3\">\n        <div class=\"grow\"><span class=\"code-label\">Mã kích hoạt {% if activated %}· đã kích hoạt{% else %}· chưa dùng{% endif %}</span><span class=\"code-value\">{{ o.licenseCode }}</span></div>\n        <button class=\"btn btn-secondary btn-icon\" aria-label=\"Sao chép mã\" onclick=\"UI.copy('{{ o.licenseCode }}', 'Đã sao chép mã kích hoạt.')\">{{{ icon('copy', 18) }}}</button>\n      </div>\n      {% else %}\n      <div class=\"alert alert-warning mt-3\">{{{ icon('clock', 18) }}}<div class=\"text-sm\">Mã kích hoạt đang chờ cấp, sẽ gửi qua SMS.</div></div>\n      {% endif %}\n    {% else %}\n    <div class=\"code-box mt-3\"><div class=\"grow\"><span class=\"code-label\">Mã kích hoạt</span><span class=\"code-value\">••••-••••-••••</span></div>{{{ icon('lock', 18, 'text-muted') }}}</div>\n    {% endif %}\n  {% endif %}\n  {% if o.status === 'AWAITING_RECONCILE' %}<p class=\"text-sm text-muted mt-3\">Đang chờ đối soát chuyển khoản. Mã kích hoạt được cấp sau khi xác nhận.</p>{% endif %}\n  {% if o.status === 'REJECTED' %}<p class=\"text-sm text-error mt-3\">Từ chối đối soát: {{ o.rejectReason || '' }}</p>{% endif %}\n</div>\n{% endblock %}\n\n{% block buyer/order-lookup-result %}\n<!-- Kết quả tra cứu: danh sách đơn + CTA đăng ký / trạng thái hồ sơ -->\n<div class=\"row-between mb-3\"><h2>{{ orders.length }} đơn hàng</h2><button class=\"btn btn-ghost btn-sm\" onclick=\"App.reload()\">{{{ icon('arrow-left', 16) }}} Tra cứu khác</button></div>\n{% if !verified %}\n<div class=\"alert alert-neutral mb-3\">{{{ icon('lock', 18) }}}<div class=\"text-sm\">Mã kích hoạt được ẩn. Tra cứu bằng SĐT + OTP để xem.</div></div>\n{% endif %}\n\n{% each o in orders %}\n{{{ include('buyer/order-lookup-card', { o: o, verified: verified, activated: o.licenseCode && Store.codeInfo(o.licenseCode) && Store.codeInfo(o.licenseCode).status === 'ACTIVATED' }) }}}\n{% endeach %}\n\n{% if el.ok %}\n<div class=\"card card-tint mt-4\"><div class=\"card-body\">\n  <h3>Đăng ký thành viên HOMI365</h3>\n  <p class=\"text-sm text-muted mt-1\">Số điện thoại này đã mua gói qua {{ el.referrer.fullName }} (hạng {{ RULES.rank(el.referrer.rank).label }}). Đăng ký hồ sơ để nhận link bán hàng và hoa hồng theo hạng.</p>\n  <div class=\"actions\"><a class=\"btn btn-primary btn-lg btn-block\" href=\"#register?phone={{ phone }}\">{{{ icon('user', 18) }}} Đăng ký thành viên</a></div>\n</div></div>\n{% endif %}\n{% if el.reason === 'pending' %}\n<div class=\"alert alert-info mt-4\">{{{ icon('clock', 18) }}}<div class=\"text-sm\">Hồ sơ thành viên của bạn đang {{ label('approval', el.registration.status).toLowerCase() }}. <a href=\"#register?state=pending&phone={{ phone }}\">Xem trạng thái</a></div></div>\n{% endif %}\n{% if isSeller %}\n<div class=\"actions\"><a class=\"btn btn-outline btn-lg btn-block\" href=\"#login\">Đăng nhập Dashboard thành viên</a></div>\n{% endif %}\n{% endblock %}\n",
  "buyer/order-result": "{% block buyer/order-result-awaiting %}\n<!-- (d) AWAITING_RECONCILE — polling -->\n<div class=\"stack\">\n  <div class=\"card\"><div class=\"card-body stack\">\n    <div class=\"result-hero\">\n      <div class=\"result-icon is-pending pulse\">{{{ icon('clock', 40) }}}</div>\n      <h1>Đang chờ xác nhận chuyển khoản</h1>\n      <p>Chúng tôi đang đối soát giao dịch của bạn. Trang này tự cập nhật mỗi {{ CONFIG.order.reconcilePollSeconds }} giây — bạn có thể đóng trang và tra cứu lại sau.</p>\n    </div>\n    {{{ info }}}\n    <div class=\"text-caption text-center\" id=\"poll-status\" aria-live=\"polite\">Đang kiểm tra…</div>\n    <div class=\"actions actions-row\">\n      <a class=\"btn btn-secondary btn-lg\" href=\"#order-lookup\">Tra cứu đơn sau</a>\n      <button class=\"btn btn-outline btn-lg\" onclick=\"App.reload()\">{{{ icon('refresh', 18) }}} Kiểm tra ngay</button>\n    </div>\n  </div></div>\n  <div class=\"demo-hint\">Mô phỏng: admin xác nhận/từ chối tại <a href=\"#orders\" target=\"_blank\">orders</a> (mở tab mới) — trang này sẽ tự chuyển.\n    <button class=\"btn-link\" onclick=\"Store.confirmReconcile('{{ order.id }}'); App.reload()\">Giả lập admin xác nhận</button> ·\n    <button class=\"btn-link\" onclick=\"Store.rejectReconcile('{{ order.id }}', 'Không tìm thấy giao dịch khớp'); App.reload()\">Giả lập từ chối</button>\n  </div>\n</div>\n{% endblock %}\n\n{% block buyer/order-result-failed %}\n<!-- (c) FAILED + Thử lại (nếu còn hạn) -->\n<div class=\"card\"><div class=\"card-body stack\">\n  <div class=\"result-hero\">\n    <div class=\"result-icon is-error\">{{{ icon('x-circle', 40) }}}</div>\n    <h1>Thanh toán thất bại</h1>\n    <p>{{ order.failReason || 'Giao dịch không thành công.' }}</p>\n  </div>\n  {{{ info }}}\n  {% if canRetry %}\n  <div class=\"row-between\"><span class=\"text-sm text-muted\">Đơn còn hiệu lực</span>{{{ UI.countdown.markup('a03-countdown') }}}</div>\n  {% else %}\n  <div class=\"alert alert-warning\">{{{ icon('clock', 20) }}}<div>Đơn đã hết thời gian giữ. Vui lòng đặt lại.</div></div>\n  {% endif %}\n  <div class=\"actions actions-row\">\n    <a class=\"btn btn-secondary btn-lg\" href=\"#order-lookup\">Tra cứu đơn</a>\n    {% if canRetry %}\n    <button class=\"btn btn-primary btn-lg\" onclick=\"Store.retryOrder('{{ order.id }}'); App.navigate('payment')\">{{{ icon('refresh', 18) }}} Thử lại</button>\n    {% else %}\n    <button class=\"btn btn-primary btn-lg\" onclick=\"App.navigate('buy')\">Đặt lại</button>\n    {% endif %}\n  </div>\n</div></div>\n{% endblock %}\n\n{% block buyer/order-result-later %}\n<!-- (b) Để sau → xác nhận đã gửi SMS -->\n<div class=\"card\"><div class=\"card-body stack text-center\">\n  <div class=\"result-icon is-success\" style=\"margin:0 auto\">{{{ icon('sms', 34) }}}</div>\n  <h1>Đã gửi mã kích hoạt qua SMS</h1>\n  <p class=\"text-muted\">Tin nhắn chứa mã kích hoạt và hướng dẫn sử dụng đã gửi tới <strong class=\"mono\">{{ RULES.maskPhone(order.phone) }}</strong> (trong vòng 1 phút).</p>\n  <div class=\"alert alert-info\" style=\"text-align:left\">{{{ icon('info', 20) }}}<div>Bạn có thể đăng ký thành viên sau bằng chính số điện thoại này tại mục <strong>Đăng nhập thành viên</strong> (nếu người giới thiệu đủ điều kiện), hoặc tra cứu đơn hàng để xem lại mã.</div></div>\n  <div class=\"actions actions-row\">\n    <a class=\"btn btn-secondary btn-lg\" href=\"#login\">Đăng nhập thành viên</a>\n    <a class=\"btn btn-primary btn-lg\" href=\"#order-lookup\">Tra cứu đơn hàng</a>\n  </div>\n</div></div>\n{% endblock %}\n\n{% block buyer/order-result-nocode %}\n<!-- (f) Kho mã hết → chờ cấp -->\n<div class=\"card\"><div class=\"card-body stack\">\n  <div class=\"result-hero\">\n    <div class=\"result-icon is-success\">{{{ icon('check-circle', 40) }}}</div>\n    <h1>Thanh toán thành công</h1>\n    <p>Đơn hàng đã được ghi nhận.</p>\n  </div>\n  <div class=\"alert alert-warning\">{{{ icon('clock', 22) }}}<div><span class=\"alert-title\">Mã kích hoạt đang chờ cấp</span>Mã kích hoạt sẽ được gửi qua SMS tới <strong class=\"mono\">{{ RULES.maskPhone(order.phone) }}</strong> trong thời gian sớm nhất. Bạn cũng có thể xem mã tại mục tra cứu đơn hàng.</div></div>\n  {{{ info }}}\n  <div class=\"card card-tint\"><div class=\"card-body\">{{{ cta }}}</div></div>\n</div></div>\n{% endblock %}\n\n{% block buyer/order-result-paid %}\n<!-- (a) PAID — mã đơn + mã kích hoạt + mời đăng ký thành viên -->\n<div class=\"buyer-split buyer-split-rev\">\n  <div class=\"card\"><div class=\"card-body\">\n    <div class=\"result-hero\">\n      <div class=\"result-icon is-success\">{{{ icon('check-circle', 40) }}}</div>\n      <h1>Thanh toán thành công</h1>\n      <p>Cảm ơn bạn đã mua {{ pkg.name }}. Đồng hồ HW01 sẽ được giao tới địa chỉ đã đăng ký.</p>\n    </div>\n    <div class=\"code-box code-box-lg code-box-navy mt-4\">\n      <div class=\"grow\"><span class=\"code-label\">Mã kích hoạt của bạn</span><span class=\"code-value\">{{ order.licenseCode }}</span></div>\n      <button class=\"btn btn-icon btn-secondary\" aria-label=\"Sao chép mã kích hoạt\" onclick=\"UI.copy('{{ order.licenseCode }}', 'Đã sao chép mã kích hoạt.')\">{{{ icon('copy', 20) }}}</button>\n    </div>\n    <p class=\"text-sm text-muted mt-2\">Nhập mã này trong ứng dụng HOMI365 trên điện thoại để kích hoạt gói. Mã chỉ dùng được trên 1 thiết bị.</p>\n    <div class=\"mt-4\">{{{ info }}}</div>\n  </div></div>\n  <aside class=\"buyer-side\"><div class=\"card card-tint\"><div class=\"card-body\">{{{ cta }}}</div></div></aside>\n</div>\n{% endblock %}\n\n{% block buyer/order-result-reg-prompt %}\n<!-- Popup mời đăng ký thành viên — thân modal (hiện 1 lần/đơn) -->\n<div class=\"text-center mb-3\"><span class=\"result-icon is-info\" style=\"margin:0 auto\">{{{ icon('gift', 32) }}}</span></div>\n<p>Bạn được <strong>{{ ref.fullName }}</strong> (hạng {{ rankLabel }}) mời tham gia chương trình thành viên. Đăng ký hồ sơ để nhận <strong>link bán hàng cá nhân</strong> và <strong>hoa hồng theo hạng</strong> cho mỗi gói bán được.</p>\n<ul class=\"pkg-benefits mt-3\">\n  <li>{{{ icon('check', 16) }}}<span>Thông tin điền sẵn từ đơn hàng, chỉ cần thêm tài khoản ngân hàng và mật khẩu.</span></li>\n  <li>{{{ icon('check', 16) }}}<span>Hồ sơ được duyệt trong 1–2 ngày làm việc, nhận email kích hoạt.</span></li>\n  <li>{{{ icon('check', 16) }}}<span>Không đăng ký vẫn giữ nguyên đơn hàng và mã kích hoạt.</span></li>\n</ul>\n{% endblock %}\n\n{% block buyer/order-result-reg-prompt-foot %}\n<button class=\"btn btn-secondary btn-lg\" onclick=\"UI.closeModal()\">Thoát ra, để sau</button>\n<a class=\"btn btn-primary btn-lg\" href=\"#register?order={{ order.id }}\" onclick=\"UI.closeModal()\">{{{ icon('user', 18) }}} Đăng ký thành viên</a>\n{% endblock %}\n\n{% block buyer/order-result-rejected %}\n<!-- (e) Admin từ chối đối soát -->\n<div class=\"card\"><div class=\"card-body stack\">\n  <div class=\"result-hero\">\n    <div class=\"result-icon is-error\">{{{ icon('x-circle', 40) }}}</div>\n    <h1>Chuyển khoản chưa được xác nhận</h1>\n    <p>Bộ phận đối soát không tìm thấy giao dịch khớp với đơn hàng này.</p>\n  </div>\n  <div class=\"alert alert-error\">{{{ icon('warning', 20) }}}<div><span class=\"alert-title\">Lý do</span>{{ order.rejectReason || '—' }}</div></div>\n  {{{ info }}}\n  <div class=\"alert alert-info\">{{{ icon('phone', 20) }}}<div>Nếu bạn đã chuyển khoản, vui lòng liên hệ <strong>{{ CONFIG.brand.supportHotline }}</strong> kèm ảnh chụp giao dịch và mã đơn <span class=\"mono\">{{ order.id }}</span> để được hỗ trợ.</div></div>\n  <div class=\"actions actions-row\">\n    <a class=\"btn btn-secondary btn-lg\" href=\"#order-lookup\">Tra cứu đơn</a>\n    <button class=\"btn btn-primary btn-lg\" onclick=\"App.navigate('buy')\">Đặt đơn mới</button>\n  </div>\n</div></div>\n{% endblock %}\n",
  "buyer/payment": "<!-- payment · Thanh toán: chọn phương thức / cổng / VietQR (cột tóm tắt đơn bên phải) -->\n<div class=\"buyer-split buyer-split-rev buyer-side-first\">\n  <div class=\"stack\">\n    {% if order.status === 'FAILED' %}\n    <div class=\"alert alert-error\" role=\"alert\">{{{ icon('x-circle', 22) }}}<div><span class=\"alert-title\">Thanh toán không thành công</span>{{ order.failReason || 'Giao dịch bị huỷ hoặc cổng trả lỗi.' }} Bạn có thể chọn lại phương thức khi đơn còn thời hạn.</div></div>\n    {% endif %}\n    {{{ body }}}\n    <div class=\"demo-hint\">Mô phỏng: <button class=\"btn-link\" onclick=\"Buyer.a02SimExpire('{{ order.id }}')\">hết thời gian giữ đơn</button> (thực tế đơn tự hết hạn sau {{ holdMin }} phút)</div>\n  </div>\n\n  <aside class=\"buyer-side\"><div class=\"card\"><div class=\"card-body\">\n    <div class=\"order-summary\">\n      <div>\n        <div class=\"text-sm text-muted\">Mã đơn hàng</div><div class=\"order-id\">{{ order.id }}</div>\n        <div class=\"text-sm mt-2\">{{ pkg.fullName }}</div>\n        <div class=\"text-sm text-muted mt-1\">Giao tới: {{ order.fullName }} · {{ RULES.maskPhone(order.phone) }}</div>\n      </div>\n      {{{ UI.countdown.markup('a02-countdown') }}}\n    </div>\n    <div class=\"total-row\"><span>Số tiền cần thanh toán</span><span class=\"total-amt\">{{{ money(order.price) }}}</span></div>\n    <p class=\"text-caption mt-3\">Đơn được giữ trong {{ holdMin }} phút. Hết thời gian, đơn tự huỷ và bạn có thể đặt lại.</p>\n  </div></div></aside>\n</div>\n\n{% block buyer/payment-bank %}\n<!-- (c) Khối VietQR + \"Tôi đã chuyển khoản\" -->\n<div class=\"card\">\n  <div class=\"card-head\"><h2>Chuyển khoản VietQR</h2><span class=\"text-sm text-muted\">Bước 3/3</span></div>\n  <div class=\"card-body stack\">\n    {{{ UI.vietqr(order) }}}\n    <div class=\"alert alert-warning\">{{{ icon('warning', 20) }}}<div>Nội dung chuyển khoản phải ghi <strong class=\"mono\">{{ order.id }}</strong> để hệ thống đối soát đúng đơn. Chuyển đúng số tiền <strong>{{{ money(order.price) }}}</strong>.</div></div>\n    <div class=\"actions\">\n      <button class=\"btn btn-primary btn-lg btn-block\" onclick=\"Buyer.a02Claim('{{ order.id }}')\">{{{ icon('check', 18) }}} Tôi đã chuyển khoản</button>\n      <button class=\"btn btn-ghost\" onclick=\"App.navigate('payment')\">{{{ icon('arrow-left', 16) }}} Chọn phương thức khác</button>\n    </div>\n  </div>\n</div>\n{% endblock %}\n\n{% block buyer/payment-choose %}\n<div class=\"card\">\n  <div class=\"card-head\"><h2>Chọn phương thức thanh toán</h2><span class=\"text-sm text-muted\">Bước 3/3</span></div>\n  <div class=\"card-body stack-sm\" role=\"radiogroup\" aria-label=\"Phương thức thanh toán\">\n    {% each m in methods %}\n    <label class=\"radio-card {% if sel === m.id %}is-selected{% endif %}\" for=\"pm-{{ m.id }}\">\n      <input type=\"radio\" name=\"pm\" id=\"pm-{{ m.id }}\" value=\"{{ m.id }}\" {% if sel === m.id %}checked{% endif %} onchange=\"Buyer._a02Method='{{ m.id }}'; App.reload()\">\n      <div class=\"grow\"><div class=\"radio-card-title\">{{ m.title }}</div><div class=\"radio-card-desc\">{{ m.desc }}</div></div>\n      {{{ icon(m.ico, 24, 'text-navy') }}}\n    </label>\n    {% endeach %}\n    <div class=\"actions\">\n      <button class=\"btn btn-primary btn-lg btn-block\" onclick=\"Buyer.a02Go('{{ order.id }}')\">Tiếp tục {{{ icon('arrow-right', 18) }}}</button>\n      <button class=\"btn btn-ghost\" onclick=\"Buyer.a02Cancel('{{ order.id }}')\">Huỷ đơn, quay về trang mua hàng</button>\n    </div>\n  </div>\n</div>\n{% endblock %}\n\n{% block buyer/payment-expired %}\n<!-- (e) EXPIRED + Đặt lại (giữ mã giới thiệu — BR-06/07) -->\n<div class=\"card\"><div class=\"card-body stack text-center\">\n  <div class=\"result-icon is-pending\" style=\"margin:0 auto\">{{{ icon('clock', 34) }}}</div>\n  <div class=\"error-code\">ĐƠN {{ order.id }} · HẾT HẠN</div>\n  <h1>Đơn hàng đã hết thời gian giữ</h1>\n  <p class=\"text-muted\">Đơn chưa được thanh toán trong {{ holdMin }} phút nên đã hết hiệu lực. Thông tin và người giới thiệu của bạn vẫn được giữ — bạn có thể đặt lại ngay.</p>\n  <div class=\"alert alert-info\" style=\"text-align:left\">{{{ icon('info', 20) }}}<div>Nếu bạn <strong>đã chuyển khoản</strong> cho đơn này, đừng chuyển lại. Liên hệ hỗ trợ {{ CONFIG.brand.supportHotline }} kèm mã đơn để được đối soát.</div></div>\n  <div class=\"actions actions-row\">\n    <a class=\"btn btn-secondary btn-lg\" href=\"#order-lookup\">Tra cứu đơn</a>\n    <button class=\"btn btn-primary btn-lg\" onclick=\"App.navigate('buy')\">{{{ icon('refresh', 18) }}} Đặt lại</button>\n  </div>\n</div></div>\n{% endblock %}\n\n{% block buyer/payment-gateway %}\n<!-- (b) Cổng online — loading rồi màn cổng giả lập -->\n<div class=\"card\"><div class=\"card-body\">\n  <div id=\"gw-loading\" class=\"gateway-sim\">\n    <div class=\"gateway-logo\">{{{ icon('zap', 20) }}} {{ CONFIG.gateway.label }}</div>\n    <p class=\"pulse text-strong\">Đang chuyển hướng tới cổng thanh toán…</p>\n    <p class=\"text-sm text-muted mt-2\">Vui lòng không đóng trình duyệt. Số tiền: <strong>{{{ money(order.price) }}}</strong> · Mã đơn <span class=\"mono\">{{ order.id }}</span></p>\n  </div>\n  <div id=\"gw-sim\" class=\"gateway-sim\" hidden>\n    <div class=\"gateway-logo\">{{{ icon('shield', 20) }}} Cổng thanh toán (mô phỏng)</div>\n    <p class=\"text-muted text-sm\">Màn hình này mô phỏng trang của cổng thanh toán. Khi tích hợp thật, cổng gọi callback về hệ thống và người mua được đưa về màn kết quả (order-result).</p>\n    <div class=\"actions\">\n      <button class=\"btn btn-success btn-lg btn-block\" onclick=\"Store.markPaid('{{ order.id }}', 'gateway'); App.navigate('order-result')\">{{{ icon('check', 18) }}} Thanh toán thành công (callback PAID)</button>\n      <button class=\"btn btn-danger-outline btn-lg btn-block\" onclick=\"Store.failOrder('{{ order.id }}'); App.navigate('payment')\">Huỷ giao dịch trên cổng (FAILED)</button>\n      <button class=\"btn btn-ghost\" onclick=\"App.navigate('payment')\">{{{ icon('arrow-left', 16) }}} Chọn phương thức khác</button>\n    </div>\n  </div>\n</div></div>\n{% endblock %}\n",
  "buyer/register": "<!-- register · Đăng ký thành viên: kiểm tra điều kiện → hồ sơ + T&C → OTP → chờ duyệt -->\n<div class=\"buyer-split\">\n  <aside class=\"buyer-side\">{{{ include('partials/intro-panel', intro) }}}</aside>\n  <div class=\"stack\" id=\"a06-col\">{{{ body }}}</div>\n</div>\n\n{% block buyer/register-blocked %}\n<!-- Không đủ điều kiện đăng ký (chưa mua / người giới thiệu Copper / bị từ chối / đã là thành viên) -->\n<div class=\"card\"><div class=\"card-body stack text-center\">\n  <div class=\"result-icon {{ iconClass }}\" style=\"margin:0 auto\">{{{ icon(ico, 34) }}}</div>\n  <h2>{{ title }}</h2>\n  <p class=\"text-muted\">{{{ desc }}}</p>\n  {% if agent %}\n  <div class=\"actions\"><a class=\"btn btn-primary btn-lg\" href=\"#login\">Đăng nhập</a></div>\n  {% else %}\n  <div class=\"actions actions-row\">\n    <a class=\"btn btn-secondary btn-lg\" href=\"#register\">Dùng số khác</a>\n    <a class=\"btn btn-primary btn-lg\" href=\"#order-lookup?phone={{ phone }}\">Tra cứu đơn hàng</a>\n  </div>\n  {% endif %}\n</div></div>\n{% endblock %}\n\n{% block buyer/register-check %}\n<div class=\"card\"><div class=\"card-body\">\n  <h2 class=\"mb-3\">Kiểm tra điều kiện đăng ký</h2>\n  <form novalidate onsubmit=\"Buyer.a06Lookup(event)\">\n    {{{ UI.field({ id: 'rg-phone', label: 'Số điện thoại đã mua gói', required: true, type: 'tel', mono: true, placeholder: '0912 345 678', attrs: 'inputmode=\"numeric\"' }) }}}\n    <div class=\"actions\"><button class=\"btn btn-primary btn-lg btn-block\">{{{ icon('search', 18) }}} Kiểm tra</button></div>\n  </form>\n</div></div>\n<div class=\"demo-hint\">SĐT mẫu: <strong>{{ phoneOk }}</strong> đủ điều kiện · <strong>{{ phoneCopper }}</strong> người giới thiệu Copper · <strong>0999999999</strong> chưa mua · <strong>0913000888</strong> đang chờ duyệt · <strong>0914000999</strong> bị từ chối</div>\n{% endblock %}\n\n{% block buyer/register-done %}\n<!-- Đăng ký đã gửi (bước 3/3) -->\n<div class=\"stack text-center\">\n  <div class=\"result-icon is-success\" style=\"margin:0 auto\">{{{ icon('check-circle', 34) }}}</div>\n  <h2>Hồ sơ đã gửi — {{{ badge('approval', 'PENDING_0', true) }}}</h2>\n  <p class=\"text-muted\">Mã hồ sơ <span class=\"mono text-strong\">{{ regId }}</span>. Bộ phận quản trị duyệt 2 lớp trong 1–2 ngày làm việc.</p>\n  <div class=\"alert alert-info\" style=\"text-align:left\">{{{ icon('sms', 20) }}}<div class=\"text-sm\">Khi được duyệt, email từ <strong>{{ CONFIG.email.from }}</strong> gửi tới <strong>{{ email }}</strong> gồm: link giới thiệu, link mua hàng cá nhân <span class=\"mono\">{{ alias }}</span> và cổng thành viên.</div></div>\n  <div class=\"actions actions-row\">\n    <a class=\"btn btn-secondary btn-lg\" href=\"#register?state=pending&phone={{ phone }}\">Xem trạng thái hồ sơ</a>\n    <a class=\"btn btn-primary btn-lg\" href=\"#home\">Về trang chủ</a>\n  </div>\n</div>\n{% endblock %}\n\n{% block buyer/register-form %}\n<!-- Hồ sơ thành viên (bước 1/3) -->\n<div class=\"card\">\n  <div class=\"card-head\"><h2>Hồ sơ thành viên</h2><span class=\"text-sm text-muted\">Bước 1/3</span></div>\n  <div class=\"card-body\" id=\"a06-body\">\n    {% if rejReason !== null %}\n    <div class=\"alert alert-warning mb-4\">{{{ icon('warning', 18) }}}<div class=\"text-sm\"><span class=\"alert-title\">Hồ sơ trước bị từ chối</span>{{ rejReason }}. Vui lòng kiểm tra và nộp lại.</div></div>\n    {% endif %}\n    <div class=\"alert alert-info mb-4\">{{{ icon('users', 18) }}}<div class=\"text-sm\">Người giới thiệu: <strong>{{ ref.fullName }}</strong> · {{ RULES.rank(ref.rank).label }} · đơn <span class=\"mono\">{{ o.id }}</span>. Bạn sẽ thuộc tuyến của người này (khoá tại thời điểm mua).</div></div>\n\n    <form novalidate onsubmit=\"Buyer.a06Submit(event, '{{ phone }}')\">\n      {{{ UI.field({ id: 'rg-name', label: 'Họ và tên', required: true, value: d.fullName, hint: 'Dùng để tạo link mua hàng cá nhân', attrs: 'oninput=\"Buyer.a06Alias(\\'' + phone + '\\')\"' }) }}}\n      <div class=\"text-sm text-muted mt-1\">Link cá nhân dự kiến: <span class=\"mono text-strong\" id=\"rg-alias\">{{ alias }}</span></div>\n      <div class=\"form-grid form-grid-2 mt-4\">\n        {{{ UI.field({ id: 'rg-email', label: 'Email', required: true, type: 'email', value: d.email }) }}}\n        {{{ UI.field({ id: 'rg-phone2', label: 'Số điện thoại', value: phone, mono: true, attrs: 'readonly' }) }}}\n      </div>\n\n      <h3 class=\"mt-6 mb-2\">Tài khoản nhận hoa hồng</h3>\n      <div class=\"form-grid form-grid-2\">\n        {{{ UI.field({ id: 'rg-bank', label: 'Ngân hàng', required: true, type: 'select', value: d.bankName, options: bankOptions }) }}}\n        {{{ UI.field({ id: 'rg-acc', label: 'Số tài khoản', required: true, mono: true, value: d.accountNo, attrs: 'inputmode=\"numeric\"' }) }}}\n      </div>\n      <div class=\"mt-4\">{{{ UI.field({ id: 'rg-owner', label: 'Chủ tài khoản', required: true, value: d.owner, placeholder: 'NGUYEN VAN A', hint: 'Viết in hoa không dấu, trùng họ tên' }) }}}</div>\n\n      <h3 class=\"mt-6 mb-2\">Mật khẩu đăng nhập</h3>\n      <div class=\"form-grid form-grid-2\">\n        {{{ UI.field({ id: 'rg-pw', label: 'Mật khẩu', required: true, type: 'password', hint: 'Tối thiểu 8 ký tự, có chữ và số' }) }}}\n        {{{ UI.field({ id: 'rg-pw2', label: 'Nhập lại mật khẩu', required: true, type: 'password' }) }}}\n      </div>\n\n      <h3 class=\"mt-6 mb-2\">Điều khoản &amp; điều kiện <span class=\"badge badge-navy badge-plain\">v{{ tc.version }}</span></h3>\n      <div class=\"tc-box\" tabindex=\"0\">{{ tc.text }}</div>\n      <label class=\"check mt-3\"><input type=\"checkbox\" id=\"rg-tc\"> Tôi đã đọc và đồng ý với Điều khoản &amp; điều kiện phiên bản {{ tc.version }}</label>\n      <div class=\"field-error\" id=\"rg-tc-err\"></div>\n      <div id=\"a06-alert\" hidden></div>\n      <div class=\"actions\"><button class=\"btn btn-primary btn-lg btn-block\">{{{ icon('sms', 18) }}} Gửi OTP &amp; nộp hồ sơ</button></div>\n    </form>\n  </div>\n</div>\n{% endblock %}\n\n{% block buyer/register-status %}\n<!-- Trạng thái hồ sơ đăng ký: chờ duyệt / đã duyệt / bị từ chối -->\n<div class=\"card\"><div class=\"card-body stack\">\n  <div class=\"text-center\">\n    <div class=\"result-icon {% if reg.status === 'APPROVED' %}is-success{% elif reg.status === 'REJECTED' %}is-error{% else %}is-pending{% endif %}\" style=\"margin:0 auto\">{{{ icon(reg.status === 'APPROVED' ? 'check-circle' : reg.status === 'REJECTED' ? 'x-circle' : 'clock', 34) }}}</div>\n    <h2 class=\"mt-3\">{% if reg.status === 'APPROVED' %}Hồ sơ đã được duyệt{% elif reg.status === 'REJECTED' %}Hồ sơ bị từ chối{% else %}Hồ sơ đang chờ duyệt{% endif %}</h2>\n    <div class=\"mt-2\">{{{ badge('approval', reg.status, true) }}}</div>\n  </div>\n\n  <div class=\"steps\" style=\"justify-content:center\">\n    {% each s, i in steps %}\n    <div class=\"step {% if s.done %}is-done{% endif %}\"><span class=\"step-dot\">{% if s.done %}{{{ icon('check', 14) }}}{% else %}{{ i + 1 }}{% endif %}</span><span>{{ s.label }}</span></div>\n    {% if i < steps.length - 1 %}<span class=\"step-line\"></span>{% endif %}\n    {% endeach %}\n  </div>\n\n  <dl class=\"dl\">\n    <dt>Mã hồ sơ</dt><dd class=\"mono\">{{ reg.id }}</dd>\n    <dt>Nộp lúc</dt><dd>{{{ dt(reg.createdAt) }}}</dd>\n    <dt>Người giới thiệu</dt><dd>{{ referrerName || '—' }}</dd>\n  </dl>\n\n  {% if rej %}\n  <div class=\"alert alert-error\">{{{ icon('x-circle', 18) }}}<div><span class=\"alert-title\">Lý do từ chối</span>{{ rej.reason || '' }}</div></div>\n  {% else %}\n  <div class=\"alert alert-info\">{{{ icon('sms', 18) }}}<div class=\"text-sm\">Khi được duyệt, bạn nhận email từ <strong>{{ CONFIG.email.from }}</strong> gồm link giới thiệu, link mua hàng cá nhân và cổng thành viên.</div></div>\n  {% endif %}\n\n  <div class=\"actions actions-row\">\n    {% if reg.status === 'REJECTED' && CONFIG.rules.rejectedCanResubmit %}<a class=\"btn btn-primary btn-lg\" href=\"#register?phone={{ phone }}&resubmit=1\">Nộp lại hồ sơ</a>{% endif %}\n    {% if reg.status === 'APPROVED' %}<a class=\"btn btn-primary btn-lg\" href=\"#login\">Đăng nhập thành viên</a>{% else %}<a class=\"btn btn-secondary btn-lg\" href=\"#login\">Về đăng nhập</a>{% endif %}\n  </div>\n</div></div>\n{% endblock %}\n",
  "common/common": "{% block common/403 %}\n<div class=\"error-page\">\n  <div class=\"card error-card\">\n    <div class=\"card-body stack\">\n      <div class=\"result-icon is-error\" style=\"margin:0 auto\">{{{ icon('ban', 36) }}}</div>\n      <div class=\"error-code\">403 · FORBIDDEN</div>\n      {% if spec %}\n      <h1>Chỉ Head Admin mới truy cập được mục này</h1>\n      <p class=\"text-muted\">Quản lý tài khoản admin (admin-users) thuộc quyền Head Admin. Tài khoản Admin Specialist của bạn không có quyền này.</p>\n      <div class=\"actions actions-row\"><a class=\"btn btn-primary btn-lg\" href=\"#admin-dashboard\">Về tổng quan quản trị</a></div>\n      {% else %}\n      <h1>Bạn không có quyền truy cập khu vực quản trị</h1>\n      <p class=\"text-muted\">Phiên hiện tại là phiên thành viên. Khu vực quản trị yêu cầu tài khoản quản trị viên đăng nhập bằng tên đăng nhập và mật khẩu.</p>\n      <div class=\"actions actions-row\">\n        <a class=\"btn btn-secondary btn-lg\" href=\"#dashboard\">Về Dashboard thành viên</a>\n        <a class=\"btn btn-primary btn-lg\" href=\"#admin-login\">Đăng nhập quản trị</a>\n      </div>\n      {% endif %}\n    </div>\n  </div>\n</div>\n{% endblock %}\n\n{% block common/demo-nav %}\n<div class=\"row-between\"><strong>Demo navigator</strong><button class=\"modal-close\" aria-label=\"Đóng\" onclick=\"App.toggleDemoNav()\">{{{ icon('x', 18) }}}</button></div>\n{% each g in groups %}\n<h4>{{ g.title }}</h4>\n{% each it in g.items %}<a class=\"demo-link\" href=\"#{{ it.hash }}\" onclick=\"App.toggleDemoNav()\"><code>#{{ it.hash.split('?')[0] }}</code>{{ it.label }}</a>{% endeach %}\n{% endeach %}\n<h4>Tiện ích</h4>\n<a class=\"demo-link\" href=\"javascript:void(0)\" onclick=\"Store.loginAgentById('U001'); App.toggleDemoNav(); App.navigate('dashboard')\">Đăng nhập nhanh thành viên An</a>\n<a class=\"demo-link\" href=\"javascript:void(0)\" onclick=\"Store.adminLogin('head','Homi@2026'); App.toggleDemoNav(); App.navigate('admin-dashboard')\">Đăng nhập nhanh Head Admin</a>\n<a class=\"demo-link\" href=\"javascript:void(0)\" onclick=\"Store.expireAgentSession(); App.toggleDemoNav(); App.navigate('dashboard')\">Giả lập hết phiên</a>\n<a class=\"demo-link\" href=\"javascript:void(0)\" onclick=\"Store.otpResetAll(); UI.toast('Đã gỡ mọi khoá OTP.')\">Gỡ khoá OTP</a>\n<a class=\"demo-link text-error\" href=\"javascript:void(0)\" onclick=\"if (confirm('Nạp lại toàn bộ dữ liệu mẫu?')) Store.reset()\">Nạp lại dữ liệu mẫu</a>\n{% endblock %}\n\n{% block common/home %}\n<div class=\"buyer\">\n  <header class=\"buyer-header\">\n    <div class=\"buyer-header-inner\">{{{ UI.logo({ size: 34 }) }}}<span class=\"text-sm text-muted\">Prototype v2 · spec v3 · 05/09/2026</span></div>\n  </header>\n\n  <main class=\"buyer-main\">\n    <div class=\"stack-lg\">\n      <div class=\"text-center\">\n        <h1>Prototype giao diện HOMI365 · Medigo</h1>\n        <p class=\"text-muted mt-2\">Bản mô phỏng luồng mua hàng, đăng ký &amp; dashboard thành viên và quản trị (CHANGE SPEC v3). Dữ liệu mẫu lưu trên trình duyệt của bạn. Mã OTP dùng chung: <strong class=\"mono\">{{ CONFIG.otp.mockCode }}</strong>.</p>\n      </div>\n\n      <div class=\"grid-2\">\n        <!-- Người mua -->\n        <div class=\"card\"><div class=\"card-body\">\n          <div class=\"row mb-2\"><span class=\"result-icon is-info\" style=\"width:44px;height:44px;margin:0\">{{{ icon('users', 22) }}}</span><h2 style=\"font-size:var(--fs-lg)\">Người mua</h2></div>\n          <p class=\"text-sm text-muted\">Vào bằng link giới thiệu hoặc link mua hàng cá nhân của thành viên. Họ tên · SĐT · email · địa chỉ → OTP → thanh toán → kết quả.</p>\n          <dl class=\"dl dl-stack mt-3\">\n            <dt>Link giới thiệu (ref_code)</dt><dd><span class=\"mono\">{{ RULES.referralUrl(an.refCode) }}</span></dd>\n            <dt>Link mua hàng cá nhân (alias)</dt><dd><span class=\"mono\">{{ RULES.purchaseUrl(an.purchaseAlias) }}</span></dd>\n            <dt>SĐT gây lỗi gửi SMS</dt><dd><span class=\"mono\">{{ CONFIG.demo.smsErrorPhone }}</span></dd>\n          </dl>\n          <div class=\"actions\">\n            <a class=\"btn btn-primary btn-lg btn-block\" href=\"{{ RULES.referralHash(an.refCode) }}\">{{{ icon('external', 18) }}} Mở link giới thiệu mẫu</a>\n            <a class=\"btn btn-secondary btn-block\" href=\"{{ RULES.purchaseHash(an.purchaseAlias) }}\">Mở link mua hàng cá nhân {{ an.purchaseAlias }}</a>\n          </div>\n        </div></div>\n\n        <!-- Đăng ký thành viên -->\n        <div class=\"card\"><div class=\"card-body\">\n          <div class=\"row mb-2\"><span class=\"result-icon is-info\" style=\"width:44px;height:44px;margin:0\">{{{ icon('user', 22) }}}</span><h2 style=\"font-size:var(--fs-lg)\">Đăng ký thành viên</h2></div>\n          <p class=\"text-sm text-muted\">Sau khi mua, người mua đăng ký thành viên (hồ sơ + T&amp;C + OTP) và chờ admin duyệt 2 lớp. Chỉ người giới thiệu từ hạng Silver mới được tuyển.</p>\n          <dl class=\"dl dl-stack mt-3\">\n            <dt>Đã mua qua Lithium — đăng ký được</dt><dd><span class=\"mono\">{{ kim.phone }}</span> · {{ kim.fullName }}</dd>\n            <dt>Đã mua qua Copper — bị chặn</dt><dd><span class=\"mono\">{{ bao.phone }}</span> · {{ bao.fullName }}</dd>\n            <dt>Hồ sơ đang chờ duyệt (1/2)</dt><dd><span class=\"mono\">0913000888</span></dd>\n            <dt>Hồ sơ bị từ chối</dt><dd><span class=\"mono\">0914000999</span></dd>\n          </dl>\n          <div class=\"actions\">\n            <a class=\"btn btn-primary btn-lg btn-block\" href=\"#register\">{{{ icon('user', 18) }}} Đăng ký thành viên</a>\n            <a class=\"btn btn-secondary btn-block\" href=\"#order-lookup\">Tra cứu đơn hàng (mã đơn mẫu <span class=\"mono\">{{ paidOrderId }}</span>)</a>\n          </div>\n        </div></div>\n\n        <!-- Thành viên -->\n        <div class=\"card\"><div class=\"card-body\">\n          <div class=\"row mb-2\"><span class=\"result-icon is-info\" style=\"width:44px;height:44px;margin:0\">{{{ icon('key', 22) }}}</span><h2 style=\"font-size:var(--fs-lg)\">Thành viên</h2></div>\n          <p class=\"text-sm text-muted\">Đăng nhập bằng SĐT + mật khẩu (quên mật khẩu qua OTP). Dashboard: hạng &amp; điểm, 2 link, thống kê, hoa hồng chênh lệch, F1, ví &amp; rút tiền 1 lần/tháng.</p>\n          <dl class=\"dl dl-stack mt-3\">\n            <dt>Thành viên Lithium</dt><dd><span class=\"mono\">{{ an.phone }}</span> / <span class=\"mono\">{{ CONFIG.demo.agentPassword }}</span> · {{ an.fullName }}</dd>\n            <dt>Gold · Silver · Copper</dt><dd><span class=\"mono\">0912345678</span> · <span class=\"mono\">0933222111</span> · <span class=\"mono\">0987654321</span> (cùng mật khẩu)</dd>\n            <dt>Bị khoá</dt><dd><span class=\"mono\">0977000111</span></dd>\n          </dl>\n          <div class=\"actions\"><a class=\"btn btn-primary btn-lg btn-block\" href=\"#login\">{{{ icon('key', 18) }}} Đăng nhập thành viên</a></div>\n        </div></div>\n\n        <!-- Quản trị -->\n        <div class=\"card\"><div class=\"card-body\">\n          <div class=\"row mb-2\"><span class=\"result-icon is-info\" style=\"width:44px;height:44px;margin:0\">{{{ icon('shield', 22) }}}</span><h2 style=\"font-size:var(--fs-lg)\">Quản trị</h2></div>\n          <p class=\"text-sm text-muted\">2 vai trò: Admin Specialist (duyệt lớp 1/2) và Head Admin (tự chốt, quản lý tài khoản admin, chỉ định hạng, tạo thành viên gốc, chạy job xét hạng).</p>\n          <dl class=\"dl dl-stack mt-3\">\n            <dt>Head Admin</dt><dd><span class=\"mono\">head</span> / <span class=\"mono\">Homi@2026</span></dd>\n            <dt>Admin Specialist</dt><dd><span class=\"mono\">admin</span> · <span class=\"mono\">admin2</span> / <span class=\"mono\">Homi@2026</span></dd>\n            <dt>Việc đang chờ</dt><dd>{{ pending.regs }} đăng ký · {{ pending.wds }} rút tiền · {{ pending.awaiting }} đối soát</dd>\n          </dl>\n          <div class=\"actions\"><a class=\"btn btn-primary btn-lg btn-block\" href=\"#admin-login\">{{{ icon('shield', 18) }}} Đăng nhập quản trị</a></div>\n        </div></div>\n      </div>\n\n      <div class=\"alert alert-neutral\">{{{ icon('info', 18) }}}<div class=\"text-sm\">Muốn xem lại từ đầu với dữ liệu gốc: <button class=\"btn-link\" onclick=\"if (confirm('Nạp lại toàn bộ dữ liệu mẫu? Mọi thao tác đã làm sẽ mất.')) Store.reset()\">nạp lại dữ liệu mẫu</button>. Bộ thành phần giao diện: <a href=\"./styleguide.html\">styleguide</a>.</div></div>\n    </div>\n  </main>\n\n  <footer class=\"buyer-footer\">{{ CONFIG.brand.company }}</footer>\n</div>\n{% endblock %}\n\n{% block common/policy %}\n<div class=\"policy\">\n  <nav class=\"policy-crumb\" aria-label=\"Breadcrumb\"><a href=\"#home\">Trang chủ</a><span>/</span><span>{{ p.title }}</span></nav>\n  <div class=\"policy-grid\">\n    <article class=\"policy-body\">\n      <h1>{{ p.title }}</h1>\n      {% if p.intro %}<p class=\"policy-intro\">{{ p.intro }}</p>{% endif %}\n\n      {% each sec, i in p.sections %}\n      <section class=\"policy-section\" id=\"sec-{{ i + 1 }}\">\n        <h2>{{ sec.h }}</h2>\n        {% each it in sec.items %}\n          {% if typeof it === 'string' %}\n          <p>{{ it }}</p>\n          {% elif it.list %}\n          <ul class=\"policy-list\">{% each t in it.list %}<li>{{ t }}</li>{% endeach %}</ul>\n          {% elif it.steps %}\n          <ol class=\"policy-steps\">{% each t, k in it.steps %}<li><strong>Bước {{ k + 1 }}:</strong> {{ t }}</li>{% endeach %}</ol>\n          {% endif %}\n        {% endeach %}\n      </section>\n      {% endeach %}\n\n      <p class=\"text-caption mt-6\">Cập nhật 09/2026 · {{ CONFIG.brand.company }} · Hỗ trợ {{ CONFIG.brand.supportHotline }}</p>\n    </article>\n\n    <aside class=\"policy-side\">\n      <div class=\"policy-menu\">\n        <div class=\"policy-menu-title\">Danh mục chính sách</div>\n        {% each x in POLICIES %}\n        <a href=\"#policy?s={{ x.id }}\" class=\"{% if x.id === p.id %}is-active{% endif %}\" {% if x.id === p.id %}aria-current=\"page\"{% endif %}>{{ x.title }}</a>\n        {% endeach %}\n      </div>\n    </aside>\n  </div>\n</div>\n{% endblock %}\n\n{% block common/shell-admin %}\n<div class=\"admin\">\n  <aside class=\"admin-sidebar\" id=\"admin-sidebar\">\n    <div class=\"admin-sidebar-brand\">{{{ UI.logo({ size: 30, invert: true }) }}}<span class=\"sub\">Quản trị HOMI365</span></div>\n    <nav class=\"admin-nav\" aria-label=\"Menu quản trị\">\n      {% each it in items %}\n        {% if it.group %}\n        <div class=\"admin-nav-group\">{{ it.group }}</div>\n        {% else %}\n        <a href=\"#{{ it.code }}\" class=\"{% if active === it.code %}is-active{% endif %}\">\n          {{{ icon(it.ico, 18) }}}<span>{{ it.label }}</span>\n          {% if it.badge %}<span class=\"nav-badge\">{{ it.badge }}</span>{% else %}<span class=\"nav-code\">{{ it.code }}</span>{% endif %}\n        </a>\n        {% endif %}\n      {% endeach %}\n    </nav>\n    <div class=\"admin-sidebar-foot\">\n      <div class=\"who\">{{ me.fullName || me.username }}</div>\n      <div class=\"role\">{{ roleLabel }} · {{ me.username }}</div>\n      <button class=\"btn btn-sm btn-secondary\" onclick=\"App.logoutAdmin()\">{{{ icon('logout', 16) }}} Đăng xuất</button>\n    </div>\n  </aside>\n\n  <div class=\"admin-content\">\n    <div class=\"admin-topbar\">\n      <div class=\"row\">\n        <button class=\"btn btn-icon btn-secondary admin-menu-btn\" aria-label=\"Mở menu\" onclick=\"document.getElementById('admin-sidebar').classList.toggle('is-open')\">{{{ icon('menu', 20) }}}</button>\n        <div><div class=\"crumb\">{{ active }}</div><h1>{{{ title }}}</h1></div>\n      </div>\n      <div class=\"row\">{{{ actions }}}</div>\n    </div>\n    <main class=\"admin-main\">{{{ content }}}</main>\n  </div>\n</div>\n{% endblock %}\n\n{% block common/shell-buyer %}\n<div class=\"buyer\">\n  <header class=\"buyer-header\">\n    <div class=\"buyer-header-inner\">\n      <a href=\"#home\" class=\"brand\" aria-label=\"HOMI365 — trang giới thiệu\">{{{ UI.logo({ size: 34 }) }}}</a>\n      <nav class=\"buyer-nav\" aria-label=\"Điều hướng\">\n        <a href=\"#order-lookup\" class=\"{% if cur === 'order-lookup' %}is-active{% endif %}\">{{{ icon('search', 18) }}}<span>Tra cứu đơn hàng</span></a>\n        <a href=\"#login\" class=\"{% if cur === 'login' %}is-active{% endif %}\">{{{ icon('key', 18) }}}<span>Đăng nhập thành viên</span></a>\n      </nav>\n    </div>\n  </header>\n\n  {% if showRef && seller %}\n  <div class=\"ref-bar\">Người giới thiệu: <strong>{{ seller.fullName }}</strong> · mã <span class=\"mono\">{{ seller.refCode }}</span></div>\n  {% endif %}\n\n  <main class=\"buyer-main {% if narrow %}buyer-main-narrow{% endif %}\" id=\"buyer-main\">{{{ content }}}</main>\n\n  <footer class=\"site-footer\">\n    <div class=\"site-footer-inner\">\n      <div>\n        {{{ UI.logo({ size: 28 }) }}}\n        <p class=\"mt-2\">{{ CONFIG.brand.company }}</p>\n        <p>Hỗ trợ <strong>{{ CONFIG.brand.supportHotline }}</strong> · {{ CONFIG.brand.supportHours }}</p>\n      </div>\n      <div>\n        <div class=\"footer-title\">Khách hàng</div>\n        <a href=\"#order-lookup\">Tra cứu đơn hàng</a>\n        <a href=\"#login\">Đăng nhập thành viên</a>\n        <a href=\"#register\">Đăng ký thành viên</a>\n        <a href=\"#home\">Trang giới thiệu prototype</a>\n      </div>\n      <div>\n        <div class=\"footer-title\">Chính sách</div>\n        {% each p in POLICIES %}<a href=\"#policy?s={{ p.id }}\">{{ p.title }}</a>{% endeach %}\n      </div>\n      <div>\n        <div class=\"footer-title\">Quản trị</div>\n        <a href=\"#admin-login\">Đăng nhập quản trị</a>\n        <a href=\"./styleguide.html\">Bộ thành phần giao diện</a>\n      </div>\n    </div>\n  </footer>\n</div>\n{% endblock %}\n\n{% block common/shell-seller %}\n<div class=\"seller\">\n  <header class=\"seller-header\">\n    <div class=\"seller-header-inner\">\n      <a href=\"#dashboard\" class=\"brand\" aria-label=\"HOMI365\">{{{ UI.logo({ size: 34 }) }}}</a>\n      <nav class=\"seller-nav-top\" aria-label=\"Điều hướng thành viên\">\n        {% each n in nav %}<a href=\"#{{ n.code }}\" class=\"{% if active === n.code %}is-active{% endif %}\">{{{ icon(n.ico, 22) }}}<span>{{ n.label }}</span></a>{% endeach %}\n      </nav>\n      <div class=\"seller-user\">\n        <button class=\"seller-user-btn\" id=\"seller-user-btn\" aria-haspopup=\"true\" aria-expanded=\"false\" onclick=\"App.toggleSellerMenu()\">\n          <span class=\"avatar\" aria-hidden=\"true\">{{ RULES.initials(u.fullName) }}</span>\n          <span class=\"seller-user-name\">{{ u.fullName }}</span>\n          {{{ badge('rank', u.rank) }}}{{{ icon('chevron-down', 16) }}}\n        </button>\n        <div class=\"seller-menu\" id=\"seller-menu\" hidden>\n          <div class=\"seller-menu-head\">\n            <div class=\"name\">{{ u.fullName }}</div>\n            <div class=\"sub\">{{ RULES.maskPhone(u.phone) }} · {{ u.refCode }}</div>\n            <div class=\"mt-1\">{{{ badge('rank', u.rank) }}}</div>\n          </div>\n          <a href=\"#profile\">{{{ icon('user', 18) }}} Hồ sơ của tôi</a>\n          <button class=\"danger\" onclick=\"App.logoutAgent()\">{{{ icon('logout', 18) }}} Đăng xuất</button>\n        </div>\n      </div>\n    </div>\n  </header>\n\n  <main class=\"seller-main\">{{{ content }}}</main>\n\n  <nav class=\"seller-nav-bottom\" aria-label=\"Điều hướng thành viên\">\n    {% each n in nav %}<a href=\"#{{ n.code }}\" class=\"{% if active === n.code %}is-active{% endif %}\">{{{ icon(n.ico, 22) }}}<span>{{ n.label }}</span></a>{% endeach %}\n  </nav>\n</div>\n{% endblock %}\n",
  "common/partials": "{% block partials/admin-actions %}\n<!-- Nút hành động góc phải topbar admin, theo màn (screen = 'agents' | 'products' | 'inventory' | 'admin-users') -->\n{% if screen === 'agents' %}\n<button class=\"btn btn-primary\" onclick=\"Admin.rootAgentModal()\">{{{ icon('plus', 16) }}} Tạo thành viên gốc</button>\n{% elif screen === 'products' %}\n<button class=\"btn btn-primary\" onclick=\"Admin.packageForm()\">{{{ icon('plus', 16) }}} Thêm gói</button>\n{% elif screen === 'inventory' %}\n<button class=\"btn btn-secondary\" onclick=\"Admin.importModal()\">{{{ icon('upload', 16) }}} Nhập file</button>\n<button class=\"btn btn-primary\" onclick=\"Admin.generateModal()\">{{{ icon('plus', 16) }}} Sinh hàng loạt</button>\n{% elif screen === 'admin-users' %}\n<button class=\"btn btn-primary\" onclick=\"Admin.adminForm()\">{{{ icon('plus', 16) }}} Thêm tài khoản</button>\n{% endif %}\n{% endblock %}\n\n{% block partials/admin-approval-cell %}\n<!-- Ô \"Tiến trình\" duyệt 2 lớp (rút tiền / đăng ký): badge trạng thái + từng lượt xác nhận + lý do từ chối -->\n{{{ badge(kind, e.status) }}}\n{% each a in approvals %}\n<span class=\"cell-sub\">{{{ icon('check', 12) }}} {{ a.by }} · {{ LABELS.role[a.role] ? LABELS.role[a.role].text : a.role }} · {{ dt(a.at) }}</span>\n{% endeach %}\n{% if rejection %}\n<span class=\"cell-sub text-error\">{{ rejection.by }}: {{ rejection.reason || '' }}</span>\n{% endif %}\n{% endblock %}\n\n{% block partials/admin-audit-list %}\n<!-- Danh sách audit của một thực thể: list = Store.auditOf(entity, id) -->\n{% if list.length %}\n<ul class=\"timeline\">\n  {% each a in list %}\n  <li><span class=\"timeline-time\">{{ dt(a.at) }}</span><span class=\"timeline-text\"><strong>{{ a.actor }}</strong> {% if a.from || a.to %}<span class=\"mono\">{{ a.from || '—' }} → {{ a.to || '—' }}</span> {% endif %}{{ a.note || '' }}</span></li>\n  {% endeach %}\n</ul>\n{% else %}\n<p class=\"text-muted\">Chưa có</p>\n{% endif %}\n{% endblock %}\n\n{% block partials/admin-period-seg %}\n<!-- Bộ chọn kỳ thống kê (tuần / tháng / quý) trên admin-dashboard -->\n<div class=\"seg\" role=\"group\" aria-label=\"Kỳ\">\n  {% each p in periods %}\n  <button class=\"{{ period === p.id ? 'is-active' : '' }}\" onclick=\"Admin.st.period='{{ p.id }}'; App.reload()\">{{{ p.label }}}</button>\n  {% endeach %}\n</div>\n{% endblock %}\n\n{% block partials/admin-timeline %}\n<!-- Dòng thời gian đơn giản: rows = [{ at, text }] -->\n<ul class=\"timeline\">\n  {% each r in rows %}\n  <li><span class=\"timeline-time\">{{ dt(r.at) }}</span><span class=\"timeline-text\">{{ r.text }}</span></li>\n  {% endeach %}\n</ul>\n{% endblock %}\n\n{% block partials/admin-tree %}\n<!-- Cây tuyến dưới (đệ quy): nodes = [{ user, sold, children }] -->\n{% if nodes.length %}\n<ul class=\"tree\">\n  {% each n in nodes %}\n  <li>\n    <span class=\"tree-node\"><strong>{{ n.user.fullName }}</strong> {{{ n.user.rank ? badge('rank', n.user.rank) : badge('userType', 'buyer') }}} <span class=\"text-sm text-muted\">· {{ n.sold }} đơn · <span class=\"mono\">{{ n.user.refCode || n.user.phone }}</span></span> <button class=\"btn-link\" onclick=\"Admin.userDrawer('{{ n.user.id }}')\">Xem</button></span>\n    {{{ include('partials/admin-tree', { nodes: n.children }) }}}\n  </li>\n  {% endeach %}\n</ul>\n{% endif %}\n{% endblock %}\n\n{% block partials/alert %}\n<div class=\"alert alert-{{ tone }}{% if cls %} {{ cls }}{% endif %}\" role=\"alert\">{{{ icon(ico, size || 22) }}}<div>{% if title %}<span class=\"alert-title\">{{{ title }}}</span>{% endif %}{{{ text }}}</div></div>\n{% endblock %}\n\n{% block partials/btn-reload %}\n<button class=\"btn btn-secondary\" onclick=\"App.reload()\">{{{ icon('arrow-left', 16) }}} {{ label }}</button>\n{% endblock %}\n\n{% block partials/card-head %}\n<h2>{{ title }}</h2><span class=\"text-sm text-muted\">{{ step }}</span>\n{% endblock %}\n\n{% block partials/intro-panel %}\n<div class=\"intro-panel\">\n  <h1>{{{ title }}}</h1>\n  <p>{{{ desc }}}</p>\n  <ol class=\"intro-steps\">{% each t in steps %}<li>{{{ t }}}</li>{% endeach %}</ol>\n</div>\n{% endblock %}\n\n{% block partials/order-info %}\n<dl class=\"dl\">\n  <dt>Mã đơn hàng</dt><dd class=\"mono\">{{ order.id }}</dd>\n  <dt>Gói</dt><dd>{{ pkgName }}</dd>\n  <dt>Số tiền</dt><dd>{{{ money(order.price) }}}</dd>\n  <dt>Phương thức</dt><dd>{{ LABELS.method[order.method] || '—' }}</dd>\n  <dt>Người nhận</dt><dd>{{ order.fullName }} · <span class=\"mono\">{{ RULES.maskPhone(order.phone) }}</span></dd>\n  {% if shipping %}<dt>Giao hàng</dt><dd>{{{ badge('shipping', order.shipping) }}}</dd>{% endif %}\n</dl>\n{% endblock %}\n\n{% block partials/otp-frame %}\n<h2 class=\"text-center mb-4\">{{ title }}</h2><div id=\"{{ id }}\"></div>\n{% endblock %}\n\n{% block partials/pkg-header %}\n<div class=\"pkg\">\n  <div class=\"pkg-icon\">{{{ icon('watch', 30) }}}</div>\n  <div class=\"grow\">\n    <{{{ tag }}} class=\"pkg-name\">{{ pkg.name }}</{{{ tag }}}>\n    <div class=\"pkg-meta\">{{ pkg.id }} · License {{ pkg.licenseMonths }} tháng{% if pkg.hasShipping %} · kèm đồng hồ HW01{% endif %}</div>\n  </div>\n  <div class=\"pkg-price\">{{{ money(pkg.price) }}}</div>\n</div>\n{% endblock %}\n\n{% block partials/product-intro %}\n{% if !pc %}\n<div class=\"card\"><div class=\"card-body\">\n  <p class=\"text-sm text-muted\">{{ pkg.desc }}</p>\n  <ul class=\"pkg-benefits\">{% each b in pkg.benefits %}<li>{{{ icon('check', 16) }}}<span>{{ b }}</span></li>{% endeach %}</ul>\n</div></div>\n{% else %}\n<div class=\"card product-card\">\n  <div class=\"gallery\">\n    <div class=\"gallery-main\" id=\"gallery-main\" tabindex=\"0\" role=\"group\" aria-roledescription=\"carousel\" aria-label=\"Ảnh giới thiệu gói {{ pkg.id }}\">\n      <img id=\"gallery-img\" src=\"{{ g0.src }}\" alt=\"{{ g0.title }}\" width=\"1890\" height=\"1063\" decoding=\"async\" draggable=\"false\">\n      <button class=\"gallery-nav gallery-nav-prev\" aria-label=\"Ảnh trước\" onclick=\"Buyer.galleryStep(-1)\">{{{ icon('arrow-left', 18) }}}</button>\n      <button class=\"gallery-nav gallery-nav-next\" aria-label=\"Ảnh kế tiếp\" onclick=\"Buyer.galleryStep(1)\">{{{ icon('arrow-right', 18) }}}</button>\n      <span class=\"gallery-caption\" id=\"gallery-caption\" aria-live=\"polite\">{{ g0.title }}</span>\n    </div>\n    <div class=\"gallery-thumbs\" role=\"tablist\" aria-label=\"Chọn ảnh\">\n      {% each g, i in pc.gallery %}\n      <button class=\"gallery-thumb {% if i === 0 %}is-active{% endif %}\" role=\"tab\" id=\"gthumb-{{ i }}\" aria-selected=\"{{ i === 0 }}\" title=\"{{ g.title }}\" onclick=\"Buyer.galleryTo({{ i }})\">\n        <img src=\"{{ g.thumb }}\" alt=\"\" loading=\"lazy\" decoding=\"async\" draggable=\"false\"><span class=\"sr-only\">{{ g.title }}</span>\n      </button>\n      {% endeach %}\n    </div>\n  </div>\n  <div class=\"card-body\">\n    <p>{{ pc.lead }}</p>\n    <ul class=\"pkg-benefits\">{% each b in pkg.benefits %}<li>{{{ icon('check', 16) }}}<span>{{ b }}</span></li>{% endeach %}</ul>\n  </div>\n</div>\n\n<div class=\"card\">\n  <div class=\"card-head\">\n    <h2 style=\"font-size:var(--fs-lg)\">Chi tiết tính năng gói {{ pkg.id }}</h2>\n    <button class=\"btn btn-ghost btn-sm\" id=\"feat-toggle\" aria-expanded=\"false\" aria-controls=\"feat-body\" onclick=\"Buyer.toggleFeatures()\">Xem chi tiết {{{ icon('chevron-down', 18) }}}</button>\n  </div>\n  <div class=\"card-body\" id=\"feat-body\" hidden>\n    <p class=\"text-sm text-muted\">{{ pc.intro }}</p>\n    <div class=\"feature-list mt-3\">\n      {% each f, i in pc.features %}\n      <details class=\"feature\" {% if i === 0 %}open{% endif %}>\n        <summary>{{ i + 1 }}. {{ f.title }}</summary>\n        <ul>{% each t in f.items %}<li>{{ t }}</li>{% endeach %}</ul>\n      </details>\n      {% endeach %}\n    </div>\n  </div>\n</div>\n{% endif %}\n{% endblock %}\n\n{% block partials/reg-cta %}\n{% if el.ok %}\n<div class=\"row\">\n  <span class=\"result-icon is-info\" style=\"width:44px;height:44px;margin:0\">{{{ icon('gift', 22) }}}</span>\n  <div class=\"grow\"><h2 style=\"font-size:var(--fs-lg)\">Trở thành thành viên HOMI365</h2>\n    <p class=\"text-sm text-muted\">Được {{ ref ? ref.fullName : 'người giới thiệu' }} (hạng {{ refRankLabel }}) mời tham gia. Đăng ký hồ sơ để nhận link bán hàng cá nhân và hoa hồng theo hạng; hồ sơ được duyệt trong 1–2 ngày làm việc.</p></div>\n</div>\n<div class=\"actions actions-row\">\n  <button class=\"btn btn-secondary btn-lg\" onclick=\"Buyer.a03Later('{{ order.id }}', true)\">Thoát ra</button>\n  <a class=\"btn btn-primary btn-lg\" href=\"#register?order={{ order.id }}\">{{{ icon('user', 18) }}} Đăng ký thành viên</a>\n</div>\n{% elif el.reason === 'agent' %}\n<div class=\"row\">\n  <span class=\"result-icon is-info\" style=\"width:44px;height:44px;margin:0\">{{{ icon('user', 22) }}}</span>\n  <div class=\"grow\"><h2 style=\"font-size:var(--fs-lg)\">Bạn đã là thành viên HOMI365</h2><p class=\"text-sm text-muted\">Đăng nhập để xem gói, mã kích hoạt và hoa hồng.</p></div>\n</div>\n<div class=\"actions\"><a class=\"btn btn-primary btn-lg btn-block\" href=\"#login\">Đăng nhập thành viên</a></div>\n{% elif el.reason === 'pending' %}\n<div class=\"row\">\n  <span class=\"result-icon is-info\" style=\"width:44px;height:44px;margin:0\">{{{ icon('clock', 22) }}}</span>\n  <div class=\"grow\"><h2 style=\"font-size:var(--fs-lg)\">Hồ sơ thành viên đang chờ duyệt</h2><p class=\"text-sm text-muted\">Trạng thái: {{ label('approval', el.registration.status) }}. Chúng tôi sẽ gửi email khi hồ sơ được duyệt.</p></div>\n</div>\n<div class=\"actions\"><a class=\"btn btn-secondary btn-lg btn-block\" href=\"#register?state=pending&phone={{ order.phone }}\">Xem trạng thái hồ sơ</a></div>\n{% else %}\n<div class=\"row\">\n  <span class=\"result-icon is-info\" style=\"width:44px;height:44px;margin:0\">{{{ icon('check-circle', 22) }}}</span>\n  <div class=\"grow\"><h2 style=\"font-size:var(--fs-lg)\">Đơn hàng thành công</h2><p class=\"text-sm text-muted\">Mã kích hoạt và hướng dẫn đã được gửi qua SMS/email. Bạn có thể đăng ký thành viên sau tại mục Đăng nhập thành viên khi đủ điều kiện.</p></div>\n</div>\n<div class=\"actions\"><button class=\"btn btn-secondary btn-lg btn-block\" onclick=\"Buyer.a03Later('{{ order.id }}', true)\">Thoát ra</button></div>\n{% endif %}\n{% endblock %}\n\n{% block partials/seller-approval-timeline %}\n<!-- Tiến trình duyệt một yêu cầu rút tiền — data: rows [{ at, text }] -->\n<ul class=\"timeline mt-2\">\n  {% each r in rows %}\n  <li><span class=\"timeline-time\">{{ dt(r.at) }}</span><span class=\"timeline-text\">{{ r.text }}</span></li>\n  {% endeach %}\n</ul>\n{% endblock %}\n\n{% block partials/seller-f1-table %}\n<!-- Bảng tuyến dưới trực tiếp (F1) — data: rows [{ d, sold, downCount }], canRecruit -->\n{% if !rows.length %}\n{{{ UI.empty('users', 'Chưa có tuyến dưới', canRecruit ? 'Khách mua qua link của bạn và đăng ký thành viên sẽ xuất hiện ở đây.' : 'Lên hạng Silver để được tuyển thành viên.') }}}\n{% else %}\n<div class=\"table-wrap\">\n  <table class=\"table\">\n    <thead><tr><th>Thành viên</th><th>Hạng</th><th class=\"num\">Luỹ kế</th><th class=\"num\">Bán tháng này</th><th class=\"num\">Tuyến dưới</th><th>Tham gia</th><th>Trạng thái</th></tr></thead>\n    <tbody>\n      {% each r in rows %}\n      <tr>\n        <td><span class=\"cell-main\">{{ r.d.fullName }}</span><span class=\"cell-sub mono\">{{ r.phone }} · {{ r.d.refCode }}</span></td>\n        <td>{{{ badge('rank', r.d.rank) }}}</td>\n        <td class=\"num\">{{ r.d.cumulativeSales }}</td>\n        <td class=\"num\">{{ r.sold }}</td>\n        <td class=\"num\">{{ r.downCount }}</td>\n        <td>{{ date(r.d.activatedAt || r.d.createdAt) }}</td>\n        <td>{{{ badge('user', r.d.status) }}}</td>\n      </tr>\n      {% endeach %}\n    </tbody>\n  </table>\n</div>\n{% endif %}\n{% endblock %}\n\n{% block partials/seller-period-seg %}\n<!-- Chọn kỳ thống kê (tuần / tháng / quý / tuỳ chọn) — data: periods, period, from, to -->\n<div class=\"row-wrap\">\n  <div class=\"seg\" role=\"group\" aria-label=\"Kỳ thống kê\">\n    {% each p in periods %}\n    <button class=\"{{ period === p.id ? 'is-active' : '' }}\" onclick=\"Seller.setPeriod('{{ p.id }}')\">{{ p.label }}</button>\n    {% endeach %}\n  </div>\n  {% if period === 'custom' %}\n  <div class=\"row\">\n    <input type=\"date\" class=\"input\" style=\"min-height:40px;width:auto\" id=\"rg-from\" value=\"{{ from }}\" aria-label=\"Từ ngày\">\n    <span>–</span>\n    <input type=\"date\" class=\"input\" style=\"min-height:40px;width:auto\" id=\"rg-to\" value=\"{{ to }}\" aria-label=\"Đến ngày\">\n    <button class=\"btn btn-secondary btn-sm\" onclick=\"Seller.applyRange()\">Áp dụng</button>\n  </div>\n  {% endif %}\n</div>\n{% endblock %}\n\n{% block partials/seller-rank-ladder %}\n<!-- Thang 6 hạng: ngưỡng luỹ kế, quyền tuyển, trạng thái so với hạng hiện tại\n     data: rows [{ id, threshold, canRecruit, isCur, state: 'done'|'current'|'ready'|'missing', missing }], rr -->\n<div class=\"table-wrap\">\n  <table class=\"table\" style=\"min-width:0\">\n    <thead><tr><th>Hạng</th><th class=\"num\">Ngưỡng luỹ kế</th><th>Quyền tuyển</th><th>Trạng thái</th></tr></thead>\n    <tbody>\n      {% each r in rows %}\n      <tr class=\"{{ r.isCur ? 'is-selected' : '' }}\">\n        <td>{{{ badge('rank', r.id) }}}</td>\n        <td class=\"num mono\">{{ r.threshold }} gói</td>\n        <td>{% if r.canRecruit %}{{{ icon('check', 16, 'text-success') }}} Được tuyển{% else %}<span class=\"text-muted\">Chỉ bán</span>{% endif %}</td>\n        <td>\n          {% if r.state === 'done' %}<span class=\"badge badge-success\">Đã đạt</span>\n          {% elif r.state === 'current' %}<span class=\"badge badge-navy\">Hạng hiện tại</span>\n          {% elif r.state === 'ready' %}<span class=\"badge badge-info\">Đủ luỹ kế · chờ xét</span>\n          {% else %}<span class=\"text-sm text-muted\">Còn thiếu <strong>{{ r.missing }}</strong> gói</span>{% endif %}\n        </td>\n      </tr>\n      {% endeach %}\n    </tbody>\n  </table>\n</div>\n<ul class=\"pkg-benefits mt-3\">\n  <li>{{{ icon('check', 16) }}}<span>Lên hạng khi <strong>tổng gói bán luỹ kế</strong> đạt ngưỡng; xét tự động cuối tháng, có thể nhảy nhiều bậc.</span></li>\n  <li>{{{ icon('check', 16) }}}<span>Giữ hạng: bán tối thiểu <strong>{{ rr.minSalesPerMonth }} gói/tháng</strong>; không đạt sẽ giáng {{ rr.demoteSteps }} bậc (không dưới Copper).</span></li>\n  <li>{{{ icon('check', 16) }}}<span>Hoa hồng mỗi gói tính theo hạng tại thời điểm đơn thanh toán; hạng cao hơn tuyến dưới nhận thêm phần chênh lệch.</span></li>\n</ul>\n{% endblock %}\n\n{% block partials/seller-tree %}\n<!-- Cây tuyến dưới (gốc) — data: nodes [node], canRecruit. node = { lv, name, rank, cumulativeSales, soldMonth, phone, locked, children[] } -->\n{% if !nodes.length %}\n{{{ UI.empty('users', 'Chưa có tuyến dưới', canRecruit ? 'Khách mua qua link của bạn và đăng ký thành viên sẽ xuất hiện ở đây.' : 'Lên hạng Silver để được tuyển thành viên.') }}}\n{% else %}\n<ul class=\"tree\">\n  {% each n in nodes %}\n  {{{ include('partials/seller-tree-node', { n: n }) }}}\n  {% endeach %}\n</ul>\n{% endif %}\n{% endblock %}\n\n{% block partials/seller-tree-node %}\n<!-- Một nút trong cây tuyến dưới (đệ quy qua include) — data: n = { lv, name, rank, cumulativeSales, soldMonth, phone, locked, children[] } -->\n<li>\n  <span class=\"tree-node\">\n    <span class=\"badge badge-{{ n.lv === 1 ? 'navy' : n.lv === 2 ? 'info' : 'neutral' }} badge-plain\">F{{ n.lv }}</span>\n    <strong>{{ n.name }}</strong>\n    {{{ badge('rank', n.rank) }}}\n    <span class=\"text-sm text-muted\">· luỹ kế {{ n.cumulativeSales }} · tháng này {{ n.soldMonth }} · <span class=\"mono\">{{ n.phone }}</span></span>\n    {% if n.locked %}{{{ badge('user', 'locked') }}}{% endif %}\n  </span>\n  {% if n.children.length %}\n  <ul class=\"tree\">\n    {% each c in n.children %}\n    {{{ include('partials/seller-tree-node', { n: c }) }}}\n    {% endeach %}\n  </ul>\n  {% endif %}\n</li>\n{% endblock %}\n\n{% block partials/seller-wd-steps %}\n<!-- Thanh 3 bước rút tiền: Số tiền → Tài khoản → Đã gửi — data: steps [{ k, l, active, done }] -->\n<div class=\"steps mb-4\">\n  {% each s, i in steps %}\n  <div class=\"step {{ s.active ? 'is-active' : '' }} {{ s.done ? 'is-done' : '' }}\"><span class=\"step-dot\">{% if s.done %}{{{ icon('check', 14) }}}{% else %}{{ i + 1 }}{% endif %}</span><span>{{ s.l }}</span></div>{% if i < 2 %}<span class=\"step-line\"></span>{% endif %}\n  {% endeach %}\n</div>\n{% endblock %}\n",
  "seller/dashboard": "<!-- dashboard · Tổng quan: tiêu đề + thanh tab (Thống kê · Hoa hồng · Tuyến) — data: u, tab, tabs, treeCount, tabHtml -->\n<div class=\"stack-lg\">\n  <div class=\"page-title\">\n    <div>\n      <h1>Xin chào, {{ u.fullName }}</h1>\n      <p class=\"row-wrap\">{{{ badge('rank', u.rank, true) }}}<span>Mã giới thiệu <span class=\"mono text-strong\">{{ u.refCode }}</span> · thành viên từ {{ date(u.activatedAt || u.createdAt) }}</span></p>\n    </div>\n  </div>\n  <div class=\"c01-tabs\">\n    <div class=\"tabs\" role=\"tablist\">\n      {% each t in tabs %}\n      <button class=\"tab {{ tab === t.id ? 'is-active' : '' }}\" role=\"tab\" aria-selected=\"{{ tab === t.id }}\" onclick=\"Seller.setTab('{{ t.id }}')\">{{{ icon(t.ico, 18) }}} {{ t.label }}{% if t.id === 'tree' %} <span class=\"count\">{{ treeCount }}</span>{% endif %}</button>\n      {% endeach %}\n    </div>\n  </div>\n  {{{ tabHtml }}}\n</div>\n\n{% block seller/dashboard-cmchart %}\n<!-- dashboard · biểu đồ hoa hồng theo ngày trong #c01-cmchart — data: rangeLabel, chartHtml -->\n<h3 class=\"mb-2\">Hoa hồng ghi nhận theo ngày (triệu đồng) · {{ rangeLabel }}</h3>\n{{{ chartHtml }}}\n{% endblock %}\n\n{% block seller/dashboard-commissions %}\n<!-- dashboard · tab Hoa hồng: 4 ô ví, biểu đồ, bộ lọc bảng kê — data: w, cw, cmKind -->\n<div class=\"stack-lg\">\n  <div class=\"card\">\n    <div class=\"card-head\">\n      <h2>Hoa hồng</h2>\n      <button class=\"btn btn-accent\" {{{ cw.ok ? '' : 'disabled' }}} title=\"{{ cw.ok ? '' : cw.message }}\" onclick=\"App.navigate('wallet?withdraw=1')\">{{{ icon('cash', 18) }}} Rút tiền</button>\n    </div>\n    <div class=\"card-body\">\n      <div class=\"stat-grid stat-grid-4\">\n        <div class=\"stat\"><div class=\"stat-label\">{{{ icon('check-circle', 16) }}} Đã ghi nhận</div><div class=\"stat-value\">{{ money(w.recorded) }}</div><div class=\"stat-sub\">Tổng hoa hồng từ khi tham gia</div></div>\n        <div class=\"stat\"><div class=\"stat-label\">{{{ icon('clock', 16) }}} Đang chờ duyệt rút</div><div class=\"stat-value text-warning\">{{ money(w.held) }}</div></div>\n        <div class=\"stat\"><div class=\"stat-label\">{{{ icon('cash', 16) }}} Đã rút</div><div class=\"stat-value\">{{ money(w.withdrawn) }}</div></div>\n        <div class=\"stat stat-navy stat-clickable\" onclick=\"App.navigate('wallet')\"><div class=\"stat-label\">{{{ icon('wallet', 16) }}} Khả dụng</div><div class=\"stat-value\">{{ money(w.available) }}</div><div class=\"stat-sub\">Xem ví {{{ icon('arrow-right', 12) }}}</div></div>\n      </div>\n      {% if !cw.ok %}<p class=\"text-sm text-muted mt-3\">{{{ icon('info', 14) }}} {{ cw.message }}</p>{% endif %}\n      <div id=\"c01-cmchart\" class=\"mt-4\"></div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <div class=\"card-head\">\n      <h2>Bảng kê hoa hồng</h2>\n      <div class=\"row-wrap\">\n        <select class=\"select\" style=\"min-height:40px;width:auto\" aria-label=\"Lọc nguồn\" onchange=\"Seller.state.cmKind=this.value; Seller.state.cmPage=1; Seller.renderCommissions()\">\n          <option value=\"\">Tất cả nguồn</option>\n          <option value=\"SELF\" {{{ cmKind === 'SELF' ? 'selected' : '' }}}>Tự bán</option>\n          <option value=\"DIFF\" {{{ cmKind === 'DIFF' ? 'selected' : '' }}}>Chênh lệch tuyến dưới</option>\n        </select>\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"Seller.exportCommissions()\">{{{ icon('download', 16) }}} Xuất Excel</button>\n      </div>\n    </div>\n    <div class=\"card-body\" id=\"c01-cm\">{{{ UI.skeletonTable(6, 5) }}}</div>\n  </div>\n</div>\n{% endblock %}\n\n{% block seller/dashboard-commissions-table %}\n<!-- dashboard · bảng kê hoa hồng trong #c01-cm (có phân trang)\n     data: rows [{ c, o, phone, source, showSeller, seller, sellerRankLabel }], pg, count, total -->\n{% if !count %}\n{{{ UI.empty('cash', 'Chưa có khoản hoa hồng trong kỳ', 'Hoa hồng ghi nhận ngay khi đơn của bạn hoặc tuyến dưới thanh toán thành công.') }}}\n{% else %}\n<div class=\"table-wrap\">\n  <table class=\"table\">\n    <thead><tr><th>Ngày</th><th>Đơn</th><th>Nguồn</th><th>Hạng lúc tính</th><th class=\"num\">Số tiền</th><th>Trạng thái</th></tr></thead>\n    <tbody>\n      {% each r in rows %}\n      <tr>\n        <td>{{ date(r.c.createdAt) }}</td>\n        <td><span class=\"cell-main mono\">{{ r.c.orderId }}</span><span class=\"cell-sub\">{% if r.o %}{{ r.o.fullName }} · {{ r.phone }}{% endif %}</span></td>\n        <td><span class=\"badge badge-{{ r.c.kind === 'SELF' ? 'navy' : 'info' }} badge-plain\">{{ r.source }}</span>{% if r.showSeller %}<span class=\"cell-sub\">bán bởi {{ r.seller.fullName }} ({{ r.sellerRankLabel }})</span>{% endif %}</td>\n        <td>{{{ badge('rank', r.c.rankAtCalc) }}}</td>\n        <td class=\"num mono text-strong\">{{ money(r.c.amount) }}</td>\n        <td>{{{ badge('commission', r.c.status) }}}</td>\n      </tr>\n      {% endeach %}\n    </tbody>\n    <tfoot><tr><th colspan=\"4\">Tổng {{ count }} khoản</th><th class=\"num\">{{ money(total) }}</th><th></th></tr></tfoot>\n  </table>\n</div>\n{{{ UI.pagination(pg, 'Seller.gotoCmPage') }}}\n{% endif %}\n{% endblock %}\n\n{% block seller/dashboard-stats %}\n<!-- dashboard · tab Thống kê: link giới thiệu, hạng & điểm, thang hạng, khung thống kê theo kỳ\n     data: u, w, rk, nx, need, pct, sold, rr, canRecruit, keepOk, refUrl, aliasUrl, publicAliasUrl, jobTime, ladderHtml, periodSegHtml -->\n<div class=\"stack-lg\">\n  <div class=\"grid-2 grid-2-wide\">\n    <div class=\"card\">\n      <div class=\"card-head\">\n        <h2>Link của bạn</h2>\n        {% if canRecruit %}<span class=\"text-sm text-muted\">Khách mua qua link được tính vào tuyến của bạn</span>{% else %}<span class=\"badge badge-warning\">Hạng Copper: chỉ bán, chưa được tuyển thành viên</span>{% endif %}\n      </div>\n      <div class=\"card-body stack\">\n        <div>\n          <div class=\"field-label mb-2\">Link giới thiệu (ref_code)</div>\n          <div class=\"ref-url\">\n            <input class=\"input\" readonly value=\"{{ refUrl }}\" aria-label=\"Link giới thiệu\" onclick=\"this.select()\">\n            <button class=\"btn btn-primary\" onclick=\"UI.copy('{{ refUrl }}', 'Đã sao chép link giới thiệu.')\">{{{ icon('copy', 18) }}} Sao chép</button>\n          </div>\n        </div>\n        <div>\n          <div class=\"field-label mb-2\">Link mua hàng cá nhân · <span class=\"mono\">{{ publicAliasUrl }}</span></div>\n          <div class=\"ref-url\">\n            <input class=\"input\" readonly value=\"{{ aliasUrl }}\" aria-label=\"Link mua hàng cá nhân\" onclick=\"this.select()\">\n            <button class=\"btn btn-secondary\" onclick=\"UI.copy('{{ aliasUrl }}', 'Đã sao chép link mua hàng cá nhân.')\">{{{ icon('copy', 18) }}} Sao chép</button>\n          </div>\n        </div>\n        <div class=\"share-row\">\n          <button class=\"btn btn-secondary share-btn\" onclick=\"Seller.shareZalo('{{ aliasUrl }}')\"><span class=\"share-mark share-zalo\">Z</span> Zalo</button>\n          <button class=\"btn btn-secondary share-btn\" onclick=\"window.open('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent('{{ aliasUrl }}'), '_blank', 'noopener')\"><span class=\"share-mark share-fb\">f</span> Facebook</button>\n          <button class=\"btn btn-secondary share-btn\" onclick=\"UI.share('{{ aliasUrl }}', 'Gói Bác sĩ 24/7 HOMI365')\">{{{ icon('share', 18) }}} Khác</button>\n        </div>\n        <div class=\"ref-qr ref-qr-inline\">\n          {{{ UI.qrSvg(aliasUrl, 150) }}}\n          <div class=\"qr-label\">QR link mua hàng cá nhân</div>\n          <button class=\"btn btn-ghost btn-sm mt-1\" onclick=\"Seller.downloadQr('{{ u.purchaseAlias }}')\">{{{ icon('download', 16) }}} Tải QR</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"stack\">\n      <div class=\"card card-tint\">\n        <div class=\"card-body\">\n          <div class=\"row-between\"><h2 style=\"font-size:var(--fs-lg)\">Hạng & điểm</h2>{{{ badge('rank', u.rank, true) }}}</div>\n          <div class=\"stat-grid mt-3\" style=\"grid-template-columns:1fr 1fr\">\n            <div><div class=\"stat-label\">Điểm tích luỹ</div><div class=\"stat-value\">{{ num(w.points) }}</div><div class=\"stat-sub\">1 điểm = 1đ hoa hồng</div></div>\n            <div><div class=\"stat-label\">Gói bán luỹ kế</div><div class=\"stat-value\">{{ num(u.cumulativeSales) }}</div><div class=\"stat-sub\">{% if nx %}Còn thiếu {{ need }} gói lên {{ nx.label }}{% else %}Hạng cao nhất{% endif %}</div></div>\n          </div>\n          {% if nx %}\n          <div class=\"progress mt-3\"><span style=\"width:{{ pct }}%\"></span></div>\n          <div class=\"text-caption mt-1\">{{ rk.label }} ({{ rk.threshold }}) → {{ nx.label }} ({{ nx.threshold }})</div>\n          {% endif %}\n          <div class=\"mt-3 {{ keepOk ? 'alert alert-success' : 'alert alert-warning' }}\">\n            {{{ icon(keepOk ? 'check-circle' : 'warning', 18) }}}\n            <div class=\"text-sm\">Tháng này đã bán <strong>{{ sold }}</strong> gói. {% if keepOk %}Đã đủ điều kiện giữ hạng tháng này.{% else %}Cần tối thiểu {{ rr.minSalesPerMonth }} gói/tháng để giữ hạng — nếu không sẽ giáng 1 bậc vào cuối tháng.{% endif %}</div>\n          </div>\n          <div class=\"mt-2 text-right\"><a href=\"#profile\" class=\"btn-link\">Lịch sử thăng/giáng hạng {{{ icon('arrow-right', 14) }}}</a></div>\n        </div>\n      </div>\n      <div class=\"card\">\n        <div class=\"card-head\"><h2 style=\"font-size:var(--fs-lg)\">Thang hạng & điều kiện lên hạng</h2><span class=\"text-sm text-muted\">Xét vào {{ jobTime }}</span></div>\n        <div class=\"card-body\">{{{ ladderHtml }}}</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <div class=\"card-head\"><h2>Thống kê</h2>{{{ periodSegHtml }}}</div>\n    <div class=\"card-body\" id=\"c01-stats\">{{{ UI.skeletonCards(2) }}}</div>\n  </div>\n</div>\n{% endblock %}\n\n{% block seller/dashboard-stats-body %}\n<!-- dashboard · nội dung #c01-stats sau khi tải: 6 ô số liệu kỳ + biểu đồ đơn/click — data: st, conversion, rangeLabel, chartHtml -->\n<div class=\"stat-grid stat-grid-6\">\n  <div class=\"stat\"><div class=\"stat-label\">{{{ icon('external', 16) }}} Lượt click</div><div class=\"stat-value\">{{ num(st.clicks) }}</div></div>\n  <div class=\"stat\"><div class=\"stat-label\">{{{ icon('inbox', 16) }}} Đơn đã đặt</div><div class=\"stat-value\">{{ num(st.orders) }}</div></div>\n  <div class=\"stat\"><div class=\"stat-label\">{{{ icon('check-circle', 16) }}} Đơn thanh toán</div><div class=\"stat-value\">{{ num(st.paid) }}</div><div class=\"stat-sub\">Chuyển đổi {{ conversion }}</div></div>\n  <div class=\"stat\"><div class=\"stat-label\">{{{ icon('bars', 16) }}} Doanh số kỳ</div><div class=\"stat-value\">{{ money(st.revenue) }}</div></div>\n  <div class=\"stat stat-accent\"><div class=\"stat-label\">{{{ icon('cash', 16) }}} Hoa hồng kỳ</div><div class=\"stat-value\">{{ money(st.commission) }}</div></div>\n  <div class=\"stat\"><div class=\"stat-label\">{{{ icon('calendar', 16) }}} Kỳ</div><div class=\"stat-value\" style=\"font-size:var(--fs-md)\">{{ rangeLabel }}</div></div>\n</div>\n<div class=\"mt-6\">\n  <h3 class=\"mb-2\">Xu hướng đơn & click</h3>\n  {{{ chartHtml }}}\n</div>\n{% endblock %}\n\n{% block seller/dashboard-tree %}\n<!-- dashboard · tab Tuyến: cây tuyến dưới 3 cấp — data: countsText, treeHtml -->\n<div class=\"stack-lg\">\n  <div class=\"card\">\n    <div class=\"card-head\"><h2>Tuyến dưới (F1 · F2 · F3)</h2><span class=\"text-sm text-muted\">{{ countsText }}</span></div>\n    <div class=\"card-body\">{{{ treeHtml }}}</div>\n  </div>\n</div>\n{% endblock %}\n",
  "seller/my-package": "<!-- my-package · Gói của tôi & mã kích hoạt — data: u, order (null nếu chưa có), pkg, code, activated, expiry, maskedPhone, methodLabel, sellerName -->\n<div class=\"page-title\"><div><h1>Gói của tôi</h1><p>Mã kích hoạt và thiết bị đã kích hoạt</p></div></div>\n{% if !order %}\n<div class=\"card\"><div class=\"card-body\">{{{ UI.empty('package', 'Chưa có gói nào', 'Tài khoản này chưa gắn với đơn hàng thanh toán thành công.') }}}</div></div>\n{% else %}\n<div class=\"grid-2 grid-2-wide\">\n  <div class=\"stack\">\n    <div class=\"card\">\n      <div class=\"card-body\">\n        {{{ Buyer.pkgHeader(pkg, { tag: 'div' }) }}}\n        <div class=\"mt-4\">\n          {% if order.licenseCode %}\n          <div class=\"code-box code-box-lg\">\n            <div class=\"grow\"><span class=\"code-label\">Mã kích hoạt</span><span class=\"code-value\">{{ order.licenseCode }}</span></div>\n            <button class=\"btn btn-secondary btn-icon\" aria-label=\"Sao chép mã kích hoạt\" onclick=\"UI.copy('{{ order.licenseCode }}', 'Đã sao chép mã kích hoạt.')\">{{{ icon('copy', 20) }}}</button>\n          </div>\n          <div class=\"row-between mt-3\"><span class=\"text-sm text-muted\">Trạng thái mã</span>{{{ badge('license', code ? code.status : 'ASSIGNED', true) }}}</div>\n          {% if code %}<div class=\"text-sm text-muted mt-1\">Thiết bị: <span class=\"mono\">{{ code.deviceSku }} · {{ code.deviceSerial || '' }}</span></div>{% endif %}\n          {% else %}\n          <div class=\"alert alert-warning\">{{{ icon('clock', 20) }}}<div><span class=\"alert-title\">Mã kích hoạt đang chờ cấp</span>Sẽ gửi qua SMS ngay khi có mã.</div></div>\n          {% endif %}\n        </div>\n        <div class=\"mt-4 alert alert-info\">{{{ icon('device', 20) }}}<div class=\"text-sm\">Kích hoạt gói bằng cách nhập mã trong <strong>ứng dụng HOMI365</strong>. Mã chỉ gắn được với 1 thiết bị.</div></div>\n        {% if order.licenseCode && !activated %}\n        <div class=\"actions\"><button class=\"btn btn-outline btn-lg btn-block\" onclick=\"Store.resendCodeSms('{{ u.id }}'); UI.toast('Đã gửi lại mã kích hoạt qua SMS tới {{ maskedPhone }}.')\">{{{ icon('sms', 18) }}} Gửi lại mã qua SMS</button></div>\n        {% endif %}\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-head\"><h2>Thiết bị đã kích hoạt</h2></div>\n      <div class=\"card-body\">\n        {% if activated %}\n        <div class=\"device\">\n          <div class=\"device-icon\">{{{ icon('device', 24) }}}</div>\n          <div class=\"grow\">\n            <div class=\"text-strong\">{{ code.device.name }}</div>\n            <div class=\"text-sm text-muted\">Mã máy <span class=\"mono\">{{ code.device.deviceId }}</span></div>\n            <div class=\"text-sm text-muted\">Kích hoạt lúc {{ dt(code.activatedAt) }}</div>\n          </div>\n          {{{ badge('license', 'ACTIVATED') }}}\n        </div>\n        <p class=\"text-sm text-muted mt-3\">License hiệu lực {{ pkg.licenseMonths }} tháng kể từ ngày kích hoạt, đến <strong>{{ expiry }}</strong>.</p>\n        {% else %}\n        {{{ UI.empty('device', 'Chưa kích hoạt trên thiết bị nào', 'Sau khi nhập mã trong ứng dụng, tên máy, mã máy và thời điểm kích hoạt hiển thị tại đây.') }}}\n        {% endif %}\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <div class=\"card-head\"><h2>Thông tin đơn hàng</h2></div>\n    <div class=\"card-body\">\n      <dl class=\"dl dl-stack\">\n        <dt>Mã đơn</dt><dd class=\"mono\">{{ order.id }}</dd>\n        <dt>Ngày mua</dt><dd>{{ dt(order.paidAt || order.createdAt) }}</dd>\n        <dt>Thanh toán</dt><dd>{{{ badge('orderStatus', order.status) }}} <span class=\"text-sm text-muted\">{{ methodLabel }}</span></dd>\n        <dt>Giao hàng (đồng hồ HW01)</dt><dd>{{{ badge('shipping', order.shipping) }}}</dd>\n        <dt>Địa chỉ nhận</dt><dd>{{ order.address }}</dd>\n        <dt>Người giới thiệu</dt><dd>{{ sellerName }}</dd>\n      </dl>\n    </div>\n  </div>\n</div>\n{% endif %}\n",
  "seller/profile": "<!-- Hồ sơ thành viên: thông tin hạng, tài khoản nhận hoa hồng, thông tin cá nhân, đổi mật khẩu\n     data: u, ref, w, rankLabel, refRankLabel, publicUrl, purchaseUrl, history [{ at, event, fromLabel, toLabel, reason }], bank { bankName, accountNo, owner }, bankOptions -->\n<div class=\"page-title\"><div><h1>Hồ sơ của tôi</h1><p>Thông tin thành viên, tài khoản nhận hoa hồng, mật khẩu</p></div></div>\n<div class=\"grid-2\">\n  <div class=\"stack\">\n    <div class=\"card\">\n      <div class=\"card-head\"><h2>Thành viên</h2>{{{ badge('rank', u.rank, true) }}}</div>\n      <div class=\"card-body\">\n        <dl class=\"dl dl-stack\">\n          <dt>Hạng hiện tại</dt><dd>{{ rankLabel }} (từ {{ date(u.rankSince) }}) · {{ num(u.cumulativeSales) }} gói luỹ kế · {{ num(w.points) }} điểm</dd>\n          <dt>Mã giới thiệu (ref_code)</dt><dd class=\"mono\">{{ u.refCode }}</dd>\n          <dt>Link mua hàng cá nhân</dt><dd><span class=\"mono\">{{ publicUrl }}</span> <button class=\"btn-link\" onclick=\"UI.copy('{{ purchaseUrl }}')\">Sao chép</button></dd>\n          <dt>Người giới thiệu</dt><dd>{% if ref %}{{ ref.fullName }} · <span class=\"mono\">{{ ref.refCode }}</span> · {{ refRankLabel }}{% else %}Không có (thành viên gốc){% endif %}</dd>\n          <dt>Email</dt><dd>{{ u.email || '—' }}</dd>\n          <dt>Điều khoản đã chấp nhận</dt><dd>Phiên bản {{ u.tcConsent ? u.tcConsent.version : '—' }} · {% if u.tcConsent %}{{ dt(u.tcConsent.at) }}{% endif %}</dd>\n          <dt>Trạng thái</dt><dd>{{{ badge('user', u.status) }}}</dd>\n        </dl>\n        <h3 class=\"mt-4 mb-2\">Lịch sử thăng / giáng hạng</h3>\n        <ul class=\"timeline\">\n          {% each h in history %}\n          <li><span class=\"timeline-time\">{{ dt(h.at) }}</span><span class=\"timeline-text\">{{{ badge('rankEvent', h.event) }}} {% if h.fromLabel %}{{ h.fromLabel }} → {% endif %}{{ h.toLabel }} · {{ h.reason }}</span></li>\n          {% endeach %}\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-head\"><h2>Tài khoản nhận hoa hồng</h2></div>\n      <div class=\"card-body\">\n        <form novalidate onsubmit=\"Seller.saveBank(event)\">\n          <div class=\"form-grid form-grid-2\">\n            {{{ UI.field({ id: 'bk-bank', label: 'Ngân hàng', required: true, type: 'select', value: bank.bankName, options: bankOptions }) }}}\n            {{{ UI.field({ id: 'bk-acc', label: 'Số tài khoản', required: true, mono: true, value: bank.accountNo, attrs: 'inputmode=\"numeric\"' }) }}}\n          </div>\n          <div class=\"mt-4\">{{{ UI.field({ id: 'bk-owner', label: 'Chủ tài khoản', required: true, value: bank.owner, hint: 'Viết in hoa không dấu, trùng họ tên đăng ký' }) }}}</div>\n          <p class=\"text-caption mt-2\">Thay đổi được ghi nhận vào nhật ký kiểm toán và áp dụng cho các yêu cầu rút tiền mới.</p>\n          <div class=\"actions\"><button class=\"btn btn-primary\">Lưu tài khoản</button></div>\n        </form>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"stack\">\n    <div class=\"card\">\n      <div class=\"card-head\"><h2>Thông tin cá nhân</h2></div>\n      <div class=\"card-body\">\n        <form novalidate onsubmit=\"Seller.saveProfile(event)\">\n          {{{ UI.field({ id: 'pf-name', label: 'Họ và tên', required: true, value: u.fullName }) }}}\n          {{{ UI.field({ id: 'pf-phone', label: 'Số điện thoại (định danh, không đổi)', value: u.phone, mono: true, attrs: 'readonly' }) }}}\n          {{{ UI.field({ id: 'pf-email', label: 'Email', type: 'email', required: true, value: u.email }) }}}\n          {{{ UI.field({ id: 'pf-address', label: 'Địa chỉ', type: 'textarea', rows: 2, value: u.address }) }}}\n          <div class=\"actions\"><button class=\"btn btn-primary btn-lg\">Lưu thay đổi</button></div>\n        </form>\n        <div class=\"section mt-6\" style=\"border-top:1px solid var(--border-soft);padding-top:20px\">\n          <h3 class=\"mb-3\">Đổi mật khẩu</h3>\n          <form novalidate onsubmit=\"Seller.changePassword(event)\">\n            {{{ UI.field({ id: 'pw-old', label: 'Mật khẩu hiện tại', type: 'password', required: true }) }}}\n            <div class=\"form-grid form-grid-2 mt-4\">\n              {{{ UI.field({ id: 'pw-new', label: 'Mật khẩu mới', type: 'password', required: true, hint: 'Tối thiểu 8 ký tự, có chữ và số' }) }}}\n              {{{ UI.field({ id: 'pw-new2', label: 'Nhập lại mật khẩu mới', type: 'password', required: true }) }}}\n            </div>\n            <div class=\"actions\"><button class=\"btn btn-outline btn-lg\">Đổi mật khẩu</button></div>\n          </form>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n",
  "seller/wallet": "<!-- wallet · Ví & rút tiền: hero số dư, panel rút tiền (#wd-panel), tab Lịch sử / Sổ hoa hồng\n     data: u, w, cw, wdStep, wdTab, wdCount, maxPerMonth, payoutNote, tabHtml -->\n<div class=\"stack-lg\">\n  <div class=\"page-title\"><div><h1>Ví & rút tiền</h1><p>Hoa hồng ghi nhận ngay khi đơn thanh toán · rút tối đa {{ maxPerMonth }} lần/tháng</p></div></div>\n  <div class=\"grid-2 grid-2-wide\">\n    <div class=\"wallet-hero\">\n      <div class=\"label\">Số dư khả dụng</div>\n      <div class=\"amount\">{{ money(w.available) }}</div>\n      <div class=\"split\" style=\"grid-template-columns:repeat(3,1fr)\">\n        <div><div class=\"label\">Đã ghi nhận</div><div class=\"v\">{{ money(w.recorded) }}</div></div>\n        <div><div class=\"label\">Đang chờ duyệt rút</div><div class=\"v\">{{ money(w.held) }}</div></div>\n        <div><div class=\"label\">Đã rút</div><div class=\"v\">{{ money(w.withdrawn) }}</div></div>\n      </div>\n      <button class=\"btn btn-accent btn-lg btn-block\" onclick=\"Seller.wdStart()\" {{{ cw.ok ? '' : 'disabled' }}}>{{{ icon('cash', 20) }}} Tạo yêu cầu rút tiền</button>\n      {% if !cw.ok %}<div class=\"text-sm mt-2\" style=\"color:var(--sky-200)\">{{ cw.message }}{% if cw.reason === 'bank' %} <a href=\"#profile\" style=\"color:var(--teal-300)\">Cập nhật hồ sơ</a>{% endif %}</div>{% endif %}\n    </div>\n    <div id=\"wd-panel\">\n      {% if !wdStep %}\n      <div class=\"card card-soft\">\n        <div class=\"card-body\">\n          <h3>Quy định rút tiền</h3>\n          <ul class=\"pkg-benefits\">\n            <li>{{{ icon('check', 16) }}}<span>Tối đa <strong>{{ maxPerMonth }} lần/tháng</strong>, số tiền không vượt quá số dư khả dụng.</span></li>\n            <li>{{{ icon('check', 16) }}}<span>Yêu cầu được <strong>duyệt 2 lớp</strong> bởi bộ phận quản trị; theo dõi tiến trình 0/2 → 1/2 → Đã duyệt.</span></li>\n            <li>{{{ icon('check', 16) }}}<span>{{ payoutNote }} vào tài khoản ngân hàng trong hồ sơ.</span></li>\n            <li>{{{ icon('check', 16) }}}<span>Nếu bị từ chối, số tiền hoàn về khả dụng và bạn thấy lý do tại đây.</span></li>\n          </ul>\n        </div>\n      </div>\n      {% endif %}\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <div class=\"tabs\" role=\"tablist\">\n      <button class=\"tab {{ wdTab === 'requests' ? 'is-active' : '' }}\" onclick=\"Seller.state.wdTab='requests'; App.reload()\">{{{ icon('file', 18) }}} Lịch sử rút tiền <span class=\"count\">{{ wdCount }}</span></button>\n      <button class=\"tab {{ wdTab === 'ledger' ? 'is-active' : '' }}\" onclick=\"Seller.state.wdTab='ledger'; App.reload()\">{{{ icon('history', 18) }}} Sổ hoa hồng</button>\n    </div>\n    <div class=\"card-body\">{{{ tabHtml }}}</div>\n  </div>\n</div>\n\n{% block seller/wallet-ledger %}\n<!-- wallet · tab Sổ hoa hồng (tối đa 40 dòng) — data: rows [{ r, desc, sign, cls }] -->\n{% if !rows.length %}\n{{{ UI.empty('history', 'Chưa có biến động') }}}\n{% else %}\n<ul class=\"ledger\">\n  {% each x in rows %}\n  <li>\n    <div>\n      <div class=\"ledger-desc\">{{ x.desc }}</div>\n      <div class=\"ledger-meta\">{{ dt(x.r.at) }} · <span class=\"mono\">{{ x.r.ref }}</span></div>\n    </div>\n    <div class=\"ledger-amt {{ x.cls }}\">{{ x.sign }}{{ money(x.r.amount) }}<span class=\"ledger-bal\">Số dư {{ money(x.r.balance) }}</span></div>\n  </li>\n  {% endeach %}\n</ul>\n{% endif %}\n{% endblock %}\n\n{% block seller/wallet-requests %}\n<!-- wallet · tab Lịch sử rút tiền — data: list [{ w, maskedAccount, rejectReason, timelineHtml }] -->\n{% if !list.length %}\n{{{ UI.empty('cash', 'Chưa có yêu cầu rút tiền', 'Bấm \"Tạo yêu cầu rút tiền\" khi có số dư khả dụng.') }}}\n{% else %}\n<div class=\"stack\">\n  {% each x in list %}\n  <div class=\"order-card\">\n    <div class=\"order-card-head\">\n      <div><div class=\"text-sm text-muted\">Yêu cầu</div><div class=\"mono text-strong\">{{ x.w.id }}</div></div>\n      <div class=\"text-right\"><div class=\"text-strong\">{{ money(x.w.amount) }}</div><div class=\"text-sm text-muted\">{{ dt(x.w.createdAt) }}</div></div>\n    </div>\n    <div class=\"status-row\">{{{ badge('withdrawal', x.w.status, true) }}}<span class=\"text-sm text-muted\">Nhận về {{ x.w.bank.bankName }} · <span class=\"mono\">{{ x.maskedAccount }}</span></span></div>\n    {% if x.w.status === 'REJECTED' %}\n    <div class=\"alert alert-error mt-3\">{{{ icon('x-circle', 18) }}}<div class=\"text-sm\"><span class=\"alert-title\">Lý do từ chối</span>{{ x.rejectReason }}</div></div>\n    {% endif %}\n    <details class=\"feature mt-2\">\n      <summary>Tiến trình duyệt</summary>\n      {{{ x.timelineHtml }}}\n    </details>\n  </div>\n  {% endeach %}\n</div>\n{% endif %}\n{% endblock %}\n\n{% block seller/wallet-withdraw %}\n<!-- wallet · panel rút tiền (#wd-panel) theo bước form / confirm / done\n     data: step, steps, u, w, d (draft), wd (yêu cầu vừa tạo), quick [số tiền gợi ý], maxPerMonth, payoutNoteLower -->\n{% if step === 'form' %}\n<div class=\"card\">\n  <div class=\"card-head\"><h2>Tạo yêu cầu rút tiền</h2><button class=\"btn btn-ghost btn-sm\" onclick=\"Seller.wdCancel()\">Huỷ</button></div>\n  <div class=\"card-body\">\n    {{{ include('partials/seller-wd-steps', { steps: steps }) }}}\n    <form novalidate onsubmit=\"Seller.wdSubmitForm(event)\">\n      {{{ UI.field({ id: 'wd-amount', label: 'Số tiền muốn rút', required: true, mono: true, value: d.amount, placeholder: '0', hint: 'Khả dụng ' + money(w.available), attrs: 'inputmode=\"numeric\"' }) }}}\n      <div class=\"quick-amounts mt-2\">\n        {% each a in quick %}\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\" onclick=\"document.getElementById('wd-amount').value='{{ a }}'\">{{ money(a) }}</button>\n        {% endeach %}\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\" onclick=\"document.getElementById('wd-amount').value='{{ w.available }}'\">Rút hết</button>\n      </div>\n      <p class=\"text-caption mt-3\">Chỉ được {{ maxPerMonth }} yêu cầu/tháng. Số tiền được tạm giữ cho đến khi xử lý xong.</p>\n      <div class=\"actions\"><button class=\"btn btn-primary btn-lg btn-block\">Tiếp tục {{{ icon('arrow-right', 18) }}}</button></div>\n    </form>\n  </div>\n</div>\n{% elif step === 'confirm' %}\n<div class=\"card\">\n  <div class=\"card-head\"><h2>Xác nhận tài khoản nhận</h2><button class=\"btn btn-ghost btn-sm\" onclick=\"Seller.wdCancel()\">Huỷ</button></div>\n  <div class=\"card-body\">\n    {{{ include('partials/seller-wd-steps', { steps: steps }) }}}\n    <div class=\"modal-summary\">\n      <dl><dt>Số tiền</dt><dd>{{ money(d.amount) }}</dd><dt>Ngân hàng</dt><dd>{{ u.bank.bankName }}</dd><dt>Số tài khoản</dt><dd class=\"mono\">{{ u.bank.accountNo }}</dd><dt>Chủ tài khoản</dt><dd>{{ u.bank.owner }}</dd></dl>\n    </div>\n    <p class=\"text-sm text-muted mt-3\">Tài khoản lấy từ hồ sơ đăng ký. Sai thông tin? <a href=\"#profile\">Sửa tại Hồ sơ</a> trước khi gửi.</p>\n    <div class=\"actions actions-row\">\n      <button class=\"btn btn-secondary btn-lg\" onclick=\"Seller.state.wdStep='form'; Seller.wdRender()\">Quay lại</button>\n      <button class=\"btn btn-primary btn-lg\" onclick=\"Seller.wdConfirm()\">{{{ icon('check', 18) }}} Gửi yêu cầu</button>\n    </div>\n  </div>\n</div>\n{% elif step === 'done' %}\n<div class=\"card\">\n  <div class=\"card-body\">\n    {{{ include('partials/seller-wd-steps', { steps: steps }) }}}\n    <div class=\"text-center stack\">\n      <div class=\"result-icon is-success\" style=\"margin:0 auto\">{{{ icon('check-circle', 34) }}}</div>\n      <h2>Đã gửi yêu cầu rút tiền</h2>\n      <p class=\"text-muted\">Mã <span class=\"mono text-strong\">{{ wd.id }}</span> · {{ money(wd.amount) }} · trạng thái <strong>Chờ duyệt (0/2)</strong>. Sau khi 2 lớp duyệt, công ty chi trả {{ payoutNoteLower }}.</p>\n      <div class=\"actions\"><button class=\"btn btn-primary btn-lg\" onclick=\"Seller.state.wdStep=null; Seller.state.wdTab='requests'; App.reload()\">Xem lịch sử rút tiền</button></div>\n    </div>\n  </div>\n</div>\n{% endif %}\n{% endblock %}\n"
};
